  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/050_personalizacion.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 050: personalización
--
-- Por qué: la app ya sabe mucho de cada atleta, pero le habla a todos igual. Con esto, cada atleta puede decir cómo
-- quiere que le llamemos, su porqué (una frase suya que la app le recuerda al volver tras unos días sin entrenar),
-- sus tres ejercicios, el enlace a su música y su cumpleaños (día y mes, sin el año); y el coach deja escritos unos
-- mensajes que salen solos en los momentos importantes (un récord, un bloque terminado, un hito de la racha, la
-- vuelta tras un parón y el cumpleaños). Y la música: su canción de récord, cuántas veces abre su música desde una
-- sesión (para «Tu mes» y «Tu año») y las listas que enlaza el coach (por tipo de sesión, de descarga, del equipo, al
-- ritmo de cada cardio, o para una sesión o un bloque concretos). Sin iniciar sesión con Spotify: solo enlaces.
--
-- Qué hace:
--   * personal_atleta: una fila por atleta. Todo opcional.
--   * personal_mio(): el atleta lee lo suyo. personal_guardar(datos): lo guarda (sustituye la fila; si está de baja,
--     no). Con las mismas comprobaciones que la app (logica/personal.js).
--   * personal_atletas(): solo el coach; lo de cada atleta (para su ficha y para avisarle de los cumpleaños).
--   * mensajes_coach: un texto por momento, con {nombre}, {ejercicio} y {semanas}. mensajes_coach(): los leen el
--     coach y sus atletas. mensaje_coach_guardar(momento, texto): solo el coach; con el texto vacío, lo quita.
--   * musica_coach: un enlace por clave (familia:empuje…, descarga, equipo, ritmo:carrera…, sesion:<id>, bloque:<id>).
--     musica_coach_lista() y musica_coach_guardar(clave, url): solo el coach. musica_para(sesion, bloque): lo general
--     y, de una sesión o un bloque, solo si son suyos (o el coach). personal_musica_abierta(): suma una al mes en curso.
-- Nadie lee ni escribe las tablas directamente. Al borrar la ficha de un atleta, lo suyo se va con ella.
-- Sin esta migración, la app no enseña nada de esto y todo lo demás sigue igual.
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 049 (o con instalar.sql en una
-- base nueva). Se puede repetir sin romper nada.
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 50 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 050 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 50;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 49) then  -- (2) la migración previa
    raise exception 'Antes de la 050 hace falta la 049: ejecútala primero (o usa supabase/instalar.sql en una base nueva).';
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. Lo de cada atleta
-- ---------------------------------------------------------------------
create table if not exists public.personal_atleta (
  atleta_id      uuid primary key references public.atletas(id) on delete cascade,
  apodo          text,
  porque         text,
  favoritos      uuid[] not null default '{}',
  musica_url     text,
  cancion_url    text,
  musica_aperturas jsonb not null default '{}'::jsonb,
  cumple_mes     smallint,
  cumple_dia     smallint,
  actualizado_en timestamptz not null default now()
);
alter table public.personal_atleta add column if not exists cancion_url text;
alter table public.personal_atleta add column if not exists musica_aperturas jsonb not null default '{}'::jsonb;
alter table public.personal_atleta drop constraint if exists personal_atleta_valido;
alter table public.personal_atleta add constraint personal_atleta_valido check (
  (apodo is null or char_length(apodo) between 1 and 30)
  and (porque is null or char_length(porque) between 1 and 140)
  and cardinality(favoritos) <= 3
  and (musica_url is null or (char_length(musica_url) <= 300 and musica_url ~* '^https://(open\.spotify\.com|spotify\.link|music\.apple\.com|music\.youtube\.com|(www\.|m\.)?youtube\.com|youtu\.be|music\.amazon\.(es|com)|(www\.)?deezer\.com|link\.deezer\.com|(www\.)?tidal\.com|listen\.tidal\.com)/[^[:space:]<>"'']*$'))
  and array_position(favoritos, null) is null
  and ((cumple_mes is null) = (cumple_dia is null))
  and (cancion_url is null or (char_length(cancion_url) <= 300 and cancion_url ~* '^https://(open\.spotify\.com|spotify\.link|music\.apple\.com|music\.youtube\.com|(www\.|m\.)?youtube\.com|youtu\.be|music\.amazon\.(es|com)|(www\.)?deezer\.com|link\.deezer\.com|(www\.)?tidal\.com|listen\.tidal\.com)/[^[:space:]<>"'']*$'
       and (cancion_url !~* '^https://open\.spotify\.com/' or cancion_url ~ '^https://open\.spotify\.com/(intl-[a-z-]+/)?track/')))
  and jsonb_typeof(musica_aperturas) = 'object'
  and ((cumple_mes is null and cumple_dia is null)
       or (cumple_mes between 1 and 12 and cumple_dia between 1 and
           (case when cumple_mes = 2 then 29 when cumple_mes in (4, 6, 9, 11) then 30 else 31 end)))
);
comment on table public.personal_atleta is 'Lo que cada atleta elige para su app: apodo, porqué, tres ejercicios, su música y su cumpleaños (día y mes). Solo por sus funciones.';

-- Lo que devuelven las funciones (sin el atleta_id para el propio atleta)
create or replace function fbe_privado.personal_json(p public.personal_atleta) returns jsonb
language sql stable set search_path = '' as $$
  select case when p.atleta_id is null then null else jsonb_build_object(
    'apodo', p.apodo, 'porque', p.porque, 'favoritos', to_jsonb(p.favoritos), 'musica_url', p.musica_url,
    'cancion_url', p.cancion_url, 'musica_aperturas', p.musica_aperturas,
    'cumple_mes', p.cumple_mes, 'cumple_dia', p.cumple_dia, 'actualizado_en', p.actualizado_en) end;
$$;

create or replace function public.personal_mio() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id(); v public.personal_atleta;
begin
  if v_atleta is null then return null; end if;
  select * into v from public.personal_atleta where atleta_id = v_atleta;
  if not found then return null; end if;
  return fbe_privado.personal_json(v);
end $$;
comment on function public.personal_mio() is 'Lo que el atleta ha elegido para su app (o null).';

create or replace function public.personal_guardar(p_datos jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_atleta uuid := public.mi_atleta_id();
  v_apodo text; v_porque text; v_musica text; v_cancion text; v_mes smallint; v_dia smallint; v_fav uuid[];
  v public.personal_atleta;
begin
  if v_atleta is null then raise exception 'Solo el atleta guarda lo suyo'; end if;
  if exists (select 1 from public.atletas where id = v_atleta and estado = 'baja') then
    raise exception 'Tu cuenta está de baja: puedes ver y descargar tus datos, pero no añadir ni cambiar nada';
  end if;
  if p_datos is null or jsonb_typeof(p_datos) <> 'object' then raise exception 'Faltan los datos'; end if;
  if coalesce(jsonb_typeof(p_datos -> 'apodo'), 'null') not in ('string', 'null') or coalesce(jsonb_typeof(p_datos -> 'porque'), 'null') not in ('string', 'null')
     or coalesce(jsonb_typeof(p_datos -> 'musica_url'), 'null') not in ('string', 'null') or coalesce(jsonb_typeof(p_datos -> 'cancion_url'), 'null') not in ('string', 'null') then
    raise exception 'Datos no válidos';
  end if;
  -- textos: sin saltos ni espacios de más; vacíos, nada
  v_apodo := nullif(btrim(regexp_replace(coalesce(p_datos ->> 'apodo', ''), '[[:space:][:cntrl:]]+', ' ', 'g')), '');
  v_porque := nullif(btrim(regexp_replace(coalesce(p_datos ->> 'porque', ''), '[[:space:][:cntrl:]]+', ' ', 'g')), '');
  v_musica := nullif(btrim(coalesce(p_datos ->> 'musica_url', '')), '');
  v_cancion := nullif(btrim(coalesce(p_datos ->> 'cancion_url', '')), '');
  begin
    v_mes := nullif(p_datos ->> 'cumple_mes', '')::smallint;
    v_dia := nullif(p_datos ->> 'cumple_dia', '')::smallint;
  exception when others then raise exception 'Fecha de cumpleaños no válida'; end;
  if (v_mes is null) <> (v_dia is null) or (v_mes is not null and (v_mes not between 1 and 12 or v_dia not between 1 and
      (case when v_mes = 2 then 29 when v_mes in (4, 6, 9, 11) then 30 else 31 end))) then
    raise exception 'Fecha de cumpleaños no válida: hacen falta el día y el mes';
  end if;
  if char_length(v_apodo) > 30 then raise exception 'Cómo quieres que te llamemos: como mucho 30 caracteres'; end if;
  if char_length(v_porque) > 140 then raise exception 'Tu porqué: como mucho 140 caracteres'; end if;
  if v_musica is not null and (char_length(v_musica) > 300 or v_musica !~* '^https://(open\.spotify\.com|spotify\.link|music\.apple\.com|music\.youtube\.com|(www\.|m\.)?youtube\.com|youtu\.be|music\.amazon\.(es|com)|(www\.)?deezer\.com|link\.deezer\.com|(www\.)?tidal\.com|listen\.tidal\.com)/[^[:space:]<>"'']*$') then
    raise exception 'Ese enlace de música no vale: pega el de Spotify, Apple Music, YouTube Music, Amazon Music, Deezer o Tidal';
  end if;
  if v_cancion is not null and (char_length(v_cancion) > 300 or v_cancion !~* '^https://(open\.spotify\.com|spotify\.link|music\.apple\.com|music\.youtube\.com|(www\.|m\.)?youtube\.com|youtu\.be|music\.amazon\.(es|com)|(www\.)?deezer\.com|link\.deezer\.com|(www\.)?tidal\.com|listen\.tidal\.com)/[^[:space:]<>"'']*$'
      or (v_cancion ~* '^https://open\.spotify\.com/' and v_cancion !~ '^https://open\.spotify\.com/(intl-[a-z-]+/)?track/')) then
    raise exception 'Esa canción no vale: pega el enlace de una canción (en Spotify, de una canción, no de una lista)';
  end if;
  if jsonb_typeof(coalesce(p_datos -> 'favoritos', '[]'::jsonb)) <> 'array' then raise exception 'Favoritos no válidos'; end if;
  if jsonb_array_length(coalesce(p_datos -> 'favoritos', '[]'::jsonb)) > 3 then raise exception 'Como mucho 3 ejercicios'; end if;
  begin
    -- (sin huecos ni repetidos, en el orden en que vienen)
    select coalesce(array_agg(u order by o), '{}') into v_fav
      from (select x::uuid as u, min(n) as o
              from jsonb_array_elements_text(coalesce(p_datos -> 'favoritos', '[]'::jsonb)) with ordinality as t(x, n)
             where x is not null group by x::uuid) f;
  exception when others then raise exception 'Favoritos no válidos'; end;
  insert into public.personal_atleta as t (atleta_id, apodo, porque, favoritos, musica_url, cancion_url, cumple_mes, cumple_dia, actualizado_en)
    values (v_atleta, v_apodo, v_porque, v_fav, v_musica, v_cancion, v_mes, v_dia, now())
  on conflict (atleta_id) do update set apodo = excluded.apodo, porque = excluded.porque, favoritos = excluded.favoritos,
    musica_url = excluded.musica_url, cancion_url = excluded.cancion_url, cumple_mes = excluded.cumple_mes, cumple_dia = excluded.cumple_dia, actualizado_en = now()
  returning * into v;
  return fbe_privado.personal_json(v);
end $$;
comment on function public.personal_guardar(jsonb) is 'El atleta guarda lo que elige para su app (sustituye lo anterior).';

create or replace function public.personal_atletas() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  return coalesce((select jsonb_agg(fbe_privado.personal_json(p) || jsonb_build_object('atleta_id', p.atleta_id) order by p.atleta_id)
                   from public.personal_atleta p), '[]'::jsonb);
end $$;
comment on function public.personal_atletas() is 'Lo de cada atleta (apodo, porqué, favoritos, música y cumpleaños). Solo el coach.';

-- ---------------------------------------------------------------------
-- 2. Los mensajes del coach para los momentos importantes
-- ---------------------------------------------------------------------
create table if not exists public.mensajes_coach (
  momento        text primary key check (momento in ('record', 'bloque', 'racha', 'vuelta', 'cumple')),
  texto          text not null check (char_length(texto) between 1 and 400),
  actualizado_en timestamptz not null default now()
);
comment on table public.mensajes_coach is 'Lo que el coach deja escrito para cada momento (récord, bloque terminado, hito de racha, vuelta tras un parón, cumpleaños). Solo por sus funciones.';

create or replace function public.mensajes_coach() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.es_coach() and public.mi_atleta_id() is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('momento', m.momento, 'texto', m.texto, 'actualizado_en', m.actualizado_en) order by m.momento)
                   from public.mensajes_coach m), '[]'::jsonb);
end $$;
comment on function public.mensajes_coach() is 'Los mensajes del coach para cada momento. Los leen el coach y sus atletas.';

create or replace function public.mensaje_coach_guardar(p_momento text, p_texto text) returns void
language plpgsql security definer set search_path = '' as $$
declare v text := nullif(btrim(coalesce(p_texto, '')), '');
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  if p_momento is null or p_momento not in ('record', 'bloque', 'racha', 'vuelta', 'cumple') then raise exception 'Momento no válido'; end if;
  if v is null then delete from public.mensajes_coach where momento = p_momento; return; end if;
  if char_length(v) > 400 then raise exception 'Como mucho 400 caracteres'; end if;
  insert into public.mensajes_coach (momento, texto, actualizado_en) values (p_momento, v, now())
    on conflict (momento) do update set texto = excluded.texto, actualizado_en = now();
end $$;
comment on function public.mensaje_coach_guardar(text, text) is 'El coach guarda (o, con el texto vacío, quita) el mensaje de un momento.';

-- Cuántas veces abre su música desde una sesión: una más en el mes en curso (de Madrid). Como mucho 500 al mes.
create or replace function public.personal_musica_abierta() returns void
language plpgsql security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id(); v_mes text := to_char(now() at time zone 'Europe/Madrid', 'YYYY-MM');
begin
  if v_atleta is null then return; end if;
  if exists (select 1 from public.atletas where id = v_atleta and estado = 'baja') then return; end if;
  insert into public.personal_atleta (atleta_id, musica_aperturas) values (v_atleta, jsonb_build_object(v_mes, 1))
  on conflict (atleta_id) do update set musica_aperturas = public.personal_atleta.musica_aperturas
    || jsonb_build_object(v_mes, least(500, coalesce((public.personal_atleta.musica_aperturas ->> v_mes)::int, 0) + 1))
    where coalesce((public.personal_atleta.musica_aperturas ->> v_mes)::int, 0) < 500;
end $$;
comment on function public.personal_musica_abierta() is 'El atleta abre su música desde una sesión: suma una al mes en curso.';

-- ---------------------------------------------------------------------
-- 3. La música que enlaza el coach
-- ---------------------------------------------------------------------
create table if not exists public.musica_coach (
  clave          text primary key,
  url            text not null,
  actualizado_en timestamptz not null default now()
);
alter table public.musica_coach drop constraint if exists musica_coach_valida;
alter table public.musica_coach add constraint musica_coach_valida check (
  clave ~ '^(familia:(empuje|tiron|pierna|core|fullbody|cardio|movilidad)|descarga|equipo|ritmo:(carrera|andar|bici|eliptica|remo|nadar|cuerda)|sesion:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|bloque:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$'
  and char_length(url) <= 300 and url ~* '^https://(open\.spotify\.com|spotify\.link|music\.apple\.com|music\.youtube\.com|(www\.|m\.)?youtube\.com|youtu\.be|music\.amazon\.(es|com)|(www\.)?deezer\.com|link\.deezer\.com|(www\.)?tidal\.com|listen\.tidal\.com)/[^[:space:]<>"'']*$'
);
comment on table public.musica_coach is 'Las listas que enlaza el coach (por tipo de sesión, descarga, equipo, ritmo de cada cardio, una sesión o un bloque). Solo por sus funciones.';

create or replace function public.musica_coach_lista() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  return coalesce((select jsonb_object_agg(m.clave, m.url) from public.musica_coach m), '{}'::jsonb);
end $$;
comment on function public.musica_coach_lista() is 'Todo lo que ha enlazado el coach ({ clave: url }). Solo el coach.';

create or replace function public.musica_coach_guardar(p_clave text, p_url text) returns void
language plpgsql security definer set search_path = '' as $$
declare v text := nullif(btrim(coalesce(p_url, '')), '');
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  if p_clave is null or p_clave !~ '^(familia:(empuje|tiron|pierna|core|fullbody|cardio|movilidad)|descarga|equipo|ritmo:(carrera|andar|bici|eliptica|remo|nadar|cuerda)|sesion:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|bloque:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$' then
    raise exception 'Clave no válida';
  end if;
  if v is null then delete from public.musica_coach where clave = p_clave; return; end if;
  insert into public.musica_coach (clave, url, actualizado_en) values (p_clave, v, now())
    on conflict (clave) do update set url = excluded.url, actualizado_en = now();
end $$;
comment on function public.musica_coach_guardar(text, text) is 'El coach enlaza (o, vacío, quita) una lista.';

-- Lo general (familias, descarga, equipo, ritmos) y lo de esa sesión y ese bloque, si son del que pregunta (o el coach)
create or replace function public.musica_para(p_sesion uuid default null, p_bloque uuid default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_coach boolean := public.es_coach(); v_atleta uuid := public.mi_atleta_id(); v_ses boolean := false; v_blo boolean := false;
begin
  if not v_coach and v_atleta is null then return '{}'::jsonb; end if;
  if p_sesion is not null then v_ses := v_coach or public.atleta_de_sesion(p_sesion) = v_atleta; end if;
  if p_bloque is not null then v_blo := v_coach or exists (select 1 from public.bloques b where b.id = p_bloque and b.atleta_id = v_atleta); end if;
  return coalesce((select jsonb_object_agg(m.clave, m.url) from public.musica_coach m
    where m.clave !~ '^(sesion|bloque):'
       or (v_ses and m.clave = 'sesion:' || p_sesion::text)
       or (v_blo and m.clave = 'bloque:' || p_bloque::text)), '{}'::jsonb);
end $$;
comment on function public.musica_para(uuid, uuid) is 'La música del coach para una sesión: lo general y lo de esa sesión y ese bloque (si son suyos).';

-- Nadie toca las tablas directamente
alter table public.personal_atleta enable row level security;
alter table public.mensajes_coach enable row level security;
alter table public.musica_coach enable row level security;
revoke all on public.personal_atleta, public.mensajes_coach, public.musica_coach from public, anon, authenticated;

-- Permisos (como al final de 003 a 049)
revoke truncate, references, trigger on all tables in schema public from public, anon, authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated, service_role;
revoke execute on function public.crear_recordatorios(timestamptz), public.notificaciones_por_enviar(integer, boolean),
  public.notificaciones_resultado(jsonb) from public, anon, authenticated;
revoke all on all functions in schema fbe_privado from public, anon, authenticated;

insert into public.fbe_migraciones (numero) values (50)  -- (3) número de esta migración
  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/051_integraciones.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 051: integraciones (Salud del iPhone, calendario que se actualiza solo y WhatsApp)
--
-- Por qué: la app es una web, y Apple solo deja entrar en Salud a las apps de la App Store. El puente es la app
-- Atajos del iPhone: un atajo que el coach prepara una vez y cada atleta instala con un toque lee de Salud sus
-- pasos, su sueño, su frecuencia cardiaca en reposo, su variabilidad (HRV) y su peso, y los manda a la función
-- «integraciones» con su enlace personal. Con eso el check-in viene relleno, el hábito de pasos se apunta solo y el
-- coach ve cómo duerme sin preguntarle. Otro atajo hace lo contrario: apunta en Salud el entreno que acaba de hacer.
-- Y el calendario: una dirección personal a la que su calendario (el del iPhone o Google) se suscribe; cuando el
-- plan cambia, el calendario cambia solo.
--
-- Qué hace:
--   * integraciones: una fila por atleta con la huella (sha-256) de sus dos enlaces personales (nunca el enlace) y
--     las opciones del calendario. integraciones_mias(): el atleta ve qué tiene conectado y los atajos del coach.
--     integracion_crear(tipo, opciones): crea un enlace nuevo (el anterior deja de valer) y lo devuelve UNA vez.
--     calendario_opciones(opciones): cambia la hora, la duración y el aviso sin cambiar el enlace.
--     integracion_quitar(tipo, borrar): lo desconecta (y, si quiere, borra lo que llegó de Salud).
--   * salud_diaria: un día por fila (pasos, minutos de sueño, FC en reposo, HRV, peso). salud_diaria_de(atleta,
--     desde, hasta): la lee el propio atleta o el coach.
--   * salud_recibir(enlace, días) y calendario_de(enlace): SOLO la función «integraciones» (clave de servicio).
--     salud_recibir guarda los días, apunta los pasos en su hábito de pasos (si lo tiene), las horas de sueño en
--     el de sueño (si no las apuntó él) y el peso en sus pesos (si ese día no hay otro). Hace falta su
--     consentimiento de datos de salud y que no esté de baja.
--   * atajos_coach: los dos enlaces de iCloud de los atajos del coach. atajo_guardar(clave, url): solo el coach.
--   * contacto_atleta: el teléfono de cada atleta para escribirle por WhatsApp. Solo lo ve y lo cambia el coach
--     (contactos(), contacto_guardar(atleta, teléfono)).
-- Nadie lee ni escribe las tablas directamente. Al borrar la ficha de un atleta, lo suyo se va con ella.
-- Sin esta migración, la app no enseña nada de esto y todo lo demás sigue igual.
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 050 (o con instalar.sql en una
-- base nueva). Se puede repetir sin romper nada.
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 51 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 051 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 51;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 50) then  -- (2) la migración previa
    raise exception 'Antes de la 051 hace falta la 050: ejecútala primero (o usa supabase/instalar.sql en una base nueva).';
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. Los enlaces personales de cada atleta
-- ---------------------------------------------------------------------
create table if not exists public.integraciones (
  atleta_id          uuid primary key references public.atletas(id) on delete cascade,
  salud_huella       text,
  salud_desde        timestamptz,
  salud_ultimo       timestamptz,       -- la última vez que llegó algo de Salud
  calendario_huella  text,
  calendario_desde   timestamptz,
  calendario_ultimo  timestamptz,       -- la última vez que su calendario pidió los entrenos
  cal_hora           text not null default '18:00',
  cal_minutos        smallint not null default 75,
  cal_aviso          smallint not null default 30,
  actualizado_en     timestamptz not null default now()
);
-- (revisión) si el calendario lleva las indicaciones del coach (la dinámica de cada sesión): por defecto, no
alter table public.integraciones add column if not exists cal_detalle boolean not null default false;
alter table public.integraciones drop constraint if exists integraciones_valida;
alter table public.integraciones add constraint integraciones_valida check (
  (salud_huella is null or salud_huella ~ '^[0-9a-f]{64}$')
  and (calendario_huella is null or calendario_huella ~ '^[0-9a-f]{64}$')
  and cal_hora ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
  and cal_minutos between 15 and 240
  and cal_aviso between 0 and 1440
);
create unique index if not exists integraciones_salud_idx on public.integraciones (salud_huella) where salud_huella is not null;
create unique index if not exists integraciones_calendario_idx on public.integraciones (calendario_huella) where calendario_huella is not null;
comment on table public.integraciones is 'Los enlaces personales de cada atleta (solo su huella sha-256) para Salud del iPhone y su calendario. Solo por sus funciones.';

create or replace function fbe_privado.huella(p_enlace text) returns text
language sql immutable set search_path = '' as $$
  select encode(sha256(convert_to(coalesce(p_enlace, ''), 'UTF8')), 'hex');
$$;

-- ---------------------------------------------------------------------
-- 2. Lo que llega de Salud, un día por fila
-- ---------------------------------------------------------------------
create table if not exists public.salud_diaria (
  atleta_id       uuid not null references public.atletas(id) on delete cascade,
  fecha           date not null,
  pasos           int,
  sueno_min       smallint,
  fc_reposo       smallint,
  hrv             numeric(5,1),
  peso_kg         numeric(5,2),
  actualizado_en  timestamptz not null default now(),
  primary key (atleta_id, fecha)
);
alter table public.salud_diaria drop constraint if exists salud_diaria_valida;
alter table public.salud_diaria add constraint salud_diaria_valida check (
  fecha >= date '2020-01-01' and fecha < date '2100-01-01'
  and (pasos is null or pasos between 0 and 100000)
  and (sueno_min is null or sueno_min between 0 and 1080)
  and (fc_reposo is null or fc_reposo between 25 and 150)
  and (hrv is null or hrv between 0 and 300)
  and (peso_kg is null or peso_kg between 25 and 350)
);
comment on table public.salud_diaria is 'Lo que manda el atajo de Salud del iPhone de cada atleta, un día por fila. Datos de salud: solo por sus funciones.';

-- (revisión) Lo que el atajo copió a sus hábitos de pasos y sueño y a sus pesos, con lo que había antes: para que
-- borrar lo de Salud (al desconectar con «borrar» o al retirar el consentimiento) se lleve también las copias y deje
-- el día como lo tenía él. Solo se deshace lo que siga igual que lo dejó el atajo: si lo cambió él después, es suyo.
create table if not exists public.salud_copias (
  atleta_id     uuid not null references public.atletas(id) on delete cascade,
  tipo          text not null check (tipo in ('pasos', 'sueno', 'peso')),
  habito_id     uuid references public.habitos(id) on delete cascade,
  fecha         date not null,
  valor_previo  numeric,          -- lo que había apuntado él (null: no había nada)
  valor_puesto  numeric not null, -- lo que dejó el atajo
  primary key (atleta_id, tipo, fecha)
);
create index if not exists salud_copias_habito_idx on public.salud_copias (habito_id);
comment on table public.salud_copias is 'Lo que el atajo de Salud copió a hábitos y pesos, para poder deshacerlo. Solo por sus funciones.';

-- Borra lo que llegó de Salud y deshace sus copias (lo que siga igual que lo dejó el atajo)
create or replace function fbe_privado.salud_borrar(p_atleta uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare c public.salud_copias;
begin
  for c in select * from public.salud_copias where atleta_id = p_atleta loop
    begin
      if c.tipo in ('pasos', 'sueno') and c.habito_id is not null then
        if c.valor_previo is null then
          delete from public.registros_habito where habito_id = c.habito_id and fecha = c.fecha and valor = c.valor_puesto;
        else
          update public.registros_habito set valor = c.valor_previo where habito_id = c.habito_id and fecha = c.fecha and valor = c.valor_puesto;
        end if;
      elsif c.tipo = 'peso' then
        delete from public.pesos where atleta_id = p_atleta and fecha = c.fecha and kg = c.valor_puesto and notas = 'Desde Salud';
      end if;
      delete from public.salud_copias where atleta_id = c.atleta_id and tipo = c.tipo and fecha = c.fecha;
    exception when others then
      -- (si una no se puede deshacer, las demás sí; esa se queda apuntada para volver a intentarlo)
      raise warning 'salud_borrar: no se pudo deshacer % del %: %', c.tipo, c.fecha, sqlerrm;
    end;
  end loop;
  delete from public.salud_diaria where atleta_id = p_atleta;
end $$;

-- ---------------------------------------------------------------------
-- 3. Los atajos del coach y el teléfono de cada atleta
-- ---------------------------------------------------------------------
create table if not exists public.atajos_coach (
  clave          text primary key,
  url            text not null,
  actualizado_en timestamptz not null default now()
);
alter table public.atajos_coach drop constraint if exists atajos_coach_valido;
alter table public.atajos_coach add constraint atajos_coach_valido check (
  clave in ('salud', 'entreno') and url ~ '^https://www\.icloud\.com/shortcuts/[0-9A-Za-z]{16,64}$'
);
comment on table public.atajos_coach is 'Los enlaces de iCloud de los atajos del coach (de Salud a la app y de la app a Salud).';

create table if not exists public.contacto_atleta (
  atleta_id      uuid primary key references public.atletas(id) on delete cascade,
  telefono       text not null,
  actualizado_en timestamptz not null default now()
);
alter table public.contacto_atleta drop constraint if exists contacto_atleta_valido;
alter table public.contacto_atleta add constraint contacto_atleta_valido check (telefono ~ '^\+?[0-9]{6,15}$');
comment on table public.contacto_atleta is 'El teléfono de cada atleta, para escribirle por WhatsApp. Solo el coach.';

-- ---------------------------------------------------------------------
-- 4. Lo que usa el atleta
-- ---------------------------------------------------------------------
create or replace function public.integraciones_mias() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id(); i public.integraciones;
begin
  if v_atleta is null then return null; end if;
  select * into i from public.integraciones where atleta_id = v_atleta;
  return jsonb_build_object(
    'salud', jsonb_build_object('activa', i.salud_huella is not null, 'desde', i.salud_desde, 'ultimo', i.salud_ultimo),
    'calendario', jsonb_build_object('activo', i.calendario_huella is not null, 'desde', i.calendario_desde, 'ultimo', i.calendario_ultimo,
      'hora', coalesce(i.cal_hora, '18:00'), 'minutos', coalesce(i.cal_minutos, 75), 'aviso', coalesce(i.cal_aviso, 30), 'detalle', coalesce(i.cal_detalle, false)),
    'atajos', coalesce((select jsonb_object_agg(a.clave, a.url) from public.atajos_coach a), '{}'::jsonb));
end $$;
comment on function public.integraciones_mias() is 'Qué tiene conectado el atleta (Salud y calendario, sin los enlaces) y los atajos de su coach.';

-- Lee y comprueba las opciones del calendario (lo que falta, como estaba)
create or replace function fbe_privado.opciones_calendario(p jsonb, i public.integraciones) returns public.integraciones
language plpgsql immutable set search_path = '' as $$
declare r public.integraciones := i; v_min int; v_aviso int;
begin
  if p is null or jsonb_typeof(p) <> 'object' then return r; end if;
  if p ? 'hora' then
    if coalesce(p ->> 'hora', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Hora no válida (HH:MM)'; end if;
    r.cal_hora := p ->> 'hora';
  end if;
  begin
    v_min := nullif(p ->> 'minutos', '')::int;
    v_aviso := nullif(p ->> 'aviso', '')::int;
  exception when others then raise exception 'Duración o aviso no válidos'; end;
  if v_min is not null then
    if v_min not between 15 and 240 then raise exception 'La duración va de 15 a 240 minutos'; end if;
    r.cal_minutos := v_min;
  end if;
  if v_aviso is not null then
    if v_aviso not between 0 and 1440 then raise exception 'El aviso va de 0 a 1440 minutos'; end if;
    r.cal_aviso := v_aviso;
  end if;
  if p ? 'detalle' then
    if jsonb_typeof(p -> 'detalle') <> 'boolean' then raise exception 'Detalle no válido'; end if;
    r.cal_detalle := (p ->> 'detalle')::boolean;
  end if;
  return r;
end $$;

create or replace function public.integracion_crear(p_tipo text, p_opciones jsonb default null) returns text
language plpgsql security definer set search_path = '' as $$
declare
  v_atleta uuid := public.mi_atleta_id();
  v_enlace text;
  i public.integraciones;
begin
  if v_atleta is null then raise exception 'Solo el atleta conecta lo suyo'; end if;
  if p_tipo not in ('salud', 'calendario') then raise exception 'Tipo no válido'; end if;
  if exists (select 1 from public.atletas where id = v_atleta and estado = 'baja') then
    raise exception 'Tu cuenta está de baja: puedes ver y descargar tus datos, pero no añadir ni cambiar nada';
  end if;
  if p_tipo = 'salud' and not public.consentimiento_salud_de_atleta(v_atleta) then
    raise exception 'Para traer datos de Salud hace falta tu consentimiento de datos de salud';
  end if;
  -- 64 caracteres al azar (dos uuid aleatorios y el reloj, pasados por sha-256): imposible de adivinar
  v_enlace := encode(sha256(convert_to(gen_random_uuid()::text || gen_random_uuid()::text || clock_timestamp()::text, 'UTF8')), 'hex');
  insert into public.integraciones (atleta_id) values (v_atleta) on conflict (atleta_id) do nothing;
  select * into i from public.integraciones where atleta_id = v_atleta for update;
  if p_tipo = 'salud' then
    update public.integraciones set salud_huella = fbe_privado.huella(v_enlace), salud_desde = coalesce(salud_desde, now()), actualizado_en = now()
      where atleta_id = v_atleta;
  else
    i := fbe_privado.opciones_calendario(p_opciones, i);
    update public.integraciones set calendario_huella = fbe_privado.huella(v_enlace), calendario_desde = coalesce(calendario_desde, now()),
      cal_hora = i.cal_hora, cal_minutos = i.cal_minutos, cal_aviso = i.cal_aviso, cal_detalle = i.cal_detalle, actualizado_en = now()
      where atleta_id = v_atleta;
  end if;
  return v_enlace;
end $$;
comment on function public.integracion_crear(text, jsonb) is 'Crea el enlace personal de Salud o del calendario (el anterior deja de valer) y lo devuelve una sola vez.';

create or replace function public.calendario_opciones(p_opciones jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id(); i public.integraciones;
begin
  if v_atleta is null then raise exception 'Solo el atleta cambia lo suyo'; end if;
  if exists (select 1 from public.atletas where id = v_atleta and estado = 'baja') then
    raise exception 'Tu cuenta está de baja: puedes ver y descargar tus datos, pero no añadir ni cambiar nada';
  end if;
  insert into public.integraciones (atleta_id) values (v_atleta) on conflict (atleta_id) do nothing;
  select * into i from public.integraciones where atleta_id = v_atleta for update;
  i := fbe_privado.opciones_calendario(p_opciones, i);
  update public.integraciones set cal_hora = i.cal_hora, cal_minutos = i.cal_minutos, cal_aviso = i.cal_aviso, cal_detalle = i.cal_detalle, actualizado_en = now()
    where atleta_id = v_atleta;
  return jsonb_build_object('hora', i.cal_hora, 'minutos', i.cal_minutos, 'aviso', i.cal_aviso, 'detalle', i.cal_detalle);
end $$;
comment on function public.calendario_opciones(jsonb) is 'La hora, la duración y el aviso de los entrenos en su calendario (el enlace no cambia).';

create or replace function public.integracion_quitar(p_tipo text, p_borrar boolean default false) returns void
language plpgsql security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id();
begin
  if v_atleta is null then raise exception 'Solo el atleta desconecta lo suyo'; end if;
  if p_tipo = 'salud' then
    update public.integraciones set salud_huella = null, salud_desde = null, salud_ultimo = null, actualizado_en = now() where atleta_id = v_atleta;
    -- Borrar lo que llegó se puede siempre (también de baja)
    if p_borrar then perform fbe_privado.salud_borrar(v_atleta); end if;
  elsif p_tipo = 'calendario' then
    update public.integraciones set calendario_huella = null, calendario_desde = null, calendario_ultimo = null, actualizado_en = now() where atleta_id = v_atleta;
  else
    raise exception 'Tipo no válido';
  end if;
end $$;
comment on function public.integracion_quitar(text, boolean) is 'Desconecta Salud o el calendario (el enlace deja de valer); con p_borrar, borra también lo que llegó de Salud.';

-- Lo que llegó de Salud: el propio atleta o el coach. Con la conexión, para la ficha.
create or replace function public.salud_diaria_de(p_atleta uuid, p_desde date default null, p_hasta date default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_desde date := coalesce(p_desde, (now() at time zone 'Europe/Madrid')::date - 13);
        v_hasta date := coalesce(p_hasta, (now() at time zone 'Europe/Madrid')::date + 1);
        i public.integraciones;
begin
  if p_atleta is null or not (public.es_coach() or p_atleta = public.mi_atleta_id()) then
    return jsonb_build_object('conectada', false, 'ultimo', null, 'dias', '[]'::jsonb);
  end if;
  -- (sin tope: un día por fila; la descarga de sus datos pide todo)
  select * into i from public.integraciones where atleta_id = p_atleta;
  return jsonb_build_object('conectada', coalesce(i.salud_huella is not null, false), 'ultimo', i.salud_ultimo,
    'dias', coalesce((select jsonb_agg(jsonb_build_object('fecha', s.fecha, 'pasos', s.pasos, 'sueno_min', s.sueno_min, 'fc_reposo', s.fc_reposo,
                       'hrv', s.hrv, 'peso_kg', s.peso_kg) order by s.fecha desc)
                     from public.salud_diaria s where s.atleta_id = p_atleta and s.fecha between v_desde and v_hasta), '[]'::jsonb));
end $$;
comment on function public.salud_diaria_de(uuid, date, date) is 'Lo que llegó de Salud de un atleta (él mismo o el coach), del más reciente al más antiguo.';

-- ---------------------------------------------------------------------
-- 5. Solo para la función «integraciones» (con la clave de servicio)
-- ---------------------------------------------------------------------
-- p_dias: [{ fecha: 'AAAA-MM-DD', pasos, sueno_min, fc_reposo, hrv, peso_kg }] (ya limpios en la función; aquí se
-- vuelve a comprobar: lo que se sale de rango se ignora, campo a campo). Como mucho 31 días, de los 60 últimos.
create or replace function public.salud_recibir(p_enlace text, p_dias jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_atleta uuid;
  v_hoy date := (now() at time zone 'Europe/Madrid')::date;
  d jsonb; v_fecha date; v_pasos int; v_sueno int; v_fc int; v_hrv numeric; v_peso numeric;
  n_dias int := 0; n_habitos int := 0; n_pesos int := 0; n int;
  v_hab_pasos uuid; v_hab_sueno uuid; v_prev numeric;
begin
  if coalesce(p_enlace, '') !~ '^[0-9a-f]{64}$' then return jsonb_build_object('ok', false, 'error', 'enlace'); end if;
  -- (for update: si a la vez se retira el consentimiento, uno espera al otro; el que espera ya no encuentra la clave)
  select atleta_id into v_atleta from public.integraciones where salud_huella = fbe_privado.huella(p_enlace) for update;
  if v_atleta is null then return jsonb_build_object('ok', false, 'error', 'enlace'); end if;
  if exists (select 1 from public.atletas where id = v_atleta and estado = 'baja') then return jsonb_build_object('ok', false, 'error', 'baja'); end if;
  if not exists (select 1 from public.atletas a join public.consentimientos c on c.perfil_id = a.perfil_id
                 where a.id = v_atleta and c.tipo = 'datos_salud' and c.revocado_en is null) then
    return jsonb_build_object('ok', false, 'error', 'consentimiento');
  end if;
  if p_dias is null or jsonb_typeof(p_dias) <> 'array' or jsonb_array_length(p_dias) = 0 then return jsonb_build_object('ok', false, 'error', 'datos'); end if;
  if jsonb_array_length(p_dias) > 31 then return jsonb_build_object('ok', false, 'error', 'demasiados'); end if;

  -- Sus hábitos de pasos y de sueño (los activos, de número)
  select h.id into v_hab_pasos from public.habitos h
    where h.atleta_id = v_atleta and h.activo and h.tipo = 'numero' and (lower(coalesce(h.unidad, '')) = 'pasos' or h.icono = 'pasos')
    order by h.orden, h.creado_en limit 1;
  select h.id into v_hab_sueno from public.habitos h
    where h.atleta_id = v_atleta and h.activo and h.tipo = 'numero' and h.icono = 'sueno' and lower(coalesce(h.unidad, '')) in ('h', 'horas', 'hora')
    order by h.orden, h.creado_en limit 1;

  for d in select * from jsonb_array_elements(p_dias) loop
    continue when jsonb_typeof(d) <> 'object';
    begin v_fecha := (d ->> 'fecha')::date; exception when others then v_fecha := null; end;
    continue when v_fecha is null or v_fecha < v_hoy - 60 or v_fecha > v_hoy + 1;
    begin v_pasos := round((d ->> 'pasos')::numeric); exception when others then v_pasos := null; end;
    begin v_sueno := round((d ->> 'sueno_min')::numeric); exception when others then v_sueno := null; end;
    begin v_fc := round((d ->> 'fc_reposo')::numeric); exception when others then v_fc := null; end;
    begin v_hrv := round((d ->> 'hrv')::numeric, 1); exception when others then v_hrv := null; end;
    begin v_peso := round((d ->> 'peso_kg')::numeric, 2); exception when others then v_peso := null; end;
    if v_pasos not between 0 and 100000 then v_pasos := null; end if;
    if v_sueno not between 1 and 1080 then v_sueno := null; end if;
    if v_fc not between 25 and 150 then v_fc := null; end if;
    if v_hrv not between 1 and 300 then v_hrv := null; end if;
    if v_peso not between 25 and 350 then v_peso := null; end if;
    continue when v_pasos is null and v_sueno is null and v_fc is null and v_hrv is null and v_peso is null;

    insert into public.salud_diaria as s (atleta_id, fecha, pasos, sueno_min, fc_reposo, hrv, peso_kg)
      values (v_atleta, v_fecha, v_pasos, v_sueno, v_fc, v_hrv, v_peso)
    on conflict (atleta_id, fecha) do update set
      -- los pasos de un día solo suben (un envío a media tarde y otro por la noche); lo demás, lo último que llega
      pasos = greatest(s.pasos, excluded.pasos), sueno_min = coalesce(excluded.sueno_min, s.sueno_min),
      fc_reposo = coalesce(excluded.fc_reposo, s.fc_reposo), hrv = coalesce(excluded.hrv, s.hrv),
      peso_kg = coalesce(excluded.peso_kg, s.peso_kg), actualizado_en = now();
    n_dias := n_dias + 1;

    -- Los pasos, en su hábito de pasos (sin bajar lo que ya apuntó)
    if v_pasos is not null and v_hab_pasos is not null and v_fecha <= v_hoy then
      select valor into v_prev from public.registros_habito where habito_id = v_hab_pasos and fecha = v_fecha;
      insert into public.registros_habito as r (habito_id, atleta_id, fecha, valor) values (v_hab_pasos, v_atleta, v_fecha, v_pasos)
      on conflict (habito_id, fecha) do update set valor = greatest(r.valor, excluded.valor) where r.valor < excluded.valor;
      get diagnostics n = row_count; n_habitos := n_habitos + n;
      -- (se apunta la copia con lo que había antes; si ya había una copia, se queda su «antes», el de él)
      if n > 0 then
        insert into public.salud_copias (atleta_id, tipo, habito_id, fecha, valor_previo, valor_puesto) values (v_atleta, 'pasos', v_hab_pasos, v_fecha, v_prev, v_pasos)
        -- (su «antes» se queda, salvo que él haya cambiado o borrado el día desde la última copia, o cambie el hábito)
        on conflict (atleta_id, tipo, fecha) do update set
          valor_previo = case when public.salud_copias.valor_puesto is distinct from v_prev or public.salud_copias.habito_id is distinct from excluded.habito_id
                              then excluded.valor_previo else public.salud_copias.valor_previo end,
          valor_puesto = excluded.valor_puesto, habito_id = excluded.habito_id;
      end if;
    end if;
    -- Las horas de sueño, en su hábito de sueño si ese día no las apuntó él
    if v_sueno is not null and v_hab_sueno is not null and v_fecha <= v_hoy then
      insert into public.registros_habito (habito_id, atleta_id, fecha, valor) values (v_hab_sueno, v_atleta, v_fecha, round(v_sueno / 60.0, 1))
      on conflict (habito_id, fecha) do nothing;
      get diagnostics n = row_count; n_habitos := n_habitos + n;
      if n > 0 then
        insert into public.salud_copias (atleta_id, tipo, habito_id, fecha, valor_previo, valor_puesto) values (v_atleta, 'sueno', v_hab_sueno, v_fecha, null, round(v_sueno / 60.0, 1))
        on conflict (atleta_id, tipo, fecha) do update set valor_puesto = excluded.valor_puesto, habito_id = excluded.habito_id, valor_previo = null;
      end if;
    end if;
    -- El peso, en sus pesos si ese día no hay otro
    if v_peso is not null and v_fecha <= v_hoy then
      insert into public.pesos (atleta_id, fecha, kg, notas) values (v_atleta, v_fecha, v_peso, 'Desde Salud')
      on conflict (atleta_id, fecha) do nothing;
      get diagnostics n = row_count; n_pesos := n_pesos + n;
      if n > 0 then
        insert into public.salud_copias (atleta_id, tipo, habito_id, fecha, valor_previo, valor_puesto) values (v_atleta, 'peso', null, v_fecha, null, v_peso)
        on conflict (atleta_id, tipo, fecha) do update set valor_puesto = excluded.valor_puesto;
      end if;
    end if;
  end loop;

  update public.integraciones set salud_ultimo = now() where atleta_id = v_atleta;
  return jsonb_build_object('ok', true, 'dias', n_dias, 'habitos', n_habitos, 'pesos', n_pesos);
end $$;
comment on function public.salud_recibir(text, jsonb) is 'Solo la función «integraciones»: guarda lo que manda el atajo de Salud de un atleta (con su enlace).';

-- Los entrenos con día previsto, de dos semanas atrás a ocho adelante, para su calendario
create or replace function public.calendario_de(p_enlace text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_atleta uuid; i public.integraciones;
  v_hoy date := (now() at time zone 'Europe/Madrid')::date;
begin
  if coalesce(p_enlace, '') !~ '^[0-9a-f]{64}$' then return null; end if;
  select * into i from public.integraciones where calendario_huella = fbe_privado.huella(p_enlace);
  if not found then return null; end if;
  v_atleta := i.atleta_id;
  -- (la última consulta, como mucho una vez por hora: los calendarios preguntan a menudo)
  if i.calendario_ultimo is null or i.calendario_ultimo < now() - interval '1 hour' then
    update public.integraciones set calendario_ultimo = now() where atleta_id = v_atleta;
  end if;
  return jsonb_build_object('hora', i.cal_hora, 'minutos', i.cal_minutos, 'aviso', i.cal_aviso,
    'eventos', case when exists (select 1 from public.atletas where id = v_atleta and estado = 'baja') then '[]'::jsonb else
      coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'dia', s.dia_previsto, 'nombre', s.nombre, 'tipo', s.tipo,
                  'descripcion', case when i.cal_detalle then coalesce(s.dinamica, '') else '' end, 'hecha', s.completada) order by s.dia_previsto, s.orden)
                from public.sesiones s
                join public.semanas w on w.id = s.semana_id
                join public.bloques b on b.id = w.bloque_id
                where b.atleta_id = v_atleta and not b.es_plantilla and b.estado <> 'cancelado' and w.programacion = 'programada'
                  and s.dia_previsto is not null and w.fecha_inicio is not null
                  and s.dia_previsto between w.fecha_inicio and w.fecha_inicio + 6
                  and s.dia_previsto between v_hoy - 14 and v_hoy + 56), '[]'::jsonb) end);
end $$;
comment on function public.calendario_de(text) is 'Solo la función «integraciones»: los entrenos con día de un atleta (con su enlace), para su calendario.';

-- ---------------------------------------------------------------------
-- 6. Lo que usa el coach
-- ---------------------------------------------------------------------
create or replace function public.atajos_lista() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  return coalesce((select jsonb_object_agg(a.clave, a.url) from public.atajos_coach a), '{}'::jsonb);
end $$;
comment on function public.atajos_lista() is 'Los enlaces de los atajos del coach. Solo el coach (el atleta los ve en integraciones_mias).';

create or replace function public.atajo_guardar(p_clave text, p_url text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_url text := nullif(btrim(coalesce(p_url, '')), '');
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  if p_clave not in ('salud', 'entreno') then raise exception 'Atajo no válido'; end if;
  if v_url is null then delete from public.atajos_coach where clave = p_clave; return; end if;
  insert into public.atajos_coach (clave, url) values (p_clave, v_url)
  on conflict (clave) do update set url = excluded.url, actualizado_en = now();
end $$;
comment on function public.atajo_guardar(text, text) is 'El coach guarda (o, vacío, quita) el enlace de iCloud de uno de sus atajos.';

create or replace function public.contactos() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  return coalesce((select jsonb_object_agg(c.atleta_id, c.telefono) from public.contacto_atleta c), '{}'::jsonb);
end $$;
comment on function public.contactos() is 'El teléfono de cada atleta ({ atleta_id: teléfono }). Solo el coach.';

create or replace function public.contacto_guardar(p_atleta uuid, p_telefono text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_tel text := regexp_replace(coalesce(p_telefono, ''), '[[:space:]().-]', '', 'g');
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  if not exists (select 1 from public.atletas where id = p_atleta) then raise exception 'Ese atleta no existe'; end if;
  if v_tel = '' then delete from public.contacto_atleta where atleta_id = p_atleta; return; end if;
  if v_tel ~ '^00' then v_tel := '+' || substr(v_tel, 3); end if;
  if v_tel !~ '^\+?[0-9]{6,15}$' then raise exception 'Teléfono no válido'; end if;
  insert into public.contacto_atleta (atleta_id, telefono) values (p_atleta, v_tel)
  on conflict (atleta_id) do update set telefono = excluded.telefono, actualizado_en = now();
end $$;
comment on function public.contacto_guardar(uuid, text) is 'El coach guarda (o, vacío, quita) el teléfono de un atleta.';

-- ---------------------------------------------------------------------
-- 7. (revisión) Lo suyo en su descarga, retirar el consentimiento y la copia del coach
-- ---------------------------------------------------------------------
-- Su teléfono (el que guardó el coach), para «Descargar mis datos»
create or replace function public.contacto_mio() returns text
language sql stable security definer set search_path = '' as $$
  select c.telefono from public.contacto_atleta c where c.atleta_id = public.mi_atleta_id();
$$;
comment on function public.contacto_mio() is 'El teléfono del atleta que lo pide (para su descarga de datos).';

-- Al retirar el consentimiento de datos de salud: Salud del iPhone se desconecta y lo que llegó de ahí se borra (con sus
-- copias). Lo que escribió él (check-ins, pesos, hábitos) se queda, como siempre: lo de Salud llega solo, sin que lo
-- escriba, y solo tiene sentido mientras lo tiene conectado. «before»: aún con el consentimiento, por si algo lo pide.
create or replace function fbe_privado.salud_al_retirar() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_atleta uuid;
begin
  if old.tipo = 'datos_salud' and old.revocado_en is null and (tg_op = 'DELETE' or new.revocado_en is not null)
     and not exists (select 1 from public.consentimientos c where c.perfil_id = old.perfil_id and c.tipo = 'datos_salud' and c.revocado_en is null and c.id <> old.id) then
    for v_atleta in select a.id from public.atletas a where a.perfil_id = old.perfil_id loop
      update public.integraciones set salud_huella = null, salud_desde = null, salud_ultimo = null, actualizado_en = now() where atleta_id = v_atleta;
      perform fbe_privado.salud_borrar(v_atleta);
    end loop;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;
-- Al borrar su cuenta, la ficha se queda sin cuenta (perfil_id a null) antes de que se borren sus consentimientos: lo de
-- Salud se va entonces (si no, una ficha vuelta a vincular con una invitación recuperaría la clave vieja)
create or replace function fbe_privado.salud_al_desvincular() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.perfil_id is not null and new.perfil_id is null then
    update public.integraciones set salud_huella = null, salud_desde = null, salud_ultimo = null, actualizado_en = now() where atleta_id = old.id;
    perform fbe_privado.salud_borrar(old.id);
  end if;
  return new;
end $$;
drop trigger if exists atletas_salud_al_desvincular on public.atletas;
create trigger atletas_salud_al_desvincular after update of perfil_id on public.atletas
  for each row execute function fbe_privado.salud_al_desvincular();
drop trigger if exists consentimientos_salud_al_retirar on public.consentimientos;
create trigger consentimientos_salud_al_retirar before update or delete on public.consentimientos
  for each row execute function fbe_privado.salud_al_retirar();

-- La copia completa del coach: las tablas que solo se abren con funciones (las de la 050 y la 051), sin las huellas de
-- los enlaces (no sirven de nada en una copia)
create or replace function public.copia_privada() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  return jsonb_build_object(
    'personal_atleta', coalesce((select jsonb_agg(to_jsonb(t)) from public.personal_atleta t), '[]'::jsonb),
    'mensajes_coach', coalesce((select jsonb_agg(to_jsonb(t)) from public.mensajes_coach t), '[]'::jsonb),
    'musica_coach', coalesce((select jsonb_agg(to_jsonb(t)) from public.musica_coach t), '[]'::jsonb),
    'integraciones', coalesce((select jsonb_agg(to_jsonb(t) - 'salud_huella' - 'calendario_huella') from public.integraciones t), '[]'::jsonb),
    'salud_diaria', coalesce((select jsonb_agg(to_jsonb(t)) from public.salud_diaria t), '[]'::jsonb),
    'salud_copias', coalesce((select jsonb_agg(to_jsonb(t)) from public.salud_copias t), '[]'::jsonb),
    'atajos_coach', coalesce((select jsonb_agg(to_jsonb(t)) from public.atajos_coach t), '[]'::jsonb),
    'contacto_atleta', coalesce((select jsonb_agg(to_jsonb(t)) from public.contacto_atleta t), '[]'::jsonb));
end $$;
comment on function public.copia_privada() is 'Para la copia completa del coach: las tablas de la 050 y la 051 (sin las huellas de los enlaces). Solo el coach.';

-- Nadie toca las tablas directamente
alter table public.integraciones enable row level security;
alter table public.salud_diaria enable row level security;
alter table public.atajos_coach enable row level security;
alter table public.contacto_atleta enable row level security;
alter table public.salud_copias enable row level security;
revoke all on public.integraciones, public.salud_diaria, public.atajos_coach, public.contacto_atleta, public.salud_copias from public, anon, authenticated;

-- Permisos (como al final de 003 a 050). salud_recibir y calendario_de, solo la clave de servicio.
revoke truncate, references, trigger on all tables in schema public from public, anon, authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated, service_role;
revoke execute on function public.crear_recordatorios(timestamptz), public.notificaciones_por_enviar(integer, boolean),
  public.notificaciones_resultado(jsonb), public.salud_recibir(text, jsonb), public.calendario_de(text) from public, anon, authenticated;
revoke all on all functions in schema fbe_privado from public, anon, authenticated;

insert into public.fbe_migraciones (numero) values (51)  -- (3) número de esta migración
  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/053_social.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 053: la parte social del equipo, tanda «social» (15 mejoras)
--
-- Por qué: la comunidad ya tiene muro, retos, ranking, parejas de racha, ánimos, bienvenidas, momentos y los eventos
-- del coach. Lo que faltaba es que los atletas se busquen entre ellos: coincidir en el gimnasio, retarse, acompañar a
-- quien entra, felicitarse, elegir a quien más anima… y que todo eso cuente en su perfil del equipo.
--
-- Qué hace (todo voluntario y siempre dentro de la comunidad):
--   * Cumpleaños en el equipo: el atleta lo enciende (comunidad_miembros.cumple_equipo) y el día de su cumpleaños (el que
--     puso en Perfil → Lo tuyo, 050) los del equipo lo ven (comunidad_cumples()) y le felicitan con un ánimo.
--   * Ánimo con unas palabras: comunidad_animar(perfil, texto) admite hasta 80 letras (opcional), que van en el aviso.
--   * Encuestas de los atletas: una al día, como las del coach (2 a 4 opciones, cierre opcional). Las vota todo el equipo.
--   * Quedadas propuestas por atletas: comunidad_eventos.creado_por (null = del coach). Hasta 3 abiertas por persona, con
--     hasta 30 plazas; quien la propone va; solo él (o el coach) la cambia o la cancela.
--   * Duelos 1 a 1 (comunidad_duelos): retar a un compañero a la semana (sesiones hechas de lunes a domingo). Hay que
--     aceptar; lo ven los dos y el coach; al acabar la semana, quién ha hecho más.
--   * «Hoy entreno a las…» (comunidad_intenciones): una fila por persona (hoy o mañana, con hora y nota opcionales) que
--     ven los del equipo para coincidir. Caduca sola.
--   * Apadrinar a quien entra (comunidad_padrinos): un veterano (8 semanas dentro) acompaña 30 días a alguien que lleva
--     menos de 14 en el equipo. El nuevo ve quién le acompaña; el padrino, a quién.
--   * Compañero de la semana elegido por el equipo (comunidad_votos_semana): un voto por semana (se puede cambiar) a quien
--     más ha animado o ayudado. El lunes sale el de la semana anterior si tiene al menos 2 votos. Los votos no se ven.
--   * Tu huella en el equipo (comunidad_huella): ánimos dados y recibidos, bienvenidas, comentarios, reacciones, quedadas,
--     ahijados, veces elegido y semanas seguidas animando.
--   * Insignias sociales: Animador (25 ánimos), Anfitrión (3 bienvenidas), Padrino (1) y Puntual (3 quedadas).
--   * Citar una publicación (comunidad_posts.cita_post_id): compartir en el muro la de un compañero con tu comentario.
--   * Quién necesita un ánimo (comunidad_sin_entrenar): solo quien lo enciende (ver_ausencia) sale cuando lleva 5 días o
--     más sin entrenar, para que le manden ánimo.
-- Lo mejor de la semana, el álbum y «misma sesión» no necesitan la base: salen de lo que ya hay.
-- Al salir borrando lo suyo, también se va lo de aquí; comunidad_mis_datos() lo incluye. Sin esta migración, la app no
-- enseña nada de esto y todo lo demás sigue igual.
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 052 (o con instalar.sql en una
-- base nueva). Necesita la 051. La migración del reloj, si llega después, va como 054. Se puede repetir sin romper nada.
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 53 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 053 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 53;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 51) then  -- (2) la migración previa que hace falta (la 052, del reloj, es aparte)
    raise exception 'Falta la migración 051 (esta base va por la %). Ejecuta las migraciones en orden.', to_char(coalesce(v, 0), 'FM000');
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. Lo que cada uno enciende: el cumpleaños y «que me manden ánimo si paro»
-- ---------------------------------------------------------------------
alter table public.comunidad_miembros add column if not exists cumple_equipo boolean not null default false;
alter table public.comunidad_miembros add column if not exists ver_ausencia boolean not null default false;

create or replace function public.comunidad_social_ajustes(p_cumple boolean default null, p_ausencia boolean default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare m public.comunidad_miembros;
begin
  if auth.uid() is null or not public.comunidad_soy_miembro() then raise exception 'No estás en la comunidad' using errcode = '42501'; end if;
  update public.comunidad_miembros set cumple_equipo = coalesce(p_cumple, cumple_equipo), ver_ausencia = coalesce(p_ausencia, ver_ausencia)
  where perfil_id = auth.uid() returning * into m;
  return jsonb_build_object('cumple_equipo', m.cumple_equipo, 'ver_ausencia', m.ver_ausencia);
end $$;
comment on function public.comunidad_social_ajustes(boolean, boolean) is '053: enciende o apaga «mi cumpleaños en el equipo» y «que me manden ánimo si paro».';

-- Los cumpleaños de hoy (hora de Madrid) de quien lo tiene encendido y puso su cumpleaños (050). Solo dentro.
create or replace function public.comunidad_cumples()
returns table (perfil_id uuid, nombre text, foto text, soy_yo boolean)
language sql stable security definer set search_path = '' as $$
  select d.perfil_id, d.nombre, p.foto, d.perfil_id = auth.uid()
  from fbe_privado.comunidad_dentro d
  join public.comunidad_miembros m on m.atleta_id = d.atleta_id and m.cumple_equipo
  join public.personal_atleta pa on pa.atleta_id = d.atleta_id
    and pa.cumple_mes = extract(month from fbe_privado.comunidad_hoy())::smallint
    and pa.cumple_dia = extract(day from fbe_privado.comunidad_hoy())::smallint
  join public.perfiles p on p.id = d.perfil_id
  where auth.uid() is not null and (public.es_coach() or public.comunidad_soy_miembro())
  order by d.nombre
$$;

-- ---------------------------------------------------------------------
-- 2. El ánimo, con unas palabras
-- ---------------------------------------------------------------------
alter table public.comunidad_animos add column if not exists texto text;
alter table public.comunidad_animos drop constraint if exists comunidad_animos_texto_valido;
alter table public.comunidad_animos add constraint comunidad_animos_texto_valido check (
  texto is null or (char_length(texto) between 1 and 80 and public.texto_visible(texto) and texto !~ '[[:cntrl:]]'));

drop function if exists public.comunidad_animar(uuid);
create or replace function public.comunidad_animar(p_perfil uuid, p_texto text default null) returns date
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_semana date := fbe_privado.comunidad_lunes();
  v_para_atleta uuid;
  v_texto text := nullif(btrim(regexp_replace(coalesce(p_texto, ''), '\s+', ' ', 'g')), '');
begin
  if v_uid is null or not public.comunidad_activa() or not (public.es_coach() or public.comunidad_soy_miembro()) then
    raise exception 'Para animar tienes que estar en la comunidad (y abierta)' using errcode = '42501';
  end if;
  if p_perfil is null or p_perfil = v_uid then raise exception 'A ti no te puedes mandar ánimo (¡pero vas bien!)' using errcode = '22023'; end if;
  if v_texto is not null and char_length(v_texto) > 80 then raise exception 'Las palabras del ánimo, hasta 80 letras' using errcode = '22023'; end if;
  if v_texto is not null and fbe_privado.comunidad_moderar_entrada(v_uid, false, v_texto) then
    raise exception 'Esas palabras no pueden ir en un ánimo' using errcode = '22023';
  end if;
  select d.atleta_id into v_para_atleta from fbe_privado.comunidad_dentro d where d.perfil_id = p_perfil;
  if v_para_atleta is null then raise exception 'Esa persona ya no está en el equipo' using errcode = '42501'; end if;
  if exists (select 1 from public.comunidad_animos a where a.de = v_uid and a.para = p_perfil and a.semana = v_semana) then
    raise exception 'Ya le has mandado ánimo esta semana' using errcode = '23505';
  end if;
  perform fbe_privado.comunidad_gastar_cupo('animo');
  insert into public.comunidad_animos (de, para, atleta_id, para_atleta_id, semana, texto)
  values (v_uid, p_perfil, case when public.es_coach() then null else public.mi_atleta_id() end, v_para_atleta, v_semana, v_texto);
  perform fbe_privado.notificar_seguro(p_perfil, 'comunidad', fbe_privado.comunidad_nombre(v_uid) || ' te ha mandado ánimo 🙌',
    coalesce('«' || v_texto || '»', 'Míralo en Equipo.'), '#equipo', 'comunidad_animo:' || v_uid || ':' || v_semana);
  return v_semana;
end $$;
comment on function public.comunidad_animar(uuid, text) is '029/053: mandar ánimo a alguien del equipo (una vez por semana), con unas palabras opcionales (hasta 80).';

-- ---------------------------------------------------------------------
-- 3. Encuestas de los atletas (una al día) y citar una publicación
-- ---------------------------------------------------------------------
alter table public.comunidad_posts add column if not exists cita_post_id uuid references public.comunidad_posts(id) on delete set null;
create index if not exists comunidad_posts_cita_idx on public.comunidad_posts (cita_post_id) where cita_post_id is not null;

drop policy if exists miembro_publicar on public.comunidad_posts;
create policy miembro_publicar on public.comunidad_posts for insert to authenticated
  with check (autor_id = auth.uid() and tipo in ('post', 'momento', 'encuesta') and not fijada and not oculta and sesion_id is null and resumen is null
              and atleta_id = public.mi_atleta_id() and public.comunidad_soy_miembro());

-- La encuesta, limpia (lo de la 029/045, para el coach y para los atletas)
create or replace function public.comunidad_encuesta_limpia(p jsonb) returns jsonb
language plpgsql set search_path = '' as $$
declare
  v_cierre timestamptz;
  v_opciones jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'object' or jsonb_typeof(p -> 'opciones') is distinct from 'array' then
    raise exception 'Una encuesta lleva de 2 a 4 opciones' using errcode = '22023';
  end if;
  begin
    v_cierre := nullif(btrim(coalesce(p ->> 'cierre', '')), '')::timestamptz;
  exception when others then
    raise exception 'El cierre de la encuesta no es una fecha válida' using errcode = '22023';
  end;
  if v_cierre is not null and v_cierre <= now() + interval '5 minutes' then
    raise exception 'El cierre de la encuesta, más adelante (o sin cierre)' using errcode = '22023';
  end if;
  select jsonb_agg(to_jsonb(btrim(e.o #>> '{}')) order by e.n) into v_opciones
  from jsonb_array_elements(p -> 'opciones') with ordinality as e(o, n);
  return jsonb_build_object('opciones', coalesce(v_opciones, '[]'::jsonb), 'cierre', to_jsonb(v_cierre));
end $$;

-- Publicar desde la app (029/045), con las encuestas de los atletas (una al día) y la cita de otra publicación
create or replace function public.comunidad_post_preparar() returns trigger
language plpgsql set search_path = '' as $$
begin
  if current_user not in ('authenticated', 'anon') then return new; end if;
  new.autor_id := auth.uid();
  new.creado_en := now();
  new.oculta := false;
  new.sesion_id := null;
  new.resumen := null;
  new.reto_id := null;
  new.menciones := coalesce(new.menciones, '{}');
  if public.es_coach() then
    new.atleta_id := null;
    new.cita_post_id := null;
    if new.tipo is distinct from 'aviso' and new.tipo is distinct from 'encuesta' and new.tipo is distinct from 'momento' then
      raise exception 'Como coach, en el muro publicas avisos, encuestas y momentos' using errcode = '42501';
    end if;
    if new.foto_ruta is not null and (new.tipo not in ('aviso', 'momento') or new.foto_ruta not like 'coach/%') then
      raise exception 'La foto no va en su sitio' using errcode = '42501';
    end if;
    if new.tipo = 'encuesta' then new.encuesta := public.comunidad_encuesta_limpia(new.encuesta); else new.encuesta := null; end if;
  else
    new.atleta_id := public.mi_atleta_id();
    new.fijada := false;
    if new.tipo is distinct from 'post' and new.tipo is distinct from 'momento' and new.tipo is distinct from 'encuesta' then
      raise exception 'Los avisos son del coach, y los entrenos y los logros se comparten desde su sitio' using errcode = '42501';
    end if;
    if new.tipo = 'encuesta' then
      -- (053) una al día por persona; sin programar ni fijar
      if (select count(*) from public.comunidad_posts x where x.autor_id = new.autor_id and x.tipo = 'encuesta' and x.creado_en > now() - interval '1 day') >= 1 then
        raise exception 'Una encuesta al día: mañana, otra' using errcode = '54000';
      end if;
      new.encuesta := public.comunidad_encuesta_limpia(new.encuesta);
      new.publicar_en := null;
      new.foto_ruta := null;
      new.fotos := null;
    else
      new.encuesta := null;
    end if;
    if new.foto_ruta is not null and (new.atleta_id is null or new.foto_ruta not like new.atleta_id::text || '/%') then
      raise exception 'La foto no va en su sitio' using errcode = '42501';
    end if;
    -- (053) citar: solo una publicación que se ve, que no sea un momento ni la propia
    if new.cita_post_id is not null then
      if new.tipo <> 'post' then raise exception 'Solo una publicación normal cita a otra' using errcode = '22023'; end if;
      if not exists (select 1 from public.comunidad_posts c where c.id = new.cita_post_id and c.tipo <> 'momento' and c.autor_id <> new.autor_id
                     and public.comunidad_post_visible(c.id)) then
        raise exception 'Esa publicación ya no está (o es tuya)' using errcode = '22023';
      end if;
      if nullif(btrim(coalesce(new.texto, '')), '') is null then raise exception 'Al citar, escribe algo' using errcode = '22023'; end if;
    end if;
  end if;
  return new;
end $$;

-- A quien citan le llega un aviso (una vez por publicación que cita)
create or replace function fbe_privado.comunidad_al_citar() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_autor uuid;
begin
  if new.cita_post_id is null or new.retenida then return null; end if;
  select c.autor_id into v_autor from public.comunidad_posts c where c.id = new.cita_post_id;
  if v_autor is not null and v_autor <> new.autor_id and public.comunidad_activa() then
    perform fbe_privado.notificar_seguro(v_autor, 'comunidad', fbe_privado.comunidad_nombre(new.autor_id) || ' ha compartido tu publicación',
      coalesce(left(new.texto, 120), 'Míralo en Equipo.'), '#equipo', 'comunidad_cita:' || new.id);
  end if;
  return null;
exception when others then
  raise warning 'FBE: aviso de la cita % no creado: %', new.id, sqlerrm;
  return null;
end $$;
drop trigger if exists comunidad_posts_zz_citar on public.comunidad_posts;
create trigger comunidad_posts_zz_citar after insert on public.comunidad_posts
  for each row execute function fbe_privado.comunidad_al_citar();

-- Moderar (045) también las encuestas de los atletas: el texto y las opciones pasan el mismo filtro que una publicación
-- (al coach no se le retiene nada).
create or replace function fbe_privado.comunidad_post_moderar() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  new.retenida := new.tipo not in ('aviso', 'aniversario')
    and fbe_privado.comunidad_moderar_entrada(new.autor_id, new.tipo in ('post', 'momento', 'encuesta'),
          concat_ws(' ', new.texto, (select string_agg(o #>> '{}', ' ')
                                     from jsonb_array_elements(case when jsonb_typeof(new.encuesta -> 'opciones') = 'array'
                                                                    then new.encuesta -> 'opciones' else '[]'::jsonb end) o)));
  return new;
end $$;

-- El aviso a todo el equipo (044) sigue siendo para los avisos y las encuestas del coach: las de los atletas se ven en
-- el muro sin hacer sonar todos los móviles (una al día por persona sería mucho ruido).
create or replace function fbe_privado.comunidad_al_avisar() returns trigger
language plpgsql security definer set search_path = '' set lock_timeout = '1s' as $$
begin
  if new.tipo not in ('aviso', 'encuesta') or new.oculta or new.retenida or new.atleta_id is not null or not public.comunidad_activa() then
    return null;
  end if;
  if new.publicar_en is not null and new.publicar_en > now() then return null; end if;
  perform fbe_privado.notificar_seguro(d.perfil_id, 'comunidad',
            fbe_privado.comunidad_nombre(new.autor_id)
              || case when new.tipo = 'encuesta' then ' ha publicado una encuesta en el equipo' else ' ha publicado un aviso en el equipo' end,
            case when new.tipo = 'encuesta' then 'Tócalo para votar en Equipo.' else 'Tócalo para leerlo en Equipo.' end,
            '#equipo', 'comunidad_aviso:' || new.id)
  from fbe_privado.comunidad_dentro d
  where d.perfil_id <> new.autor_id;
  return null;
exception when others then
  raise warning 'FBE: notificación del aviso % no creada: %', new.id, sqlerrm;
  return null;
end $$;

-- ---------------------------------------------------------------------
-- 4. Quedadas propuestas por atletas
-- ---------------------------------------------------------------------
alter table public.comunidad_eventos add column if not exists creado_por uuid references public.perfiles(id) on delete cascade;
create index if not exists comunidad_eventos_creado_por_idx on public.comunidad_eventos (creado_por) where creado_por is not null;

drop policy if exists miembro_proponer on public.comunidad_eventos;
create policy miembro_proponer on public.comunidad_eventos for insert to authenticated
  with check (public.comunidad_soy_miembro() and public.comunidad_activa() and creado_por = auth.uid() and (plazas is null or plazas <= 30));
drop policy if exists miembro_suya on public.comunidad_eventos;
create policy miembro_suya on public.comunidad_eventos for update to authenticated
  using (creado_por = auth.uid() and public.comunidad_soy_miembro())
  with check (creado_por = auth.uid() and (plazas is null or plazas <= 30));

-- Al preparar (044): quien no es coach propone como él mismo, con hasta 3 quedadas abiertas
create or replace function public.comunidad_evento_preparar() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.creado_en := now();
    new.cancelado_en := null;
    if current_user in ('authenticated', 'anon') and not public.es_coach() then
      new.creado_por := auth.uid();
      new.plazas := coalesce(new.plazas, 30);
      if (select count(*) from public.comunidad_eventos e where e.creado_por = auth.uid() and e.cancelado_en is null and e.empieza_en > now()) >= 3 then
        raise exception 'Como mucho tres quedadas abiertas a la vez' using errcode = '54000';
      end if;
    elsif public.es_coach() then
      new.creado_por := null;   -- lo del coach es del coach: no firma a nombre de nadie
    end if;
  else
    if current_user in ('authenticated', 'anon') and not public.es_coach() then
      if new.empieza_en is distinct from old.empieza_en and old.empieza_en <= now() then
        raise exception 'Esa quedada ya pasó: propón otra' using errcode = '22023';
      end if;
      new.plazas := coalesce(new.plazas, 30);
    end if;
    new.creado_en := old.creado_en;
    new.creado_por := old.creado_por;
    new.cancelado_en := case when old.cancelado_en is not null then old.cancelado_en when new.cancelado_en is not null then now() end;
  end if;
  new.actualizado_en := now();
  new.titulo := btrim(new.titulo);
  new.lugar := btrim(new.lugar);
  new.descripcion := nullif(btrim(coalesce(new.descripcion, '')), '');
  if (tg_op = 'INSERT' or new.empieza_en is distinct from old.empieza_en) and new.cancelado_en is null then
    if new.empieza_en <= now() then raise exception 'El evento, más adelante (esa hora ya ha pasado)' using errcode = '22023'; end if;
    if new.empieza_en > now() + interval '1 year' then raise exception 'El evento, como mucho dentro de un año' using errcode = '22023'; end if;
  end if;
  return new;
end $$;

-- Las quedadas de los atletas pasan el mismo filtro de palabras que el muro (el título, el lugar y la descripción).
-- Va aparte porque comunidad_evento_preparar es del invocador y no llega a fbe_privado.
create or replace function fbe_privado.comunidad_evento_moderar() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if coalesce(nullif(current_setting('role', true), ''), 'none') in ('authenticated', 'anon') and not public.es_coach()
     and fbe_privado.comunidad_moderar_entrada(auth.uid(), false, concat_ws(' ', new.titulo, new.lugar, new.descripcion)) then
    raise exception 'Hay palabras que no van en el equipo' using errcode = '22023';
  end if;
  return new;
end $$;
drop trigger if exists comunidad_eventos_ab_moderar on public.comunidad_eventos;
create trigger comunidad_eventos_ab_moderar before insert or update of titulo, lugar, descripcion on public.comunidad_eventos
  for each row execute function fbe_privado.comunidad_evento_moderar();

-- Quien propone una quedada, va
create or replace function fbe_privado.comunidad_quedada_creada() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.creado_por is not null then
    insert into public.comunidad_evento_asistentes (evento_id, perfil_id, atleta_id, va)
    select new.id, new.creado_por, d.atleta_id, true from fbe_privado.comunidad_dentro d where d.perfil_id = new.creado_por
    on conflict (evento_id, perfil_id) do nothing;
  end if;
  return null;
end $$;
drop trigger if exists comunidad_eventos_zz_quedada on public.comunidad_eventos;
create trigger comunidad_eventos_zz_quedada after insert on public.comunidad_eventos
  for each row execute function fbe_privado.comunidad_quedada_creada();

-- Al cancelarla (044), el aviso dice quién la cancela
create or replace function fbe_privado.comunidad_evento_cambiado() returns trigger
language plpgsql security definer set search_path = '' set lock_timeout = '1s' as $$
begin
  if tg_op = 'DELETE' or new.cancelado_en is distinct from old.cancelado_en or new.empieza_en is distinct from old.empieza_en then
    delete from public.notificaciones n where n.estado = 'pendiente' and n.clave like 'comunidad_evento:' || old.id || ':%';
  end if;
  if tg_op = 'UPDATE' and new.cancelado_en is not null and old.cancelado_en is null and new.empieza_en > now() and public.comunidad_activa() then
    perform fbe_privado.notificar_seguro(a.perfil_id, 'comunidad', 'Se cancela: ' || new.titulo,
              case when new.creado_por is null then 'Tu coach ha cancelado el evento. Míralo en Equipo.'
                   else fbe_privado.comunidad_nombre(new.creado_por) || ' ha cancelado la quedada. Míralo en Equipo.' end,
              '#equipo', 'comunidad_evento_cancelado:' || new.id, null, new.empieza_en)
    from public.comunidad_evento_asistentes a join fbe_privado.comunidad_dentro d on d.perfil_id = a.perfil_id
    where a.evento_id = new.id and a.va and a.perfil_id <> coalesce(new.creado_por, '00000000-0000-0000-0000-000000000000'::uuid);
  end if;
  return null;
exception when others then
  raise warning 'FBE: avisos del evento % no puestos al día: %', old.id, sqlerrm;
  return null;
end $$;

-- ---------------------------------------------------------------------
-- 5. Duelos 1 a 1
-- ---------------------------------------------------------------------
create table if not exists public.comunidad_duelos (
  id            uuid primary key default gen_random_uuid(),
  de            uuid not null references public.perfiles(id) on delete cascade,
  para          uuid not null references public.perfiles(id) on delete cascade,
  de_atleta     uuid references public.atletas(id) on delete cascade,
  para_atleta   uuid references public.atletas(id) on delete cascade,
  semana        date not null,                               -- el lunes
  estado        text not null default 'pendiente' check (estado in ('pendiente', 'aceptado', 'rechazado')),
  creado_en     timestamptz not null default now(),
  respondido_en timestamptz,
  check (de <> para)
);
create unique index if not exists comunidad_duelos_unico_idx on public.comunidad_duelos (least(de, para), greatest(de, para), semana);
create index if not exists comunidad_duelos_para_idx on public.comunidad_duelos (para, semana);
create index if not exists comunidad_duelos_de_idx on public.comunidad_duelos (de, semana);

alter table public.comunidad_duelos enable row level security;
drop policy if exists coach_ver on public.comunidad_duelos;
create policy coach_ver on public.comunidad_duelos for select to authenticated using (public.es_coach());
drop policy if exists mios_ver on public.comunidad_duelos;
create policy mios_ver on public.comunidad_duelos for select to authenticated using (auth.uid() in (de, para) and public.comunidad_soy_miembro());

-- Retar a alguien: esta semana (si aún no es domingo) o la que viene. Los dos dentro y en el ranking; hasta 3 duelos vivos.
create or replace function public.comunidad_duelo_proponer(p_para uuid, p_proxima boolean default false) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_semana date := fbe_privado.comunidad_lunes() + case when p_proxima or extract(isodow from fbe_privado.comunidad_hoy()) = 7 then 7 else 0 end;
  v_yo fbe_privado.comunidad_dentro;
  v_el fbe_privado.comunidad_dentro;
  v_id uuid;
begin
  if v_uid is null or not public.comunidad_activa() or not public.comunidad_soy_miembro() then
    raise exception 'Para retar tienes que estar en la comunidad (y abierta)' using errcode = '42501';
  end if;
  if p_para is null or p_para = v_uid then raise exception 'A ti mismo ya te retas cada semana' using errcode = '22023'; end if;
  select * into v_yo from fbe_privado.comunidad_dentro d where d.perfil_id = v_uid;
  select * into v_el from fbe_privado.comunidad_dentro d where d.perfil_id = p_para;
  if v_el.perfil_id is null then raise exception 'Esa persona ya no está en el equipo' using errcode = '42501'; end if;
  if v_yo.sin_ranking or v_el.sin_ranking then raise exception 'Los duelos cuentan sesiones: los dos tenéis que salir en el ranking' using errcode = '22023'; end if;
  if (select count(*) from public.comunidad_duelos x where v_uid in (x.de, x.para) and x.estado <> 'rechazado' and x.semana + 6 >= fbe_privado.comunidad_hoy()) >= 3 then
    raise exception 'Como mucho tres duelos a la vez' using errcode = '54000';
  end if;
  if (select count(*) from public.comunidad_duelos x where p_para in (x.de, x.para) and x.estado <> 'rechazado' and x.semana + 6 >= fbe_privado.comunidad_hoy()) >= 3 then
    raise exception 'Esa persona ya tiene tres duelos: rétale más adelante' using errcode = '54000';
  end if;
  if exists (select 1 from public.comunidad_duelos x where least(x.de, x.para) = least(v_uid, p_para) and greatest(x.de, x.para) = greatest(v_uid, p_para) and x.semana = v_semana) then
    raise exception 'Ya tenéis un duelo esa semana' using errcode = '23505';
  end if;
  perform fbe_privado.comunidad_gastar_cupo('animo');
  insert into public.comunidad_duelos (de, para, de_atleta, para_atleta, semana) values (v_uid, p_para, v_yo.atleta_id, v_el.atleta_id, v_semana) returning id into v_id;
  perform fbe_privado.notificar_seguro(p_para, 'comunidad', fbe_privado.comunidad_nombre(v_uid) || ' te reta a un duelo ⚔️',
    'Quién hace más sesiones ' || case when v_semana > fbe_privado.comunidad_lunes() then 'la semana que viene' else 'esta semana' end || '. Acéptalo en Equipo.',
    '#equipo', 'comunidad_duelo:' || v_id, null, (v_semana + 7)::timestamp at time zone 'Europe/Madrid');
  return v_id;
end $$;

-- Aceptar o rechazar un duelo que me han propuesto
create or replace function public.comunidad_duelo_responder(p_id uuid, p_acepta boolean) returns text
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  x public.comunidad_duelos;
begin
  if v_uid is null or not public.comunidad_soy_miembro() then raise exception 'No estás en la comunidad' using errcode = '42501'; end if;
  select * into x from public.comunidad_duelos d where d.id = p_id and d.para = v_uid and d.estado = 'pendiente';
  if not found then raise exception 'Ese duelo ya no está pendiente' using errcode = '22023'; end if;
  if x.semana + 6 < fbe_privado.comunidad_hoy() then raise exception 'Esa semana ya pasó' using errcode = '22023'; end if;
  if p_acepta then
    if not exists (select 1 from fbe_privado.comunidad_dentro d where d.perfil_id = x.de and not d.sin_ranking)
       or not exists (select 1 from fbe_privado.comunidad_dentro d where d.perfil_id = v_uid and not d.sin_ranking) then
      raise exception 'Los duelos cuentan sesiones: los dos tenéis que salir en el ranking' using errcode = '22023';
    end if;
    if (select count(*) from public.comunidad_duelos k where v_uid in (k.de, k.para) and k.estado <> 'rechazado' and k.id <> p_id
          and k.semana + 6 >= fbe_privado.comunidad_hoy()) >= 3 then
      raise exception 'Como mucho tres duelos a la vez' using errcode = '54000';
    end if;
  end if;
  update public.comunidad_duelos set estado = case when p_acepta then 'aceptado' else 'rechazado' end, respondido_en = now() where id = p_id;
  if p_acepta then
    perform fbe_privado.notificar_seguro(x.de, 'comunidad', fbe_privado.comunidad_nombre(v_uid) || ' acepta el duelo ⚔️', 'Que gane quien más entrene. Míralo en Equipo.',
      '#equipo', 'comunidad_duelo_ok:' || x.id, null, (x.semana + 7)::timestamp at time zone 'Europe/Madrid');
  end if;
  return case when p_acepta then 'aceptado' else 'rechazado' end;
end $$;

-- Retirar un duelo que propuse (si aún está pendiente)
create or replace function public.comunidad_duelo_retirar(p_id uuid) returns void
language sql security definer set search_path = '' as $$
  delete from public.comunidad_duelos d where d.id = p_id and d.de = auth.uid() and d.estado = 'pendiente';
$$;

-- Mis duelos (de esta semana, la que viene y la pasada): con el rival, las sesiones de cada uno y, si la semana acabó, el
-- resultado. El coach ve los de todos (p_todos).
create or replace function public.comunidad_duelos_mios(p_todos boolean default false)
returns table (id uuid, semana date, estado text, soy_retador boolean, rival uuid, rival_nombre text, rival_foto text, yo uuid, yo_nombre text,
               mias integer, suyas integer, acabado boolean, creado_en timestamptz)
language sql stable security definer set search_path = '' as $$
  with mios as (
    select d.*, case when d.de = auth.uid() then d.para else d.de end as r, case when d.de = auth.uid() then d.de else d.para end as y
    from public.comunidad_duelos d
    where auth.uid() is not null and ((p_todos and public.es_coach()) or (auth.uid() in (d.de, d.para) and public.comunidad_soy_miembro()))
      and d.semana between fbe_privado.comunidad_lunes() - 7 and fbe_privado.comunidad_lunes() + 7
  ), hechas as (
    select v.atleta_id, v.fecha from fbe_privado.comunidad_sesiones_validas(array(select m.de_atleta from mios m union select m.para_atleta from mios m)) v
  )
  select m.id, m.semana, m.estado, m.de = auth.uid(),
    m.r, coalesce(dr.nombre, 'Alguien del equipo'), case when public.es_coach() or dr.perfil_id is not null then pr.foto end,
    m.y, coalesce(dy.nombre, 'Alguien del equipo'),
    (select count(*)::integer from hechas h where h.atleta_id = case when m.de = auth.uid() then m.de_atleta else m.para_atleta end and h.fecha between m.semana and m.semana + 6),
    -- las del rival, solo si sigue dentro y en el ranking (o lo mira el coach)
    case when public.es_coach() or (dr.perfil_id is not null and not dr.sin_ranking) then
      (select count(*)::integer from hechas h where h.atleta_id = case when m.de = auth.uid() then m.para_atleta else m.de_atleta end and h.fecha between m.semana and m.semana + 6) end,
    m.semana + 6 < fbe_privado.comunidad_hoy(), m.creado_en
  from mios m
  left join fbe_privado.comunidad_dentro dr on dr.perfil_id = m.r
  left join fbe_privado.comunidad_dentro dy on dy.perfil_id = m.y
  left join public.perfiles pr on pr.id = m.r
  order by m.semana desc, m.creado_en desc
$$;

-- ---------------------------------------------------------------------
-- 6. «Hoy entreno a las…»
-- ---------------------------------------------------------------------
create table if not exists public.comunidad_intenciones (
  perfil_id  uuid primary key references public.perfiles(id) on delete cascade,
  atleta_id  uuid references public.atletas(id) on delete cascade,
  fecha      date not null,
  hora       time,
  nota       text check (nota is null or (char_length(nota) between 1 and 40 and public.texto_visible(nota) and nota !~ '[[:cntrl:]]')),
  creado_en  timestamptz not null default now()
);
alter table public.comunidad_intenciones enable row level security;
drop policy if exists coach_ver on public.comunidad_intenciones;
create policy coach_ver on public.comunidad_intenciones for select to authenticated using (public.es_coach());
drop policy if exists mia_ver on public.comunidad_intenciones;
create policy mia_ver on public.comunidad_intenciones for select to authenticated using (perfil_id = auth.uid());

-- Decir cuándo entreno (hoy o mañana; sin fecha, lo quito)
create or replace function public.comunidad_intencion(p_fecha date default null, p_hora time default null, p_nota text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_nota text := nullif(btrim(regexp_replace(coalesce(p_nota, ''), '\s+', ' ', 'g')), '');
begin
  if v_uid is null or not public.comunidad_activa() or not public.comunidad_soy_miembro() then raise exception 'No estás en la comunidad' using errcode = '42501'; end if;
  delete from public.comunidad_intenciones i where i.fecha < fbe_privado.comunidad_hoy();
  if p_fecha is null then
    delete from public.comunidad_intenciones i where i.perfil_id = v_uid;
    return null;
  end if;
  if p_fecha not between fbe_privado.comunidad_hoy() and fbe_privado.comunidad_hoy() + 1 then raise exception 'Hoy o mañana' using errcode = '22023'; end if;
  if v_nota is not null and char_length(v_nota) > 40 then raise exception 'La nota, hasta 40 letras' using errcode = '22023'; end if;
  if v_nota is not null and fbe_privado.comunidad_moderar_entrada(v_uid, false, v_nota) then
    raise exception 'Esas palabras no pueden ir en la nota' using errcode = '22023';
  end if;
  insert into public.comunidad_intenciones (perfil_id, atleta_id, fecha, hora, nota) values (v_uid, public.mi_atleta_id(), p_fecha, p_hora, v_nota)
  on conflict (perfil_id) do update set fecha = excluded.fecha, hora = excluded.hora, nota = excluded.nota, creado_en = now();
  return jsonb_build_object('fecha', p_fecha, 'hora', p_hora, 'nota', v_nota);
end $$;

-- Quién ha dicho cuándo entrena (hoy y mañana), de los que están dentro
create or replace function public.comunidad_intenciones()
returns table (perfil_id uuid, nombre text, foto text, fecha date, hora time, nota text, soy_yo boolean)
language sql stable security definer set search_path = '' as $$
  select i.perfil_id, d.nombre, p.foto, i.fecha, i.hora, i.nota, i.perfil_id = auth.uid()
  from public.comunidad_intenciones i
  join fbe_privado.comunidad_dentro d on d.perfil_id = i.perfil_id
  join public.perfiles p on p.id = i.perfil_id
  where auth.uid() is not null and (public.es_coach() or public.comunidad_soy_miembro()) and i.fecha >= fbe_privado.comunidad_hoy()
  order by i.fecha, i.hora nulls last, d.nombre
$$;

-- ---------------------------------------------------------------------
-- 7. Apadrinar a quien entra
-- ---------------------------------------------------------------------
create table if not exists public.comunidad_padrinos (
  nuevo          uuid primary key references public.perfiles(id) on delete cascade,
  padrino        uuid not null references public.perfiles(id) on delete cascade,
  nuevo_atleta   uuid references public.atletas(id) on delete cascade,
  padrino_atleta uuid references public.atletas(id) on delete cascade,
  desde          date not null default (now() at time zone 'Europe/Madrid')::date,
  hasta          date not null,
  terminado_en   timestamptz,                          -- si uno de los dos lo dejó antes de tiempo (la fila se queda: cuenta para la insignia)
  creado_en      timestamptz not null default now(),
  check (nuevo <> padrino and hasta > desde)
);
alter table public.comunidad_padrinos add column if not exists terminado_en timestamptz;
create index if not exists comunidad_padrinos_padrino_idx on public.comunidad_padrinos (padrino);
alter table public.comunidad_padrinos enable row level security;
drop policy if exists coach_ver on public.comunidad_padrinos;
create policy coach_ver on public.comunidad_padrinos for select to authenticated using (public.es_coach());
drop policy if exists miembro_ver on public.comunidad_padrinos;
create policy miembro_ver on public.comunidad_padrinos for select to authenticated using (auth.uid() in (nuevo, padrino) and public.comunidad_soy_miembro());

-- Acompañar a alguien que acaba de entrar (menos de 14 días dentro), llevando yo 8 semanas o más; 30 días
create or replace function public.comunidad_apadrinar(p_nuevo uuid) returns date
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_mi_alta timestamptz;
  v_su_alta timestamptz;
  v_nuevo fbe_privado.comunidad_dentro;
  v_hasta date := fbe_privado.comunidad_hoy() + 30;
begin
  if v_uid is null or not public.comunidad_activa() or not public.comunidad_soy_miembro() then raise exception 'No estás en la comunidad' using errcode = '42501'; end if;
  if p_nuevo is null or p_nuevo = v_uid then raise exception 'A ti mismo no te puedes apadrinar' using errcode = '22023'; end if;
  select m.entrado_en into v_mi_alta from public.comunidad_miembros m where m.perfil_id = v_uid;
  if v_mi_alta > now() - interval '56 days' then raise exception 'Para acompañar a alguien hay que llevar 8 semanas en el equipo' using errcode = '22023'; end if;
  select * into v_nuevo from fbe_privado.comunidad_dentro d where d.perfil_id = p_nuevo;
  if v_nuevo.perfil_id is null then raise exception 'Esa persona ya no está en el equipo' using errcode = '42501'; end if;
  select m.entrado_en into v_su_alta from public.comunidad_miembros m where m.perfil_id = p_nuevo;
  if v_su_alta <= now() - interval '14 days' then raise exception 'Se acompaña a quien lleva menos de dos semanas en el equipo' using errcode = '22023'; end if;
  if exists (select 1 from public.comunidad_padrinos x where x.nuevo = p_nuevo and x.hasta >= fbe_privado.comunidad_hoy() and x.terminado_en is null) then
    raise exception 'Ya tiene quien le acompañe' using errcode = '23505';
  end if;
  if (select count(*) from public.comunidad_padrinos x where x.padrino = v_uid and x.hasta >= fbe_privado.comunidad_hoy() and x.terminado_en is null) >= 2 then
    raise exception 'Como mucho dos personas a la vez' using errcode = '54000';
  end if;
  insert into public.comunidad_padrinos (nuevo, padrino, nuevo_atleta, padrino_atleta, hasta) values (p_nuevo, v_uid, v_nuevo.atleta_id, public.mi_atleta_id(), v_hasta)
  on conflict (nuevo) do update set padrino = excluded.padrino, padrino_atleta = excluded.padrino_atleta, desde = fbe_privado.comunidad_hoy(), hasta = excluded.hasta, terminado_en = null, creado_en = now();
  perform fbe_privado.notificar_seguro(p_nuevo, 'comunidad', fbe_privado.comunidad_nombre(v_uid) || ' te acompaña tu primer mes 🤝',
    'Pregúntale lo que quieras: menciónale con @ en el muro. Míralo en Equipo.', '#equipo', 'comunidad_padrino:' || p_nuevo || ':' || v_uid);
  return v_hasta;
end $$;

-- Dejar de acompañar (el padrino) o soltarse (el nuevo)
create or replace function public.comunidad_padrino_quitar(p_nuevo uuid default null) returns void
language sql security definer set search_path = '' as $$
  update public.comunidad_padrinos x set terminado_en = now()
  where x.terminado_en is null and ((x.nuevo = coalesce(p_nuevo, auth.uid()) and x.padrino = auth.uid()) or (p_nuevo is null and x.nuevo = auth.uid()));
$$;

-- Quién acompaña a quién (vigentes), con nombres y fotos; y a quién puedo acompañar yo (nuevos sin padrino)
create or replace function public.comunidad_padrinos_lista() returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when auth.uid() is null or not (public.es_coach() or public.comunidad_soy_miembro()) then null else jsonb_build_object(
    'puedo', exists (select 1 from public.comunidad_miembros m where m.perfil_id = auth.uid() and m.entrado_en <= now() - interval '56 days'),
    'vigentes', coalesce((select jsonb_agg(jsonb_build_object('nuevo', x.nuevo, 'nuevo_nombre', dn.nombre, 'nuevo_foto', pn.foto,
                                                             'padrino', x.padrino, 'padrino_nombre', dp.nombre, 'padrino_foto', pp.foto,
                                                             'desde', x.desde, 'hasta', x.hasta) order by x.creado_en desc)
                          from public.comunidad_padrinos x
                          join fbe_privado.comunidad_dentro dn on dn.perfil_id = x.nuevo
                          join fbe_privado.comunidad_dentro dp on dp.perfil_id = x.padrino
                          join public.perfiles pn on pn.id = x.nuevo
                          join public.perfiles pp on pp.id = x.padrino
                          where x.hasta >= fbe_privado.comunidad_hoy() and x.terminado_en is null), '[]'::jsonb),
    'sin_padrino', coalesce((select jsonb_agg(jsonb_build_object('perfil_id', d.perfil_id, 'nombre', d.nombre, 'foto', p.foto, 'desde', m.entrado_en) order by m.entrado_en desc)
                             from fbe_privado.comunidad_dentro d
                             join public.comunidad_miembros m on m.atleta_id = d.atleta_id and m.entrado_en > now() - interval '14 days'
                             join public.perfiles p on p.id = d.perfil_id
                             where d.perfil_id <> auth.uid()
                               and not exists (select 1 from public.comunidad_padrinos x where x.nuevo = d.perfil_id and x.hasta >= fbe_privado.comunidad_hoy() and x.terminado_en is null)), '[]'::jsonb)
  ) end
$$;

-- ---------------------------------------------------------------------
-- 8. Compañero de la semana elegido por el equipo
-- ---------------------------------------------------------------------
create table if not exists public.comunidad_votos_semana (
  semana      date not null,
  de          uuid not null references public.perfiles(id) on delete cascade,
  para        uuid not null references public.perfiles(id) on delete cascade,
  de_atleta   uuid references public.atletas(id) on delete cascade,
  para_atleta uuid references public.atletas(id) on delete cascade,
  creado_en   timestamptz not null default now(),
  primary key (semana, de),
  check (de <> para)
);
create index if not exists comunidad_votos_semana_para_idx on public.comunidad_votos_semana (para, semana);
alter table public.comunidad_votos_semana enable row level security;
drop policy if exists coach_ver on public.comunidad_votos_semana;
create policy coach_ver on public.comunidad_votos_semana for select to authenticated using (public.es_coach());
drop policy if exists mio_ver on public.comunidad_votos_semana;
create policy mio_ver on public.comunidad_votos_semana for select to authenticated using (de = auth.uid());

-- Votar (o cambiar el voto) al compañero de esta semana
create or replace function public.comunidad_votar_companero(p_para uuid) returns date
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_semana date := fbe_privado.comunidad_lunes();
  v_para_atleta uuid;
begin
  if v_uid is null or not public.comunidad_activa() or not public.comunidad_soy_miembro() then raise exception 'Para votar tienes que estar en la comunidad (y abierta)' using errcode = '42501'; end if;
  if p_para is null then
    delete from public.comunidad_votos_semana v where v.de = v_uid and v.semana = v_semana;
    return v_semana;
  end if;
  if p_para = v_uid then raise exception 'A ti no te puedes votar' using errcode = '22023'; end if;
  select d.atleta_id into v_para_atleta from fbe_privado.comunidad_dentro d where d.perfil_id = p_para;
  if v_para_atleta is null then raise exception 'Esa persona ya no está en el equipo' using errcode = '42501'; end if;
  if not exists (select 1 from public.comunidad_votos_semana v where v.de = v_uid and v.semana = v_semana and v.para = p_para) then
    perform fbe_privado.comunidad_gastar_cupo('voto');
  end if;
  insert into public.comunidad_votos_semana (semana, de, para, de_atleta, para_atleta) values (v_semana, v_uid, p_para, public.mi_atleta_id(), v_para_atleta)
  on conflict (semana, de) do update set para = excluded.para, para_atleta = excluded.para_atleta, creado_en = now();
  return v_semana;
end $$;

-- El compañero de la semana pasada (con 2 votos o más; si empatan, todos), mi voto de esta y cuántos han votado ya
create or replace function public.comunidad_companero_semana() returns jsonb
language sql stable security definer set search_path = '' as $$
  with pasada as (
    select v.para, count(*) as n from public.comunidad_votos_semana v
    join fbe_privado.comunidad_dentro d on d.perfil_id = v.para
    join fbe_privado.comunidad_dentro dv on dv.perfil_id = v.de
    where v.semana = fbe_privado.comunidad_lunes() - 7 group by v.para
  ), tope as (select max(n) as n from pasada)
  select case when auth.uid() is null or not (public.es_coach() or public.comunidad_soy_miembro()) then null else jsonb_build_object(
    'semana', fbe_privado.comunidad_lunes() - 7,
    'elegidos', coalesce((select jsonb_agg(jsonb_build_object('perfil_id', p.para, 'nombre', d.nombre, 'foto', pf.foto, 'votos', p.n) order by d.nombre)
                          from pasada p join tope t on p.n = t.n join fbe_privado.comunidad_dentro d on d.perfil_id = p.para join public.perfiles pf on pf.id = p.para
                          where p.n >= 2), '[]'::jsonb),
    'mi_voto', (select v.para from public.comunidad_votos_semana v where v.de = auth.uid() and v.semana = fbe_privado.comunidad_lunes()),
    'votos', (select count(*) from public.comunidad_votos_semana v where v.semana = fbe_privado.comunidad_lunes()),
    'mis_veces', (select count(*) from (
                    select v.semana from public.comunidad_votos_semana v where v.para = auth.uid() and v.semana < fbe_privado.comunidad_lunes()
                    group by v.semana having count(*) >= 2
                      and count(*) = (select max(c) from (select count(*) as c from public.comunidad_votos_semana w where w.semana = v.semana group by w.para) z)) k)
  ) end
$$;

-- ---------------------------------------------------------------------
-- 9. Tu huella en el equipo (y las insignias sociales)
-- ---------------------------------------------------------------------
-- Las semanas seguidas (hasta esta o la pasada) con algún ánimo mandado
create or replace function fbe_privado.comunidad_semanas_animando(p_perfil uuid) returns integer
language plpgsql stable set search_path = '' as $$
declare
  v_l date := fbe_privado.comunidad_lunes();
  v_n integer := 0;
begin
  if not exists (select 1 from public.comunidad_animos a where a.de = p_perfil and a.semana = v_l) then v_l := v_l - 7; end if;
  while exists (select 1 from public.comunidad_animos a where a.de = p_perfil and a.semana = v_l) and v_n < 520 loop
    v_n := v_n + 1; v_l := v_l - 7;
  end loop;
  return v_n;
end $$;

-- Las veces que el equipo le eligió compañero de la semana (2 votos o más y el que más)
create or replace function fbe_privado.comunidad_veces_elegido(p_perfil uuid) returns integer
language sql stable set search_path = '' as $$
  select count(*)::integer from (
    select v.semana from public.comunidad_votos_semana v where v.para = p_perfil and v.semana < fbe_privado.comunidad_lunes()
    group by v.semana having count(*) >= 2
      and count(*) = (select max(c) from (select count(*) as c from public.comunidad_votos_semana w where w.semana = v.semana group by w.para) z)) k
$$;

create or replace function public.comunidad_huella(p_perfil uuid default null) returns jsonb
language sql stable security definer set search_path = '' as $$
  with quien as (
    select coalesce(p_perfil, auth.uid()) as id
  )
  select case when auth.uid() is null or not (public.es_coach() or public.comunidad_soy_miembro())
                or not exists (select 1 from fbe_privado.comunidad_dentro d, quien q where d.perfil_id = q.id) then null
    else jsonb_build_object(
    'desde', (select m.creado_en from public.comunidad_miembros m, quien q where m.perfil_id = q.id),
    'animos_dados', (select count(*) from public.comunidad_animos a, quien q where a.de = q.id),
    'animos_recibidos', (select count(*) from public.comunidad_animos a, quien q where a.para = q.id),
    'bienvenidas', (select count(*) from public.comunidad_bienvenidas b, quien q where b.de = q.id),
    'comentarios', (select count(*) from public.comunidad_comentarios c, quien q where c.autor_id = q.id and not c.oculto),
    'reacciones', (select count(*) from public.comunidad_reacciones r, quien q where r.autor_id = q.id),
    'quedadas', (select count(*) from public.comunidad_evento_asistentes a join public.comunidad_eventos e on e.id = a.evento_id, quien q
                 where a.perfil_id = q.id and a.va and e.cancelado_en is null and e.empieza_en < now()),
    'ahijados', (select count(*) from public.comunidad_padrinos x, quien q where x.padrino = q.id),
    'elegido', (select fbe_privado.comunidad_veces_elegido(q.id) from quien q),
    'semanas_animando', (select fbe_privado.comunidad_semanas_animando(q.id) from quien q),
    'duelos_ganados', (select count(*) from public.comunidad_duelos d, quien q
                       where q.id in (d.de, d.para) and d.estado = 'aceptado' and d.semana + 6 < fbe_privado.comunidad_hoy()
                         and (select count(*) from fbe_privado.comunidad_sesiones_validas(array[case when d.de = q.id then d.de_atleta else d.para_atleta end]) v where v.fecha between d.semana and d.semana + 6)
                           > (select count(*) from fbe_privado.comunidad_sesiones_validas(array[case when d.de = q.id then d.para_atleta else d.de_atleta end]) v where v.fecha between d.semana and d.semana + 6))
  ) end
$$;

-- Las insignias (042/045), con las sociales
create or replace function fbe_privado.comunidad_insignias_de(p_atleta uuid, p_perfil uuid)
returns table (clave text, valor integer, meta integer)
language sql stable security definer set search_path = '' as $$
  select 'primera_publicacion'::text, (select count(*)::integer from public.comunidad_posts x where x.autor_id = p_perfil and not x.oculta and x.tipo <> 'aniversario'), 1
  union all
  select 'animos_10', (select count(*)::integer from public.comunidad_animos a where a.de = p_perfil), 10
  union all
  select 'reacciones_25', (select count(*)::integer from public.comunidad_reacciones r where r.autor_id = p_perfil), 25
  union all
  select 'retos_5', (select count(*)::integer from public.comunidad_retos r where fbe_privado.comunidad_reto_conseguido(r.id, p_atleta)), 5
  union all
  select 'racha_4', coalesce((select p.mejor from fbe_privado.comunidad_rachas_pareja(p_atleta, p_atleta, null) p), 0), 4
  union all
  select 'pareja_4', coalesce((
    select max(p.mejor) from public.comunidad_companeros c
    join fbe_privado.comunidad_dentro o on o.perfil_id = case when c.de = p_perfil then c.para else c.de end
    cross join lateral fbe_privado.comunidad_rachas_pareja(p_atleta, o.atleta_id, (c.aceptado_en at time zone 'Europe/Madrid')::date) p
    where c.estado = 'aceptada' and p_perfil in (c.de, c.para)), 0), 4
  union all
  select 'animador_25', (select count(*)::integer from public.comunidad_animos a where a.de = p_perfil), 25
  union all
  select 'anfitrion_3', (select count(*)::integer from public.comunidad_bienvenidas b where b.de = p_perfil), 3
  union all
  select 'padrino_1', (select count(*)::integer from public.comunidad_padrinos x where x.padrino = p_perfil), 1
  union all
  select 'puntual_3', (select count(*)::integer from public.comunidad_evento_asistentes a join public.comunidad_eventos e on e.id = a.evento_id
                       where a.perfil_id = p_perfil and a.va and e.cancelado_en is null and e.empieza_en < now()), 3
$$;

-- ---------------------------------------------------------------------
-- 10. Quién necesita un ánimo (solo quien lo enciende)
-- ---------------------------------------------------------------------
create or replace function public.comunidad_sin_entrenar()
returns table (perfil_id uuid, nombre text, foto text, dias integer)
language sql stable security definer set search_path = '' as $$
  with gente as (
    select d.atleta_id, d.perfil_id, d.nombre, m.entrado_en as creado_en
    from fbe_privado.comunidad_dentro d
    join public.comunidad_miembros m on m.atleta_id = d.atleta_id and m.ver_ausencia
    where d.perfil_id <> auth.uid()
  ), ultima as (
    select v.atleta_id, max(v.fecha) as fecha from fbe_privado.comunidad_sesiones_validas(array(select g.atleta_id from gente g)) v group by v.atleta_id
  )
  select g.perfil_id, g.nombre, p.foto,
    (fbe_privado.comunidad_hoy() - coalesce(u.fecha, (g.creado_en at time zone 'Europe/Madrid')::date))::integer
  from gente g
  left join ultima u on u.atleta_id = g.atleta_id
  join public.perfiles p on p.id = g.perfil_id
  join public.atletas a on a.id = g.atleta_id and a.entrenamiento
  where auth.uid() is not null and (public.es_coach() or public.comunidad_soy_miembro())
    and fbe_privado.comunidad_hoy() - coalesce(u.fecha, (g.creado_en at time zone 'Europe/Madrid')::date) >= 5
  order by 4 desc, g.nombre
  limit 10
$$;

-- ---------------------------------------------------------------------
-- 10b. Al dejar el equipo (salir, que el coach le saque, la baja o la ficha que cambia de dueño) o el ranking, lo social
-- vivo se va: la intención, los duelos y el padrinazgo, y sus quedadas abiertas se cancelan (como las parejas, 042).
-- ---------------------------------------------------------------------
create or replace function fbe_privado.comunidad_social_al_dejar() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v uuid;
  v_fuera boolean;
begin
  if tg_table_name = 'comunidad_miembros' then
    v := new.perfil_id;
    if new.sin_ranking and not old.sin_ranking then
      delete from public.comunidad_duelos where v in (de, para) and semana + 6 >= fbe_privado.comunidad_hoy();
    end if;
    v_fuera := (new.salido_en is not null and old.salido_en is null) or (new.bloqueado and not old.bloqueado);
    if not v_fuera and not (new.version is distinct from old.version and new.version is distinct from public.comunidad_version()) then
      return null;
    end if;
  else
    v := old.perfil_id;
    v_fuera := true;
    if v is null or not ((new.estado = 'baja' and old.estado <> 'baja') or new.perfil_id is distinct from old.perfil_id) then return null; end if;
  end if;
  delete from public.comunidad_intenciones where perfil_id = v;
  delete from public.comunidad_duelos where v in (de, para) and semana + 6 >= fbe_privado.comunidad_hoy();
  update public.comunidad_padrinos set terminado_en = coalesce(terminado_en, now()) where v in (nuevo, padrino) and hasta >= fbe_privado.comunidad_hoy();
  if v_fuera then
    update public.comunidad_eventos set cancelado_en = now() where creado_por = v and cancelado_en is null and empieza_en > now();
  end if;
  return null;
end $$;
drop trigger if exists comunidad_miembros_zzz_social on public.comunidad_miembros;
create trigger comunidad_miembros_zzz_social after update of salido_en, bloqueado, version, sin_ranking on public.comunidad_miembros
  for each row execute function fbe_privado.comunidad_social_al_dejar();
drop trigger if exists atletas_zzz_social on public.atletas;
create trigger atletas_zzz_social after update of estado, perfil_id on public.atletas
  for each row execute function fbe_privado.comunidad_social_al_dejar();

-- ---------------------------------------------------------------------
-- 11. Salir borrando lo suyo (044) y mis datos (044), con lo de aquí
-- ---------------------------------------------------------------------
create or replace function public.comunidad_salir(p_borrar boolean default false) returns text[]
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_fotos text[] := '{}';
begin
  if v_uid is null then raise exception 'Necesitas iniciar sesión' using errcode = '42501'; end if;
  update public.comunidad_miembros set salido_en = now() where perfil_id = v_uid and salido_en is null;
  delete from public.comunidad_companeros where de = v_uid or para = v_uid;
  -- (053) lo que solo tiene sentido estando dentro se va siempre
  delete from public.comunidad_intenciones where perfil_id = v_uid;
  delete from public.comunidad_duelos where (de = v_uid or para = v_uid) and semana + 6 >= fbe_privado.comunidad_hoy();
  update public.comunidad_padrinos set terminado_en = coalesce(terminado_en, now()) where (nuevo = v_uid or padrino = v_uid) and hasta >= fbe_privado.comunidad_hoy();
  if coalesce(p_borrar, false) and not exists (select 1 from public.perfiles p where p.id = v_uid and p.rol = 'coach') then
    select coalesce(array_agg(distinct f.ruta) filter (where f.ruta is not null), '{}') into v_fotos
    from public.comunidad_posts x
    cross join lateral unnest(coalesce(x.fotos, array[x.foto_ruta])) as f(ruta)
    where x.autor_id = v_uid
      and not exists (select 1 from public.comunidad_reportes r where (r.copia_foto = f.ruta or r.copia_fotos @> array[f.ruta]) and r.resuelto_en is null);
    delete from public.comunidad_reacciones where autor_id = v_uid;
    delete from public.comunidad_comentario_reacciones where autor_id = v_uid;
    delete from public.comunidad_votos where autor_id = v_uid;
    delete from public.comunidad_animos where de = v_uid or para = v_uid;
    delete from public.comunidad_bienvenidas where de = v_uid or para = v_uid;
    delete from public.comunidad_guardados where perfil_id = v_uid;
    delete from public.comunidad_evento_asistentes where perfil_id = v_uid;
    delete from public.comunidad_duelos where de = v_uid or para = v_uid;
    delete from public.comunidad_padrinos where nuevo = v_uid or padrino = v_uid;
    delete from public.comunidad_votos_semana where de = v_uid or para = v_uid;
    update public.comunidad_eventos set cancelado_en = coalesce(cancelado_en, now()) where creado_por = v_uid and empieza_en > now();
    delete from public.comunidad_eventos where creado_por = v_uid;   -- el aviso de que se cancela ya ha salido
    delete from public.comunidad_comentarios where autor_id = v_uid;
    delete from public.comunidad_posts where autor_id = v_uid;
  end if;
  return v_fotos;
end $$;

create or replace function public.comunidad_mis_datos() returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when auth.uid() is null then null else jsonb_build_object(
    'miembro', (select to_jsonb(m) - 'perfil_id' from public.comunidad_miembros m where m.perfil_id = auth.uid()),
    'publicaciones', coalesce((select jsonb_agg((to_jsonb(x) - 'menciones') || jsonb_build_object('menciones', cardinality(x.menciones)) order by x.creado_en)
                               from public.comunidad_posts x where x.autor_id = auth.uid()), '[]'::jsonb),
    'comentarios', coalesce((select jsonb_agg((to_jsonb(c) - 'menciones') || jsonb_build_object('menciones', cardinality(c.menciones)) order by c.creado_en)
                             from public.comunidad_comentarios c where c.autor_id = auth.uid()), '[]'::jsonb),
    'reacciones', coalesce((select jsonb_agg(to_jsonb(r) order by r.creado_en) from public.comunidad_reacciones r where r.autor_id = auth.uid()), '[]'::jsonb),
    'reacciones_comentarios', coalesce((select jsonb_agg(jsonb_build_object('comentario_id', r.comentario_id, 'creado_en', r.creado_en) order by r.creado_en)
                                        from public.comunidad_comentario_reacciones r where r.autor_id = auth.uid()), '[]'::jsonb),
    'votos', coalesce((select jsonb_agg(to_jsonb(v) order by v.creado_en) from public.comunidad_votos v where v.autor_id = auth.uid()), '[]'::jsonb),
    'animos_mandados', coalesce((select jsonb_agg(
                                   case when exists (select 1 from fbe_privado.comunidad_dentro d where d.perfil_id = a.para)
                                        then jsonb_build_object('para', a.para, 'para_nombre', fbe_privado.comunidad_nombre(a.para), 'semana', a.semana, 'creado_en', a.creado_en, 'texto', a.texto)
                                        else jsonb_build_object('para_nombre', 'Alguien del equipo', 'semana', a.semana, 'creado_en', a.creado_en, 'texto', a.texto) end
                                   order by a.creado_en)
                                 from public.comunidad_animos a where a.de = auth.uid()), '[]'::jsonb),
    'animos_recibidos', coalesce((select jsonb_agg(jsonb_build_object('semana', a.semana, 'creado_en', a.creado_en, 'texto', a.texto) order by a.creado_en)
                                  from public.comunidad_animos a where a.para = auth.uid()), '[]'::jsonb),
    'bienvenidas_dadas', coalesce((select jsonb_agg(
                                     case when exists (select 1 from fbe_privado.comunidad_dentro d where d.perfil_id = b.para)
                                          then jsonb_build_object('para', b.para, 'para_nombre', fbe_privado.comunidad_nombre(b.para), 'creado_en', b.creado_en)
                                          else jsonb_build_object('para_nombre', 'Alguien del equipo', 'creado_en', b.creado_en) end
                                     order by b.creado_en)
                                   from public.comunidad_bienvenidas b where b.de = auth.uid()), '[]'::jsonb),
    'bienvenidas_recibidas', coalesce((select jsonb_agg(jsonb_build_object('creado_en', b.creado_en) order by b.creado_en)
                                       from public.comunidad_bienvenidas b where b.para = auth.uid()), '[]'::jsonb),
    'companeros', coalesce((select jsonb_agg(jsonb_build_object(
                              'con', case when exists (select 1 from fbe_privado.comunidad_dentro d where d.perfil_id = case when k.de = auth.uid() then k.para else k.de end)
                                          then fbe_privado.comunidad_nombre(case when k.de = auth.uid() then k.para else k.de end) else 'Alguien del equipo' end,
                              'estado', k.estado, 'invitaste', k.de = auth.uid(), 'creado_en', k.creado_en, 'aceptado_en', k.aceptado_en) order by k.creado_en)
                            from public.comunidad_companeros k where auth.uid() in (k.de, k.para)), '[]'::jsonb),
    'guardados', coalesce((select jsonb_agg(jsonb_build_object('post_id', g.post_id, 'creado_en', g.creado_en) order by g.creado_en)
                           from public.comunidad_guardados g where g.perfil_id = auth.uid()), '[]'::jsonb),
    'preguntas_frecuentes', coalesce((select jsonb_agg(jsonb_build_object('post_id', q.post_id, 'pregunta', q.pregunta, 'respuesta', q.respuesta, 'creado_en', q.creado_en) order by q.creado_en)
                                      from public.comunidad_preguntas q join public.comunidad_posts x on x.id = q.post_id where x.autor_id = auth.uid()), '[]'::jsonb),
    'eventos', coalesce((select jsonb_agg(jsonb_build_object('evento', e.titulo, 'empieza_en', e.empieza_en, 'va', a.va, 'creado_en', a.creado_en, 'propuesta_mia', e.creado_por = auth.uid()) order by a.creado_en)
                         from public.comunidad_evento_asistentes a join public.comunidad_eventos e on e.id = a.evento_id where a.perfil_id = auth.uid()), '[]'::jsonb),
    'quedadas_propuestas', coalesce((select jsonb_agg(jsonb_build_object('titulo', e.titulo, 'empieza_en', e.empieza_en, 'lugar', e.lugar, 'cancelado_en', e.cancelado_en, 'creado_en', e.creado_en) order by e.creado_en)
                                     from public.comunidad_eventos e where e.creado_por = auth.uid()), '[]'::jsonb),
    'atleta_de_la_semana', coalesce((select jsonb_agg(jsonb_build_object('motivo', k.motivo, 'desde', k.desde, 'hasta', k.hasta) order by k.desde)
                                     from public.comunidad_destacados k where k.perfil_id = auth.uid()), '[]'::jsonb),
    'avisos_al_coach', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'post_id', r.post_id, 'comentario_id', r.comentario_id, 'motivo', r.motivo,
                                   'creado_en', r.creado_en, 'resuelto_en', r.resuelto_en) order by r.creado_en)
                                 from public.comunidad_reportes r where r.autor_id = auth.uid()), '[]'::jsonb),
    'duelos', coalesce((select jsonb_agg(jsonb_build_object(
                          'con', case when exists (select 1 from fbe_privado.comunidad_dentro d where d.perfil_id = case when k.de = auth.uid() then k.para else k.de end)
                                      then fbe_privado.comunidad_nombre(case when k.de = auth.uid() then k.para else k.de end) else 'Alguien del equipo' end,
                          'semana', k.semana, 'estado', k.estado, 'retaste', k.de = auth.uid(), 'creado_en', k.creado_en) order by k.creado_en)
                        from public.comunidad_duelos k where auth.uid() in (k.de, k.para)), '[]'::jsonb),
    'intencion', (select jsonb_build_object('fecha', i.fecha, 'hora', i.hora, 'nota', i.nota) from public.comunidad_intenciones i where i.perfil_id = auth.uid()),
    'padrinos', coalesce((select jsonb_agg(jsonb_build_object(
                            'con', case when exists (select 1 from fbe_privado.comunidad_dentro d where d.perfil_id = case when x.nuevo = auth.uid() then x.padrino else x.nuevo end)
                                        then fbe_privado.comunidad_nombre(case when x.nuevo = auth.uid() then x.padrino else x.nuevo end) else 'Alguien del equipo' end,
                            'soy_padrino', x.padrino = auth.uid(), 'desde', x.desde, 'hasta', x.hasta, 'terminado_en', x.terminado_en) order by x.creado_en)
                          from public.comunidad_padrinos x where auth.uid() in (x.nuevo, x.padrino)), '[]'::jsonb),
    'votos_companero', coalesce((select jsonb_agg(jsonb_build_object('semana', v.semana,
                                   'a', case when exists (select 1 from fbe_privado.comunidad_dentro d where d.perfil_id = v.para) then fbe_privado.comunidad_nombre(v.para) else 'Alguien del equipo' end,
                                   'creado_en', v.creado_en) order by v.semana)
                                 from public.comunidad_votos_semana v where v.de = auth.uid()), '[]'::jsonb),
    'veces_elegido', fbe_privado.comunidad_veces_elegido(auth.uid())
  ) end
$$;

-- ---------------------------------------------------------------------
-- 12. Nadie toca las tablas nuevas directamente; permisos (como al final de 003 a 052)
-- ---------------------------------------------------------------------
revoke all on public.comunidad_duelos, public.comunidad_intenciones, public.comunidad_padrinos, public.comunidad_votos_semana from public, anon;
grant select on public.comunidad_duelos, public.comunidad_intenciones, public.comunidad_padrinos, public.comunidad_votos_semana to authenticated;
revoke insert, update, delete on public.comunidad_duelos, public.comunidad_intenciones, public.comunidad_padrinos, public.comunidad_votos_semana from authenticated;

revoke truncate, references, trigger on all tables in schema public from public, anon, authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated, service_role;
revoke execute on function public.crear_recordatorios(timestamptz), public.notificaciones_por_enviar(integer, boolean),
  public.notificaciones_resultado(jsonb), public.salud_recibir(text, jsonb), public.calendario_de(text) from public, anon, authenticated;
-- (las del reloj, 052: solo si están; así la 053 vale también en una base que aún no tenga la 052 puesta al día)
do $$
declare f text;
begin
  for f in select p.oid::regprocedure::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('reloj_estado', 'reloj_serie', 'reloj_saltar', 'reloj_elegir', 'reloj_terminar') loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
  end loop;
end $$;
revoke all on all functions in schema fbe_privado from public, anon, authenticated;

insert into public.fbe_migraciones (numero) values (53)  -- (3) número de esta migración
  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/054_cierre.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 054: lo que el coach necesita de cada entreno, sin pedirlo dos veces (tanda «cierre»)
--
-- Por qué: de las sesiones terminadas en la app, la mitad se queda sin esfuerzo (RPE) ni duración, y las herramientas
-- estructuradas del coach (check-in, revisión semanal, tareas, hábitos) no compiten con el chat. Esta migración pone la parte
-- de base de esa tanda; lo demás va en la app.
--
-- Qué hace:
--   * sesiones.cerrada_sola_en: la sesión que el atleta dejó con todas las series hechas y 3 horas sin tocar se cierra sola
--     (fbe_privado.sesiones_cerrar_solas, desde crear_recordatorios): duración de la primera a la última serie, esfuerzo
--     estimado con la media de sus series (solo si no lo puso) y aviso «La hemos cerrado por ti». Se puede corregir después.
--   * El coach recibe por la mañana un aviso con los vídeos de técnica que llevan 3 días o más sin revisar.
--   * atleta_resumen_semana(atleta, lunes): lo de la semana de un atleta en una consulta (sesiones hechas y previstas, esfuerzo
--     medio, series y toneladas, peso y su cambio, check-in, vídeos sin revisar, sesiones sin cerrar): para la cabecera del
--     chat del coach y para «tu semana de un vistazo» en el check-in. El coach, de cualquiera; el atleta, la suya.
--   * sesiones_abiertas(atleta): las sesiones con series y sin terminar de los últimos 14 días (el coach, de todos).
--   * bloques.objetivo_logrado: al acabar el bloque, el coach marca si el objetivo se consiguió (lo ve el atleta en el informe).
--   * habitos.origen ('coach' | 'sugerido') y habito_sugerido_activar(...): el atleta activa con un toque un hábito sugerido
--     por la app según su cuestionario (hasta 5 activos); el coach ve cuáles eligió él.
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 053 (o con instalar.sql en una base nueva).
-- Se puede repetir sin romper nada. (La del reloj, cuando entre, pasa a ser la 055.)
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 54 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 054 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 54;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 53) then  -- (2) la anterior
    raise exception 'Falta la migración 053 (esta base va por la %). Ejecuta las migraciones en orden.', to_char(coalesce(v, 0), 'FM000');
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. Columnas nuevas
-- ---------------------------------------------------------------------
alter table public.sesiones add column if not exists cerrada_sola_en timestamptz;
alter table public.bloques add column if not exists objetivo_logrado boolean;
alter table public.habitos add column if not exists origen text not null default 'coach';
alter table public.habitos drop constraint if exists habitos_origen_valido;
alter table public.habitos add constraint habitos_origen_valido check (origen in ('coach', 'sugerido'));
-- Índices para lo que mira crear_recordatorios cada minuto: las series recientes y los vídeos de técnica sin revisar
create index if not exists series_registrada_idx on public.series (registrada_en);
create index if not exists archivos_tecnica_sin_revisar_idx on public.archivos (creado_en) where tipo = 'video_tecnica' and revisado_en is null;

-- cerrada_sola_en solo la pone la base: el atleta no la pone ni la quita; si él mismo la termina, deja de estar «cerrada sola»
create or replace function public.sesion_proteger_cierre() returns trigger
language plpgsql set search_path = '' as $$
begin
  if current_user in ('authenticated', 'anon') and not public.es_coach() then
    if tg_op = 'INSERT' then
      new.cerrada_sola_en := null;
    elsif new.completada and not old.completada then
      new.cerrada_sola_en := null;
    else
      new.cerrada_sola_en := old.cerrada_sola_en;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists sesiones_r_proteger_cierre on public.sesiones;
create trigger sesiones_r_proteger_cierre before insert or update on public.sesiones
  for each row execute function public.sesion_proteger_cierre();

-- ---------------------------------------------------------------------
-- 2. Las sesiones que se quedaron sin cerrar
-- ---------------------------------------------------------------------
-- Candidatas: no terminadas, con ejercicios, todas las series pautadas con su serie guardada, la última hace 3 horas o más
-- (y menos de 7 días: lo más viejo se deja como está, por si fue a propósito). Duración: de la primera a la última serie más
-- 5 minutos (entre 10 y 240). Esfuerzo: la media de las series con RPE, redondeada, solo si el atleta no lo había puesto.
-- Fecha: el día (de Madrid) de la última serie. Avisa al atleta (tipo «sesion_hoy», que es el de sus sesiones) y devuelve cuántas.
create or replace function fbe_privado.sesiones_cerrar_solas(p_ahora timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_n integer := 0;
  r record;
begin
  for r in
    with con_series as (
      select s.id, s.nombre, w.bloque_id,
             min(x.registrada_en) as primera, max(x.registrada_en) as ultima,
             round(avg(x.rpe) filter (where x.rpe is not null and x.rpe > 0)) as rpe_medio
      from public.sesiones s
      join public.semanas w on w.id = s.semana_id and w.programacion = 'programada'
      join public.sesion_ejercicios se on se.sesion_id = s.id
      join public.series x on x.sesion_ejercicio_id = se.id
      where not s.completada and s.cerrada_sola_en is null
        and s.id in (select se4.sesion_id from public.series x4 join public.sesion_ejercicios se4 on se4.id = x4.sesion_ejercicio_id
                     where x4.registrada_en > p_ahora - interval '7 days')
      group by s.id, s.nombre, w.bloque_id
      having max(x.registrada_en) <= p_ahora - interval '3 hours' and max(x.registrada_en) > p_ahora - interval '7 days'
    )
    select c.*, b.atleta_id, p.id as perfil_id,
           case when pn.usuario_id is null then fbe_privado.fuera_de_silencio(p_ahora, time '22:30', time '08:00')
                else fbe_privado.fuera_de_silencio(p_ahora, pn.silencio_desde, pn.silencio_hasta) end as avisar_desde
    from con_series c
    join public.bloques b on b.id = c.bloque_id and not b.es_plantilla and b.estado <> 'cancelado'
    join public.atletas a on a.id = b.atleta_id and a.estado <> 'baja'
    left join public.perfiles p on p.id = a.perfil_id
    left join public.preferencias_notificaciones pn on pn.usuario_id = a.perfil_id
    where not exists (
      -- alguna pautada sin todas sus series
      select 1 from public.sesion_ejercicios se2
      where se2.sesion_id = c.id
        and (select count(*) from public.series x2 where x2.sesion_ejercicio_id = se2.id) < se2.series)
  loop
    update public.sesiones s
    set completada = true,
        fecha_realizada = coalesce(s.fecha_realizada, (r.ultima at time zone 'Europe/Madrid')::date),
        duracion_min = coalesce(s.duracion_min, greatest(10, least(240, ceil(extract(epoch from (r.ultima - r.primera)) / 60)::integer + 5))),
        rpe_sesion = coalesce(s.rpe_sesion, r.rpe_medio::smallint),
        cerrada_sola_en = p_ahora
    where s.id = r.id and not s.completada;
    if found then
      v_n := v_n + 1;
      if r.perfil_id is not null then
        perform fbe_privado.notificar_seguro(r.perfil_id, 'sesion_hoy', 'Hemos cerrado ' || coalesce(r.nombre, 'tu sesión') || ' por ti',
          'Tenías todas las series hechas. Si quieres, añade cómo fue (esfuerzo y nota) en Hoy.', '#hoy',
          'sesion_cerrada:' || r.id, r.avisar_desde, r.avisar_desde + interval '2 days');
      end if;
    end if;
  end loop;
  return v_n;
end $$;

-- Las sesiones con series guardadas y sin terminar (últimos 14 días): el coach, de todos (o de uno); el atleta, las suyas
create or replace function public.sesiones_abiertas(p_atleta uuid default null)
returns table (sesion_id uuid, atleta_id uuid, nombre text, ultima_serie timestamptz, series_hechas integer, series_pautadas integer, semana_inicio date)
language sql stable security definer set search_path = '' as $$
  select s.id, b.atleta_id, s.nombre, max(x.registrada_en), count(x.id)::integer,
         (select coalesce(sum(se2.series), 0) from public.sesion_ejercicios se2 where se2.sesion_id = s.id)::integer, w.fecha_inicio
  from public.sesiones s
  join public.semanas w on w.id = s.semana_id
  join public.bloques b on b.id = w.bloque_id
  join public.sesion_ejercicios se on se.sesion_id = s.id
  join public.series x on x.sesion_ejercicio_id = se.id
  where auth.uid() is not null and not s.completada
    and (p_atleta is null or b.atleta_id = p_atleta)
    and (public.es_coach() or b.atleta_id = public.mi_atleta_id())
  group by s.id, b.atleta_id, s.nombre, w.fecha_inicio
  having max(x.registrada_en) > now() - interval '14 days'
  order by max(x.registrada_en) desc
$$;

-- ---------------------------------------------------------------------
-- 3. La semana de un atleta, de un vistazo
-- ---------------------------------------------------------------------
create or replace function public.atleta_resumen_semana(p_atleta uuid, p_lunes date default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_lunes date := coalesce(p_lunes, (now() at time zone 'Europe/Madrid')::date - (extract(isodow from (now() at time zone 'Europe/Madrid'))::integer - 1));
  v_domingo date;
  v_sesiones jsonb;
  v_peso jsonb;
  v_checkin jsonb;
  v_videos integer;
  v_abiertas integer;
  v_sin_leer integer;
begin
  if auth.uid() is null or p_atleta is null or not coalesce(public.es_coach() or p_atleta = public.mi_atleta_id(), false) then return null; end if;
  v_domingo := v_lunes + 6;
  -- Las sesiones de esa semana (de lunes a domingo, por la fecha en que se hicieron) y las previstas en la semana publicada
  with hechas as (
    select s.id, s.rpe_sesion, s.duracion_min, s.fecha_realizada
    from public.sesiones s join public.semanas w on w.id = s.semana_id join public.bloques b on b.id = w.bloque_id
    where b.atleta_id = p_atleta and s.completada and s.fecha_realizada between v_lunes and v_domingo
  ), previstas as (
    select count(*) as n
    from public.sesiones s join public.semanas w on w.id = s.semana_id join public.bloques b on b.id = w.bloque_id
    where b.atleta_id = p_atleta and w.fecha_inicio = v_lunes and w.programacion = 'programada'
  ), series_sem as (
    select count(*) as series, coalesce(sum(x.kg * x.reps), 0) as kg, avg(x.rpe) filter (where x.rpe > 0) as rpe
    from public.series x join public.sesion_ejercicios se on se.id = x.sesion_ejercicio_id join hechas h on h.id = se.sesion_id
    where x.atleta_id = p_atleta
  )
  select jsonb_build_object(
    'hechas', (select count(*) from hechas), 'previstas', (select n from previstas),
    'rpe_sesion', (select round(avg(rpe_sesion)::numeric, 1) from hechas where rpe_sesion is not null),
    'rpe_series', (select round(rpe::numeric, 1) from series_sem),
    'minutos', (select coalesce(sum(duracion_min), 0) from hechas),
    'series', (select series from series_sem), 'toneladas', (select round(kg / 1000, 1) from series_sem),
    'ultima', (select max(fecha_realizada) from hechas))
  into v_sesiones;
  -- El peso: el último y el de hace 4 semanas (o el más cercano antes)
  select jsonb_build_object('kg', p.kg, 'fecha', p.fecha,
           'cambio_4s', (select round(p.kg - q.kg, 1) from public.pesos q where q.atleta_id = p_atleta and q.fecha <= p.fecha - 28 order by q.fecha desc limit 1))
  into v_peso from public.pesos p where p.atleta_id = p_atleta order by p.fecha desc limit 1;
  select jsonb_build_object('semana', c.semana_inicio, 'creado_en', c.creado_en, 'energia', c.energia, 'motivacion', c.motivacion, 'horas_sueno', c.horas_sueno)
  into v_checkin from public.checkins c where c.atleta_id = p_atleta and c.semana_inicio in (v_lunes, v_lunes - 7) order by c.semana_inicio desc limit 1;
  select count(*) into v_videos from public.archivos a where a.atleta_id = p_atleta and a.tipo = 'video_tecnica' and a.revisado_en is null;
  select count(*) into v_abiertas from public.sesiones_abiertas(p_atleta);
  select count(*) into v_sin_leer from public.comentarios m where m.atleta_id = p_atleta and m.autor = 'atleta' and m.leido_en is null and m.eliminado_en is null;
  return jsonb_build_object('lunes', v_lunes, 'sesiones', v_sesiones, 'peso', v_peso, 'checkin', v_checkin, 'videos_sin_revisar', v_videos,
                            'sesiones_abiertas', v_abiertas, 'sin_leer', case when public.es_coach() then v_sin_leer else null end);
end $$;

-- ---------------------------------------------------------------------
-- 4. Un hábito sugerido, activado por el atleta (hasta 5 activos; el nombre, de la lista de la app)
-- ---------------------------------------------------------------------
create or replace function public.habito_sugerido_activar(p_nombre text, p_tipo text, p_objetivo numeric default null, p_unidad text default null,
                                                           p_sentido text default 'al_menos', p_dias integer default 7, p_icono text default 'libre') returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_atleta uuid := public.mi_atleta_id();
  v_id uuid;
begin
  if v_atleta is null then raise exception 'Solo un atleta activa sus hábitos' using errcode = '42501'; end if;
  -- de uno en uno por atleta (el tope de 5 no se salta con dos peticiones a la vez) y nunca de baja
  if exists (select 1 from public.atletas a where a.id = v_atleta and a.estado = 'baja' for update) then
    raise exception 'Tu cuenta está de baja: puedes ver y descargar tus datos, pero no añadir ni cambiar nada' using errcode = '42501';
  end if;
  perform 1 from public.atletas a where a.id = v_atleta for update;
  if nullif(btrim(coalesce(p_nombre, '')), '') is null or char_length(p_nombre) > 60 then raise exception 'El hábito necesita un nombre (hasta 60 letras)' using errcode = '22023'; end if;
  if p_tipo not in ('numero', 'si_no') then raise exception 'Tipo de hábito no válido' using errcode = '22023'; end if;
  if p_sentido not in ('al_menos', 'como_mucho') then raise exception 'Sentido no válido' using errcode = '22023'; end if;
  if p_dias not between 1 and 7 then raise exception 'Los días a la semana, de 1 a 7' using errcode = '22023'; end if;
  if (select count(*) from public.habitos h where h.atleta_id = v_atleta and h.activo) >= 5 then raise exception 'Como mucho cinco hábitos activos' using errcode = '54000'; end if;
  if exists (select 1 from public.habitos h where h.atleta_id = v_atleta and h.activo and lower(h.nombre) = lower(btrim(p_nombre))) then
    raise exception 'Ya tienes ese hábito' using errcode = '23505';
  end if;
  insert into public.habitos (atleta_id, nombre, tipo, objetivo, unidad, sentido, dias_semana, icono, orden, activo, origen)
  values (v_atleta, btrim(p_nombre), p_tipo, p_objetivo, nullif(btrim(coalesce(p_unidad, '')), ''), p_sentido, p_dias, coalesce(nullif(p_icono, ''), 'libre'),
          (select least(99, coalesce(max(orden), 0) + 1) from public.habitos h where h.atleta_id = v_atleta), true, 'sugerido')
  returning id into v_id;
  return v_id;
end $$;

-- ---------------------------------------------------------------------
-- 5. crear_recordatorios (045), con lo nuevo al final
-- ---------------------------------------------------------------------
-- (045 + 054) Lo de siempre y, al final, cerrar las sesiones que se quedaron abiertas y avisar al coach de los vídeos sin revisar
create or replace function public.crear_recordatorios(p_ahora timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_local timestamp := p_ahora at time zone 'Europe/Madrid';
  v_hoy date := (p_ahora at time zone 'Europe/Madrid')::date;
  v_dow integer := extract(isodow from (p_ahora at time zone 'Europe/Madrid'))::integer;
  v_lunes date;
  v_n integer := 0;
  v_m integer;
  v_titulo text;
  v_cuerpo text;
begin
  perform fbe_privado.solo_servidor();
  v_lunes := v_hoy - (v_dow - 1);

  -- Hoy toca… (solo si planificó el día de la sesión en «Tu plan»). Cada consulta elige primero a quién
  -- (materialized: así la notificación solo se crea para esas filas, sin depender del orden del WHERE)
  with x as materialized (
    select d.perfil_id, d.hora_manana, count(*) as n, min(s.nombre) as nombre
    from fbe_privado.destinatarios d
    join public.atletas a on a.id = d.atleta_id and a.entrenamiento
    join public.bloques b on b.atleta_id = d.atleta_id and not b.es_plantilla and b.estado not in ('cancelado', 'finalizado')
    join public.semanas w on w.bloque_id = b.id and w.programacion = 'programada'
    join public.sesiones s on s.semana_id = w.id and s.dia_previsto = v_hoy and not s.completada
    where not ('sesion_hoy' = any (d.desactivados))
      and v_local >= v_hoy + d.hora_manana and v_local < v_hoy + d.hora_manana + interval '2 hours'
    group by d.perfil_id, d.hora_manana
  )
  select count(*) into v_m from x
  where fbe_privado.notificar_seguro(x.perfil_id, 'sesion_hoy',
          case when x.n = 1 then 'Hoy toca ' || x.nombre else 'Hoy tienes ' || x.n || ' sesiones' end,
          case when x.n = 1 then 'La tienes en Hoy.' else 'Las tienes en Hoy.' end,
          '#hoy', 'recordatorio_sesion:' || v_hoy, p_ahora,
          (v_hoy + x.hora_manana + interval '4 hours') at time zone 'Europe/Madrid');
  v_n := v_n + v_m;

  -- El check-in de la semana (el lunes, el de la semana que acaba de terminar, como en la app)
  with d as materialized (
    select d.perfil_id, d.hora_tarde from fbe_privado.destinatarios d
    where d.salud and not ('checkin' = any (d.desactivados)) and d.dia_checkin = v_dow
      and v_local >= v_hoy + d.hora_tarde and v_local < v_hoy + d.hora_tarde + interval '2 hours'
      and not exists (select 1 from public.checkins c
                      where c.atleta_id = d.atleta_id and c.semana_inicio = case when v_dow = 1 then v_lunes - 7 else v_lunes end)
  )
  select count(*) into v_m from d
  where fbe_privado.notificar_seguro(d.perfil_id, 'checkin', '¿Haces el check-in?',
          case when v_dow = 1 then 'El de la semana pasada aún está pendiente.' else 'El de esta semana aún está pendiente.' end,
          '#checkin', 'recordatorio_checkin:' || v_hoy, p_ahora,
          (v_hoy + d.hora_tarde + interval '4 hours') at time zone 'Europe/Madrid');
  v_n := v_n + v_m;

  -- Por la tarde, una sola: los hábitos que hoy le hacen falta (los diarios sin apuntar y los de x días a la
  -- semana que ya no llegan si se salta hoy) y la nutrición sin apuntar (si tiene plan)
  with x as materialized (
    select * from (
    select d.perfil_id, d.hora_tarde,
      case when 'habitos' = any (d.desactivados) then 0 else (
        select count(*) from public.habitos h
        where h.atleta_id = d.atleta_id and h.activo
          and not exists (select 1 from public.registros_habito r where r.habito_id = h.id and r.fecha = v_hoy)
          and h.dias_semana - (
            select count(*) from public.registros_habito r
            where r.habito_id = h.id and r.fecha >= v_lunes and r.fecha < v_hoy
              and case when h.tipo = 'si_no' then r.valor >= 1
                       when h.sentido = 'al_menos' then r.valor >= h.objetivo
                       else r.valor <= h.objetivo end
          ) >= 8 - v_dow
      ) end as habitos,
      not ('nutricion' = any (d.desactivados))
        and exists (select 1 from public.planes_nutricion pn where pn.atleta_id = d.atleta_id and pn.desde <= v_hoy)
        and exists (select 1 from public.atletas a where a.id = d.atleta_id and a.nutricion)
        and not exists (select 1 from public.registros_nutricion rn where rn.atleta_id = d.atleta_id and rn.fecha = v_hoy) as nutricion
    from fbe_privado.destinatarios d
    where d.salud and v_local >= v_hoy + d.hora_tarde and v_local < v_hoy + d.hora_tarde + interval '2 hours'
    ) y
    where y.habitos > 0 or y.nutricion
  )
  select count(*) into v_m from x
  where fbe_privado.notificar_seguro(x.perfil_id, case when x.habitos > 0 then 'habitos' else 'nutricion' end,
          case when x.habitos > 0 and x.nutricion then
                 case when x.habitos = 1 then 'Te queda un hábito y la nutrición de hoy' else 'Te quedan ' || x.habitos || ' hábitos y la nutrición de hoy' end
               when x.habitos = 1 then 'Te queda un hábito de hoy'
               when x.habitos > 1 then 'Te quedan ' || x.habitos || ' hábitos de hoy'
               else '¿Apuntas lo que has comido hoy?' end,
          case when x.habitos > 0 then 'Apúntalo en Hoy antes de que acabe el día.' else 'Aún no has apuntado la nutrición de hoy.' end,
          '#hoy', 'recordatorio_tarde:' || v_hoy, p_ahora,
          (v_hoy + x.hora_tarde + interval '4 hours') at time zone 'Europe/Madrid');
  v_n := v_n + v_m;

  -- (v0.69, 041) El domingo por la tarde, el resumen de la semana del equipo (una vez: la clave lleva el día)
  -- (revisión) en su propio bloque: si algo falla aquí, no se pierden los demás recordatorios de esa pasada
  begin
  if v_dow = 7 and v_local >= v_hoy + time '19:00' and v_local < v_hoy + time '22:00' and public.comunidad_activa() then
    select t.titulo, t.cuerpo into v_titulo, v_cuerpo
    from fbe_privado.comunidad_resumen_de_la_semana() r
    cross join lateral public.comunidad_texto_resumen(r.sesiones, r.records, r.semana_completa) t;
    if v_titulo is not null then
      with x as materialized (
        select d.perfil_id from fbe_privado.comunidad_dentro d
        union
        select p.id from public.perfiles p where p.rol = 'coach'
      )
      select count(*) into v_m from x
      where fbe_privado.notificar_seguro(x.perfil_id, 'comunidad', v_titulo, v_cuerpo, '#equipo', 'comunidad_resumen:' || v_hoy, p_ahora,
              (v_hoy + time '23:00') at time zone 'Europe/Madrid');
      v_n := v_n + v_m;
    end if;
  end if;
  exception when others then
    raise warning 'FBE: resumen del domingo no creado: %', sqlerrm;
  end;

  -- (v0.70, 042) El sábado por la tarde, a quien aún no ha completado su semana y su compañero de racha sí (también en su
  -- propio bloque: si falla, los demás recordatorios se crean igual)
  begin
  if v_dow = 6 and v_local >= v_hoy + time '19:00' and v_local < v_hoy + time '22:00' and public.comunidad_activa() then
    with sem as materialized (
      select x.atleta_id, x.hechas >= x.previstas as completa
      from fbe_privado.comunidad_semanas_de(array(select d.atleta_id from fbe_privado.comunidad_dentro d
                                                  where exists (select 1 from public.comunidad_companeros c where c.estado = 'aceptada' and d.perfil_id in (c.de, c.para)))) x
      where x.lunes = v_lunes
    ), x as materialized (
      select c.id, a.perfil_id as falta, b.perfil_id as hecho
      from public.comunidad_companeros c
      join fbe_privado.comunidad_dentro a on a.perfil_id in (c.de, c.para)
      join fbe_privado.comunidad_dentro b on b.perfil_id in (c.de, c.para) and b.perfil_id <> a.perfil_id
      join sem sa on sa.atleta_id = a.atleta_id and not sa.completa
      join sem sb on sb.atleta_id = b.atleta_id and sb.completa
      where c.estado = 'aceptada'
        -- (a uno solo de los dos por pareja y semana)
        and not exists (select 1 from public.notificaciones n where n.clave = 'comunidad_pareja:' || c.id || ':' || v_lunes)
    )
    select count(*) into v_m from x
    where fbe_privado.notificar_seguro(x.falta, 'comunidad', fbe_privado.comunidad_nombre(x.hecho) || ' ya ha completado su semana: ¿cerráis la racha?',
            'Míralo en Equipo.', '#equipo', 'comunidad_pareja:' || x.id || ':' || v_lunes, p_ahora,
            (v_hoy + 1 + time '22:00') at time zone 'Europe/Madrid');
    v_n := v_n + v_m;
  end if;
  exception when others then
    raise warning 'FBE: aviso del sábado a las parejas no creado: %', sqlerrm;
  end;
  -- (v0.72, 044) Dos horas antes de un evento, a quien va (y sigue dentro): «A las 19:00: Quedada en el Retiro». Una vez por
  -- persona, evento y hora (si cambia la hora, otro); caduca al empezar. En su propio bloque, como los dos de antes
  begin
  if public.comunidad_activa() then
    with x as materialized (
      select a.perfil_id, e.id, e.titulo, e.empieza_en
      from public.comunidad_eventos e
      join public.comunidad_evento_asistentes a on a.evento_id = e.id and a.va
      join fbe_privado.comunidad_dentro d on d.perfil_id = a.perfil_id
      where e.cancelado_en is null and e.empieza_en > p_ahora and e.empieza_en <= p_ahora + interval '2 hours'
    )
    select count(*) into v_m from x
    where fbe_privado.notificar_seguro(x.perfil_id, 'comunidad', 'A las ' || to_char(x.empieza_en at time zone 'Europe/Madrid', 'FMHH24:MI') || ': ' || x.titulo,
            'Te has apuntado. Míralo en Equipo.', '#equipo', 'comunidad_evento:' || x.id || ':' || floor(extract(epoch from x.empieza_en))::bigint, p_ahora, x.empieza_en);
    v_n := v_n + v_m;
  end if;
  exception when others then
    raise warning 'FBE: recordatorio de los eventos no creado: %', sqlerrm;
  end;

  -- (v0.72, 044) Un aviso o una encuesta programados, al llegar su hora (en el último día): a los de dentro, como al publicarlo
  -- (029), con la misma clave (si se oculta o se borra antes de salir, se retira). En su propio bloque
  begin
  if public.comunidad_activa() then
    with x as materialized (
      select k.id, k.tipo, d.perfil_id,
             coalesce(fbe_privado.nombre_corto((select p.nombre from public.perfiles p where p.id = k.autor_id)), 'Tu coach') as quien
      from public.comunidad_posts k
      join fbe_privado.comunidad_dentro d on d.perfil_id <> k.autor_id
      join public.comunidad_miembros m on m.atleta_id = d.atleta_id
      where k.publicar_en is not null
        -- (solo a quien ya estaba dentro cuando salió: a quien entra después no le llega un aviso de ayer)
        and coalesce(m.entrado_en, m.creado_en) <= k.publicar_en and k.publicar_en <= p_ahora and k.publicar_en > p_ahora - interval '1 day'
        and k.tipo in ('aviso', 'encuesta') and not k.oculta
        and not exists (select 1 from public.notificaciones n where n.usuario_id = d.perfil_id and n.clave = 'comunidad_aviso:' || k.id)
    )
    select count(*) into v_m from x
    where fbe_privado.notificar_seguro(x.perfil_id, 'comunidad',
            x.quien || case when x.tipo = 'encuesta' then ' ha publicado una encuesta en el equipo' else ' ha publicado un aviso en el equipo' end,
            case when x.tipo = 'encuesta' then 'Tócalo para votar en Equipo.' else 'Tócalo para leerlo en Equipo.' end,
            '#equipo', 'comunidad_aviso:' || x.id, p_ahora);
    v_n := v_n + v_m;
  end if;
  exception when others then
    raise warning 'FBE: aviso de lo programado no creado: %', sqlerrm;
  end;

  -- (v0.73, 045) El aniversario en FBE, en el muro, el mismo día (una vez por persona y aniversario). En su propio bloque
  begin
    perform fbe_privado.comunidad_crear_aniversarios(v_hoy);
  exception when others then
    raise warning 'FBE: aniversarios del muro no puestos: %', sqlerrm;
  end;

  -- (v0.73, 045) Al coach, el día antes (de 9:00 a 21:00, Madrid), quién cumple mañana 1 mes, 6 meses o años en FBE (de sus
  -- atletas activos, estén o no en la comunidad): «Mañana Lucía cumple 1 año en FBE 🎉». Una vez por atleta y día; lleva a su chat
  begin
  if v_local >= v_hoy + time '09:00' and v_local < v_hoy + time '21:00' then
    with x as materialized (
      select c.id as coach, a.id as atleta, coalesce(fbe_privado.nombre_corto(a.nombre), 'Alguien') as nombre, m.meses
      from public.atletas a
      join public.perfiles p on p.id = a.perfil_id and p.rol <> 'coach'
      cross join lateral (select public.comunidad_meses_aniversario(a.fecha_alta, v_hoy + 1) as meses) m
      cross join public.perfiles c
      where c.rol = 'coach' and a.estado <> 'baja' and m.meses is not null
    )
    select count(*) into v_m from x
    where fbe_privado.notificar_seguro(x.coach, 'comunidad',
            'Mañana ' || x.nombre || ' cumple ' || case when x.meses = 1 then '1 mes' when x.meses < 12 then x.meses || ' meses' when x.meses = 12 then '1 año'
                                                       else (x.meses / 12) || ' años' end || ' en FBE 🎉',
            'Felicítale mañana en el chat o en Equipo.', '#mensajes/' || x.atleta, 'comunidad_aniversario:' || x.atleta || ':' || (v_hoy + 1), p_ahora,
            (v_hoy + 2) at time zone 'Europe/Madrid');
    v_n := v_n + v_m;
  end if;
  exception when others then
    raise warning 'FBE: aviso de los aniversarios al coach no creado: %', sqlerrm;
  end;

  -- (v0.73, 045) Los momentos de hace más de 24 horas se borran (y su foto va a la cola de Storage). En su propio bloque
  begin
    perform fbe_privado.comunidad_limpiar_momentos(p_ahora);
  exception when others then
    raise warning 'FBE: momentos caducados no borrados: %', sqlerrm;
  end;

  -- (054) Las sesiones que se quedaron sin cerrar (todas las series hechas, 3 horas sin tocar): se cierran solas y se avisa
  begin
    v_m := fbe_privado.sesiones_cerrar_solas(p_ahora);
    v_n := v_n + v_m;
  exception when others then
    raise warning 'FBE: sesiones sin cerrar no cerradas: %', sqlerrm;
  end;

  -- (054) Al coach, por la mañana (10 a 12), los vídeos de técnica que llevan 3 días o más sin revisar: un aviso al día
  begin
    if v_local::time between time '10:00' and time '12:00' then
      with x as materialized (
        select c.id as coach, count(*) as n, min(a.creado_en) as desde
        from public.perfiles c
        cross join public.archivos a
        join public.atletas t on t.id = a.atleta_id and t.estado <> 'baja'
        where c.rol = 'coach' and a.tipo = 'video_tecnica' and a.revisado_en is null and a.creado_en < p_ahora - interval '3 days'
          and not exists (select 1 from public.comentarios m where m.archivo_id = a.id and m.autor = 'coach' and m.eliminado_en is null)
        group by c.id
      )
      select count(*) into v_m from x
      where fbe_privado.notificar_seguro(x.coach, 'video_recibido',
              case when x.n = 1 then 'Un vídeo espera tu revisión' else x.n || ' vídeos esperan tu revisión' end,
              'El más antiguo, desde el ' || to_char(x.desde at time zone 'Europe/Madrid', 'FMDD/FMMM') || '. Los tienes en Revisar.',
              '#revisar', 'videos_pendientes:' || v_hoy, p_ahora, (v_hoy + 1) at time zone 'Europe/Madrid');
      v_n := v_n + v_m;
    end if;
  exception when others then
    raise warning 'FBE: aviso de vídeos sin revisar no creado: %', sqlerrm;
  end;

  return v_n;
end $$;

-- ---------------------------------------------------------------------
-- 6. Permisos (como al final de 003 a 053)
-- ---------------------------------------------------------------------
revoke truncate, references, trigger on all tables in schema public from public, anon, authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated, service_role;
revoke execute on function public.crear_recordatorios(timestamptz), public.notificaciones_por_enviar(integer, boolean),
  public.notificaciones_resultado(jsonb), public.salud_recibir(text, jsonb), public.calendario_de(text) from public, anon, authenticated;
-- (las del reloj, si están)
do $$
declare f text;
begin
  for f in select p.oid::regprocedure::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('reloj_estado', 'reloj_serie', 'reloj_saltar', 'reloj_elegir', 'reloj_terminar') loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
  end loop;
end $$;
revoke all on all functions in schema fbe_privado from public, anon, authenticated;

insert into public.fbe_migraciones (numero) values (54)  -- (3) número de esta migración
  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/055_recetario_equipo.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 055: el recetario del equipo (recetas para todos los atletas)
--
-- Por qué: hasta ahora una receta solo la veía el atleta al que se la asignabas (recetas_atleta), y a quien no le
-- llevas la nutrición no veía ninguna. El recetario del equipo son recetas tuyas que ve todo el mundo: quien solo
-- entrena las consulta, y quien lleva la nutrición contigo puede además apuntarlas en su menú de la semana.
--
-- Qué hace:
--   * recetas.para_todos: la receta la ven todos tus atletas (aunque no esté en su recetario). Solo la marcas tú.
--   * recetas.libro: lo que trae una receta de un recetario escrito (capítulo, bloque, código, la entrada, la nota,
--     dificultad, si se puede cocinar para varios días, las medidas caseras de cada ingrediente…). Es opcional y solo
--     son textos: { "capitulo": "Desayunos", "bloque": "Rápidos", "codigo": "03.01", "descripcion": "…", "nota": "…",
--     "encaje": "…", "dificultad": "Fácil", "batch": "No", "objetivo": "Todos", "rendimiento": "…", "porcion": "…",
--     "tiempo": "3 h (incl. reposo)", "medidas": ["1 envase", null, …] }.
--   * recetas_favoritas: las recetas del equipo que cada atleta se guarda (las de su recetario ya tienen su favorita
--     en recetas_atleta). Las pone y las quita él; tú las ves.
--   * El menú de la semana (menu_comidas) admite, además de las recetas de su recetario, las del equipo.
--
-- Las recetas no van en esta migración: son contenido tuyo y se cargan aparte, con su propio SQL.
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 054 (o con instalar.sql en una base nueva).
-- Se puede repetir sin romper nada.
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 55 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 055 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 55;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 54) then  -- (2) la anterior
    raise exception 'Falta la migración 054 (esta base va por la %). Ejecuta las migraciones en orden.', to_char(coalesce(v, 0), 'FM000');
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. Recetas para todo el equipo y lo que traen de un recetario escrito
-- ---------------------------------------------------------------------
alter table public.recetas add column if not exists para_todos boolean not null default false;
alter table public.recetas add column if not exists libro jsonb;

-- Solo textos cortos con claves conocidas; «medidas», una lista (como mucho, una por ingrediente) de textos o nulos
create or replace function public.receta_libro_valido(j jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(j) = 'object'
    and not exists (
      select 1 from jsonb_each(j) e
      where e.key not in ('capitulo', 'bloque', 'codigo', 'descripcion', 'nota', 'encaje', 'dificultad', 'batch', 'objetivo', 'rendimiento', 'porcion', 'tiempo', 'medidas')
         or (e.key <> 'medidas' and (jsonb_typeof(e.value) <> 'string'
              or char_length(e.value #>> '{}') not between 1 and (case when e.key in ('descripcion', 'nota', 'encaje') then 1200 else 80 end)
              or not public.texto_visible(e.value #>> '{}')))
         or (e.key = 'medidas' and (jsonb_typeof(e.value) <> 'array' or jsonb_array_length(e.value) > 40
              or exists (select 1 from jsonb_array_elements(e.value) m
                         where jsonb_typeof(m) not in ('string', 'null')
                            or (jsonb_typeof(m) = 'string' and (char_length(m #>> '{}') not between 1 and 60 or not public.texto_visible(m #>> '{}'))))))
    )
$$;
alter table public.recetas drop constraint if exists recetas_libro_valido;
alter table public.recetas add constraint recetas_libro_valido check (libro is null or public.receta_libro_valido(libro));
create index if not exists recetas_para_todos_idx on public.recetas (id) where para_todos;

-- El atleta ve las de su recetario y las del equipo
drop policy if exists atleta_ver on public.recetas;
create policy atleta_ver on public.recetas for select to authenticated
  using (
    exists (select 1 from public.recetas_atleta ra where ra.receta_id = recetas.id and ra.atleta_id = public.mi_atleta_id())
    or (para_todos and public.mi_atleta_id() is not null)
  );

-- ---------------------------------------------------------------------
-- 2. El menú admite las recetas del equipo (lo demás, como en la 022)
-- ---------------------------------------------------------------------
create or replace function public.menu_comida_preparar() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op = 'UPDATE' and new.atleta_id is distinct from old.atleta_id then
    raise exception 'Una comida del menú no se puede pasar a otro atleta' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' then new.creado_en := old.creado_en; end if;
  if current_user in ('authenticated', 'anon') then
    if not public.consentimiento_salud_de_atleta(new.atleta_id) then
      raise exception 'Para organizar el menú hace falta el consentimiento de datos de salud del atleta' using errcode = '42501';
    end if;
    if new.receta_id is not null and not public.es_coach()
       and (tg_op = 'INSERT' or new.receta_id is distinct from old.receta_id)
       and not exists (select 1 from public.recetas_atleta ra where ra.atleta_id = new.atleta_id and ra.receta_id = new.receta_id)
       and not exists (select 1 from public.recetas r where r.id = new.receta_id and r.para_todos) then
      raise exception 'Esa receta no está en tu recetario' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------
-- 3. Las recetas del equipo que cada atleta se guarda
-- ---------------------------------------------------------------------
create table if not exists public.recetas_favoritas (
  atleta_id uuid not null references public.atletas (id) on delete cascade,
  receta_id uuid not null references public.recetas (id) on delete cascade,
  creada_en timestamptz not null default now(),
  primary key (atleta_id, receta_id)
);
create index if not exists recetas_favoritas_receta_idx on public.recetas_favoritas (receta_id);

drop trigger if exists recetas_favoritas_exigir_alta on public.recetas_favoritas;
create trigger recetas_favoritas_exigir_alta before insert on public.recetas_favoritas
  for each row execute function public.exigir_alta();

alter table public.recetas_favoritas enable row level security;
drop policy if exists coach_ver on public.recetas_favoritas;
create policy coach_ver on public.recetas_favoritas for select to authenticated
  using (public.es_coach());
drop policy if exists atleta_ver on public.recetas_favoritas;
create policy atleta_ver on public.recetas_favoritas for select to authenticated
  using (atleta_id = public.mi_atleta_id());
-- Solo las suyas y solo recetas del equipo
drop policy if exists atleta_crear on public.recetas_favoritas;
create policy atleta_crear on public.recetas_favoritas for insert to authenticated
  with check (atleta_id = public.mi_atleta_id()
    and exists (select 1 from public.recetas r where r.id = receta_id and r.para_todos));
drop policy if exists atleta_borrar on public.recetas_favoritas;
create policy atleta_borrar on public.recetas_favoritas for delete to authenticated
  using (atleta_id = public.mi_atleta_id());

-- Desde la 019, cada tabla nueva lleva sus permisos a mano (no se cambia: se pone o se quita)
revoke all on public.recetas_favoritas from public, anon, authenticated;
grant select, insert, delete on public.recetas_favoritas to authenticated;
grant execute on function public.receta_libro_valido(jsonb) to authenticated, service_role;

insert into public.fbe_migraciones (numero) values (55)  -- (3) número de esta migración
  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/056_carrera.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 056: la carrera, para quien quiere que le lleves también la parte de correr
--
-- Por qué: hay atletas que preparan una carrera (una media maratón, un trail) a la vez que entrenan fuerza, y su plan de
-- carrera vivía en un PDF aparte. Con esto va en la app, en la misma semana que la fuerza: sus zonas, sus carreras, el
-- macrociclo, cada semana con sus kilómetros, sesiones de carrera estructuradas (calentar, bloque, enfriar, con zona y
-- ritmo), el semáforo antes de entrenar y las revisiones cada dos semanas.
--
-- Qué hace:
--   * atletas.carrera: el coach la enciende al crear la ficha o cuando quiera (Datos). Sin ella, nada de esto se ve.
--   * carrera_atleta (una fila por atleta): el test (fecha y tipo), la FC umbral (LTHR), la FC máxima y en reposo, las
--     zonas si el coach las pone a mano (si no, salen de la LTHR), el ritmo umbral, el plan (nombre, lunes de inicio,
--     fases del macrociclo, sesiones por semana) y una nota (cómo se integra con la fuerza).
--   * carrera_eventos: sus carreras (A, B o C), con fecha, distancia, objetivo, si va o no (y por qué) y el resultado.
--   * carrera_semanas: cada semana del plan (por su lunes): etiqueta, kilómetros, semana A o B de fuerza, la clave y las
--     sesiones previstas (las que el coach pasa luego a la semana de entreno con un toque).
--   * carrera_revisiones: las revisiones del plan (fecha, qué se mira, el criterio verde, la decisión y cómo salió).
--   * carrera_recetas: la biblioteca de sesiones de calidad del coach (solo la ve el coach), con unas de partida.
--   * La pauta de cardio de una sesión (sesiones.cardio) admite ahora el tipo de sesión, rangos (35–45 min, 8–10 km),
--     la zona, el ritmo, las partes (calentar, bloque con repeticiones y recuperación, strides, enfriar) y si es opcional.
--   * Lo que apunta el atleta (sesiones.cardio_hecho) admite los segundos, el desnivel y, solo con su consentimiento de
--     datos de salud, cómo llegó (el semáforo: verde, ámbar o rojo), la FC media y máxima y el dolor (0 a 10): sin él, la
--     base los quita al guardar, los escriba quien los escriba (también el coach), como la preparación de la 005.
--   Todo lo de carrera lo escribe el coach; el atleta ve lo suyo (no la biblioteca de recetas). Va en «Descargar mis
--   datos» y se borra con la ficha.
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 055 (o con instalar.sql en una base nueva).
-- Se puede repetir sin romper nada. (La del reloj, cuando entre, pasa a ser la 057.)
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 56 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 056 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 56;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 55) then  -- (2) la anterior
    raise exception 'Falta la migración 055 (esta base va por la %). Ejecuta las migraciones en orden.', to_char(coalesce(v, 0), 'FM000');
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. El interruptor en la ficha
-- ---------------------------------------------------------------------
alter table public.atletas add column if not exists carrera boolean not null default false;

-- ---------------------------------------------------------------------
-- 2. Comprobaciones de forma (las mismas que hace la app en logica/cardio.js)
-- ---------------------------------------------------------------------
-- Un número entero entre lo y hi (o que no esté)
create or replace function public.json_entero_entre(v jsonb, lo numeric, hi numeric) returns boolean
language sql immutable set search_path = '' as $$
  select v is null or (jsonb_typeof(v) = 'number' and (v #>> '{}')::numeric = floor((v #>> '{}')::numeric) and (v #>> '{}')::numeric between lo and hi)
$$;
-- Un número (con decimales) mayor que lo y hasta hi (o que no esté)
create or replace function public.json_numero_entre(v jsonb, lo numeric, hi numeric) returns boolean
language sql immutable set search_path = '' as $$
  select v is null or (jsonb_typeof(v) = 'number' and (v #>> '{}')::numeric > lo and (v #>> '{}')::numeric <= hi)
$$;
-- Un texto de 1 a n caracteres (o que no esté)
create or replace function public.json_texto_hasta(v jsonb, n integer) returns boolean
language sql immutable set search_path = '' as $$
  select v is null or (jsonb_typeof(v) = 'string' and length(v #>> '{}') between 1 and n)
$$;
-- Un ritmo: uno o dos valores en segundos por km (de 2:00 a 15:00 min/km)
create or replace function public.carrera_ritmo_valido(v jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select v is null or (jsonb_typeof(v) = 'array' and jsonb_array_length(v) between 1 and 2
    and not exists (select 1 from jsonb_array_elements(v) e where not public.json_entero_entre(e, 120, 900)))
$$;

-- Una parte de una sesión de carrera: { "fase": "bloque", "reps": 2, "seg": 360, "zona": 4, "ritmo": [310, 320],
-- "rec_seg": 120, "rec": "trote suave" }. fase obligatoria; duración (seg) o distancia (m) por repetición, o una nota.
create or replace function public.carrera_parte_valida(p jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(p) = 'object'
    and not exists (select 1 from jsonb_object_keys(p) k where k not in ('fase', 'reps', 'seg', 'm', 'zona', 'zona_hasta', 'ritmo', 'rec_seg', 'rec', 'nota'))
    and coalesce(p ->> 'fase', '') in ('calentar', 'bloque', 'strides', 'enfriar', 'libre')
    and (p ? 'seg' or p ? 'm' or p ? 'nota')
    and public.json_entero_entre(p -> 'reps', 1, 50)
    and public.json_entero_entre(p -> 'seg', 5, 21600)
    and public.json_entero_entre(p -> 'm', 10, 100000)
    and public.json_entero_entre(p -> 'zona', 1, 5)
    and public.json_entero_entre(p -> 'zona_hasta', 1, 5)
    and (not (p ? 'zona_hasta') or (p ? 'zona' and (p ->> 'zona_hasta')::int >= (p ->> 'zona')::int))
    and public.carrera_ritmo_valido(p -> 'ritmo')
    and public.json_entero_entre(p -> 'rec_seg', 0, 1800)
    and public.json_texto_hasta(p -> 'rec', 40)
    and public.json_texto_hasta(p -> 'nota', 200)
$$;

-- La pauta de cardio (013, ampliada): modalidad y minutos o km (o partes); lo de carrera, opcional.
--   { "modalidad": "carrera", "tipo": "calidad", "minutos": 50, "minutos_max": 60, "zona": 4, "partes": [...], "opcional": false }
-- exige_volumen = false para una sesión prevista en el plan (carrera_semanas), que puede ir solo con su título.
create or replace function public.cardio_pauta_valida(j jsonb, exige_volumen boolean) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(j) = 'object'
    and length(j::text) <= 6000
    and not exists (select 1 from jsonb_object_keys(j) k where k not in ('modalidad', 'minutos', 'km', 'esfuerzo', 'nota',
                    'tipo', 'minutos_max', 'km_max', 'zona', 'zona_hasta', 'ritmo', 'partes', 'opcional'))
    and coalesce(j ->> 'modalidad', '') in ('carrera', 'andar', 'bici', 'eliptica', 'remo', 'nadar', 'cuerda', 'otro')
    and (not exige_volumen or j ? 'minutos' or j ? 'km' or j ? 'partes')
    and public.json_entero_entre(j -> 'minutos', 1, 600)
    and public.json_numero_entre(j -> 'km', 0, 200)
    and (not (j ? 'esfuerzo') or (jsonb_typeof(j -> 'esfuerzo') = 'number' and (j ->> 'esfuerzo')::numeric between 1 and 10))
    and public.json_texto_hasta(j -> 'nota', 300)
    and (not (j ? 'tipo') or coalesce(j ->> 'tipo', '') in ('facil', 'calidad', 'larga', 'carrera', 'recuperacion', 'cross', 'test', 'tecnica'))
    and public.json_entero_entre(j -> 'minutos_max', 1, 600)
    and (not (j ? 'minutos_max') or (j ? 'minutos' and (j ->> 'minutos_max')::numeric > (j ->> 'minutos')::numeric))
    and public.json_numero_entre(j -> 'km_max', 0, 200)
    and (not (j ? 'km_max') or (j ? 'km' and (j ->> 'km_max')::numeric > (j ->> 'km')::numeric))
    and public.json_entero_entre(j -> 'zona', 1, 5)
    and public.json_entero_entre(j -> 'zona_hasta', 1, 5)
    and (not (j ? 'zona_hasta') or (j ? 'zona' and (j ->> 'zona_hasta')::int >= (j ->> 'zona')::int))
    and public.carrera_ritmo_valido(j -> 'ritmo')
    and (not (j ? 'partes') or (jsonb_typeof(j -> 'partes') = 'array' and jsonb_array_length(j -> 'partes') between 1 and 12
         and not exists (select 1 from jsonb_array_elements(j -> 'partes') p where not public.carrera_parte_valida(p))))
    and (not (j ? 'opcional') or jsonb_typeof(j -> 'opcional') = 'boolean')
$$;

create or replace function public.cardio_valido(j jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select public.cardio_pauta_valida(j, true)
$$;

-- Lo hecho (013, ampliado): { "modalidad": "carrera", "minutos": 58, "seg": 12, "km": 10.2, "desnivel": 80,
-- "semaforo": "verde", "fc_media": 158, "fc_max": 176, "dolor": 0 }. Modalidad y minutos obligatorios.
create or replace function public.cardio_hecho_valido(j jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(j) = 'object'
    and not exists (select 1 from jsonb_object_keys(j) k where k not in ('modalidad', 'minutos', 'km', 'seg', 'desnivel', 'semaforo', 'fc_media', 'fc_max', 'dolor'))
    and coalesce(j ->> 'modalidad', '') in ('carrera', 'andar', 'bici', 'eliptica', 'remo', 'nadar', 'cuerda', 'otro')
    and coalesce(jsonb_typeof(j -> 'minutos'), '') = 'number' and public.json_entero_entre(j -> 'minutos', 1, 600)
    and public.json_numero_entre(j -> 'km', 0, 200)
    and public.json_entero_entre(j -> 'seg', 0, 59)
    and public.json_entero_entre(j -> 'desnivel', 0, 10000)
    and (not (j ? 'semaforo') or coalesce(j ->> 'semaforo', '') in ('verde', 'ambar', 'rojo'))
    and public.json_entero_entre(j -> 'fc_media', 40, 230)
    and public.json_entero_entre(j -> 'fc_max', 40, 240)
    and (not (j ? 'fc_media' and j ? 'fc_max') or (j ->> 'fc_max')::int >= (j ->> 'fc_media')::int)
    and public.json_entero_entre(j -> 'dolor', 0, 10)
$$;

-- Una sesión prevista en el plan: { "tipo": "calidad", "titulo": "Umbral 2 × 6 min", "dia": 3, ...lo de la pauta }.
-- Las de descanso, solo con su título, día y nota.
create or replace function public.carrera_sesion_plan_valida(j jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(j) = 'object'
    and coalesce(j ->> 'tipo', '') in ('facil', 'calidad', 'larga', 'carrera', 'recuperacion', 'cross', 'test', 'tecnica', 'descanso')
    and public.json_texto_hasta(j -> 'titulo', 60)
    and public.json_entero_entre(j -> 'dia', 1, 7)
    and case when j ->> 'tipo' = 'descanso'
      then not exists (select 1 from jsonb_object_keys(j) k where k not in ('tipo', 'titulo', 'dia', 'nota')) and public.json_texto_hasta(j -> 'nota', 300)
      else public.cardio_pauta_valida((j - 'titulo' - 'dia') || jsonb_build_object('modalidad', coalesce(j ->> 'modalidad', 'carrera')), false)
           and (j ? 'titulo' or j ? 'minutos' or j ? 'km' or j ? 'partes')
    end
$$;

-- Las fases del macrociclo: [{ "nombre": "Base", "semanas": 5, "nota": "..." }], de 1 a 12, y 60 semanas como mucho
create or replace function public.carrera_fases_validas(j jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(j) = 'array' and jsonb_array_length(j) between 1 and 12
    and not exists (select 1 from jsonb_array_elements(j) f where jsonb_typeof(f) <> 'object'
      or exists (select 1 from jsonb_object_keys(f) k where k not in ('nombre', 'semanas', 'nota'))
      or not (f ? 'nombre' and f ? 'semanas') or not public.json_texto_hasta(f -> 'nombre', 30)
      or not public.json_entero_entre(f -> 'semanas', 1, 30) or not public.json_texto_hasta(f -> 'nota', 200))
    and (select sum((f ->> 'semanas')::int) from jsonb_array_elements(j) f) <= 60
$$;

alter table public.sesiones drop constraint if exists sesiones_cardio_valido;
alter table public.sesiones add constraint sesiones_cardio_valido check (cardio is null or public.cardio_valido(cardio) is true);
alter table public.sesiones drop constraint if exists sesiones_cardio_hecho_valido;
alter table public.sesiones add constraint sesiones_cardio_hecho_valido check (cardio_hecho is null or public.cardio_hecho_valido(cardio_hecho) is true);

-- La FC, el dolor y cómo llegó (el semáforo) son datos de salud: sin el consentimiento del atleta de esa semana, la base
-- no los guarda (los quita), los escriba quien los escriba, también el coach (como la preparación, 005)
create or replace function public.sesion_carrera_salud() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.cardio_hecho is not null and jsonb_typeof(new.cardio_hecho) = 'object'
     and current_user in ('authenticated', 'anon')
     and new.cardio_hecho ?| array['fc_media', 'fc_max', 'dolor', 'semaforo'] and not public.consentimiento_salud_de_semana(new.semana_id) then
    new.cardio_hecho := new.cardio_hecho - 'fc_media' - 'fc_max' - 'dolor' - 'semaforo';
  end if;
  return new;
end $$;
drop trigger if exists sesiones_carrera_salud on public.sesiones;
create trigger sesiones_carrera_salud before insert or update of cardio_hecho on public.sesiones
  for each row execute function public.sesion_carrera_salud();

-- ---------------------------------------------------------------------
-- 3. Lo de carrera de cada atleta
-- ---------------------------------------------------------------------
create table if not exists public.carrera_atleta (
  atleta_id      uuid primary key references public.atletas(id) on delete cascade,
  lthr           smallint check (lthr between 100 and 230),          -- FC umbral (lactato), ppm
  fc_max         smallint check (fc_max between 100 and 240),
  fc_reposo      smallint check (fc_reposo between 30 and 120),
  test_fecha     date,
  test_tipo      text check (test_tipo in ('friel30', 'campo', 'laboratorio', 'estimado')),
  zonas          smallint[] check (zonas is null or (cardinality(zonas) = 4 and zonas[1] < zonas[2] and zonas[2] < zonas[3] and zonas[3] < zonas[4]
                                                     and zonas[1] >= 60 and zonas[4] <= 240)),  -- dónde empiezan Z2, Z3, Z4 y Z5
  umbral         smallint[] check (umbral is null or (cardinality(umbral) between 1 and 2 and 120 <= all (umbral) and 900 >= all (umbral))),  -- s/km
  plan_nombre    text check (length(plan_nombre) between 1 and 80),
  plan_inicio    date check (plan_inicio is null or extract(isodow from plan_inicio) = 1),
  fases          jsonb check (fases is null or public.carrera_fases_validas(fases)),
  ventanas       smallint check (ventanas between 1 and 7),           -- sesiones de carrera por semana
  nota           text check (length(nota) between 1 and 2000),
  actualizado_en timestamptz not null default now()
);

create table if not exists public.carrera_eventos (
  id              uuid primary key default gen_random_uuid(),
  atleta_id       uuid not null references public.atletas(id) on delete cascade,
  nombre          text not null check (length(nombre) between 1 and 80),
  fecha           date not null,
  distancia_km    numeric(6,2) check (distancia_km > 0 and distancia_km <= 400),
  desnivel_m      integer check (desnivel_m between 0 and 20000),
  prioridad       text not null default 'B' check (prioridad in ('A', 'B', 'C')),
  decision        text not null default 'va' check (decision in ('va', 'entreno', 'no', 'pendiente')),
  objetivo_seg    integer check (objetivo_seg between 60 and 172800),   -- tiempo objetivo
  objetivo_ritmo  smallint check (objetivo_ritmo between 120 and 900),  -- s/km
  nota            text check (length(nota) between 1 and 500),
  resultado_seg   integer check (resultado_seg between 60 and 172800),
  resultado_nota  text check (length(resultado_nota) between 1 and 500),
  creado_en       timestamptz not null default now()
);
create index if not exists carrera_eventos_atleta on public.carrera_eventos (atleta_id, fecha);

create table if not exists public.carrera_semanas (
  atleta_id  uuid not null references public.atletas(id) on delete cascade,
  lunes      date not null check (extract(isodow from lunes) = 1),
  etiqueta   text check (length(etiqueta) between 1 and 24),
  km_min     numeric(5,1) check (km_min >= 0 and km_min <= 400),
  km_max     numeric(5,1) check (km_max > 0 and km_max <= 400),
  ab         text check (ab in ('A', 'B')),
  clave      text check (length(clave) between 1 and 300),
  nota       text check (length(nota) between 1 and 500),
  sesiones   jsonb not null default '[]'::jsonb,
  actualizado_en timestamptz not null default now(),
  primary key (atleta_id, lunes),
  check (km_min is null or km_max is null or km_max >= km_min),
  check (jsonb_typeof(sesiones) = 'array' and jsonb_array_length(sesiones) <= 7 and length(sesiones::text) <= 20000)
);
create or replace function public.carrera_sesiones_plan_validas(j jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select not exists (select 1 from jsonb_array_elements(j) s where not public.carrera_sesion_plan_valida(s))
$$;
alter table public.carrera_semanas drop constraint if exists carrera_semanas_sesiones_validas;
alter table public.carrera_semanas add constraint carrera_semanas_sesiones_validas check (public.carrera_sesiones_plan_validas(sesiones));

create table if not exists public.carrera_revisiones (
  id         uuid primary key default gen_random_uuid(),
  atleta_id  uuid not null references public.atletas(id) on delete cascade,
  fecha      date not null,
  titulo     text not null check (length(titulo) between 1 and 80),
  criterio   text check (length(criterio) between 1 and 300),
  decision   text check (length(decision) between 1 and 500),
  estado     text not null default 'pendiente' check (estado in ('pendiente', 'verde', 'ambar', 'rojo')),
  creado_en  timestamptz not null default now()
);
create index if not exists carrera_revisiones_atleta on public.carrera_revisiones (atleta_id, fecha);

create table if not exists public.carrera_recetas (
  id         uuid primary key default gen_random_uuid(),
  nombre     text not null unique check (length(nombre) between 1 and 80),
  pauta      jsonb not null check (public.cardio_pauta_valida(pauta, true) and pauta ? 'partes'),
  orden      integer not null default 0,
  creado_en  timestamptz not null default now()
);

-- Lo que cambia el coach se fecha solo
create or replace function public.carrera_fechar() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.actualizado_en := now();
  return new;
end $$;
drop trigger if exists carrera_atleta_fechar on public.carrera_atleta;
create trigger carrera_atleta_fechar before update on public.carrera_atleta for each row execute function public.carrera_fechar();
drop trigger if exists carrera_semanas_fechar on public.carrera_semanas;
create trigger carrera_semanas_fechar before update on public.carrera_semanas for each row execute function public.carrera_fechar();

-- ---------------------------------------------------------------------
-- 4. Quién ve y quién cambia: el coach, todo; el atleta, ve lo suyo (no la biblioteca de recetas)
-- ---------------------------------------------------------------------
alter table public.carrera_atleta enable row level security;
alter table public.carrera_eventos enable row level security;
alter table public.carrera_semanas enable row level security;
alter table public.carrera_revisiones enable row level security;
alter table public.carrera_recetas enable row level security;
do $$
declare t text;
begin
  foreach t in array array['carrera_atleta', 'carrera_eventos', 'carrera_semanas', 'carrera_revisiones', 'carrera_recetas'] loop
    execute format('drop policy if exists coach_todo on public.%I', t);
    execute format('create policy coach_todo on public.%I for all to authenticated using (public.es_coach()) with check (public.es_coach())', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
  end loop;
  foreach t in array array['carrera_atleta', 'carrera_eventos', 'carrera_semanas', 'carrera_revisiones'] loop
    execute format('drop policy if exists atleta_ver on public.%I', t);
    execute format('create policy atleta_ver on public.%I for select to authenticated using (atleta_id = public.mi_atleta_id())', t);
  end loop;
end $$;

