  ('2 × 3 km a ritmo objetivo', 9, '{"modalidad":"carrera","tipo":"calidad","minutos":55,"zona":3,"partes":[{"fase":"calentar","seg":900,"zona":1,"zona_hasta":2},{"fase":"bloque","reps":2,"m":3000,"zona":3,"rec_seg":180,"rec":"trote suave","nota":"A tu ritmo de carrera objetivo"},{"fase":"enfriar","seg":600,"zona":1}]}'),
  ('Test de umbral de 30 min', 10, '{"modalidad":"carrera","tipo":"test","minutos":55,"partes":[{"fase":"calentar","seg":900,"zona":1,"zona_hasta":2},{"fase":"bloque","seg":1800,"nota":"Solo, en llano y lo más fuerte que puedas mantener 30 min. Pulsa vuelta a los 10 min: la FC media de los últimos 20 es tu umbral"},{"fase":"enfriar","seg":600,"zona":1}]}')
on conflict (nombre) do nothing;

-- ---------------------------------------------------------------------
-- 6. Permisos (como al final de 003 a 054)
-- ---------------------------------------------------------------------
revoke truncate, references, trigger on all tables in schema public from public, anon, authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated, service_role;
revoke execute on function public.crear_recordatorios(timestamptz), public.notificaciones_por_enviar(integer, boolean),
  public.notificaciones_resultado(jsonb), public.salud_recibir(text, jsonb), public.calendario_de(text) from public, anon, authenticated;
-- (las del reloj, si están)
do $$
declare f text;
begin
  for f in select p.oid::regprocedure::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('reloj_estado', 'reloj_serie', 'reloj_saltar', 'reloj_elegir', 'reloj_terminar') loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
  end loop;
end $$;
revoke all on all functions in schema fbe_privado from public, anon, authenticated;

insert into public.fbe_migraciones (numero) values (56)  -- (3) número de esta migración
  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/057_guias.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 057: las guías del coach y la ficha de técnica de cada ejercicio («Aprende»)
--
-- Por qué: el coach tiene escritas sus guías por grupo muscular (anatomía, lo que importa y lo que no, y una ficha por
-- ejercicio: cómo ejecutarlo, errores típicos, variaciones por nivel, cuándo lo prescribe y con qué repeticiones). Hasta
-- ahora eso vivía en PDF. Con esta migración vive en la app: cada ejercicio de la biblioteca puede llevar su ficha (el
-- atleta la abre desde el ejercicio, en mitad de la sesión) y las guías se leen en «Aprende».
--
-- Qué hace:
--   * guias: una guía (clave, título, subtítulo, grupo muscular, orden y su contenido en bloques: la entrada, una cita,
--     las secciones y las ideas clave). Las escribe el coach; las publicadas las ven todos sus atletas.
--   * fichas_ejercicio: las fichas de una guía, en su orden (nombre y ficha: patrón, músculos, pasos, errores, niveles,
--     cuándo sí y cuándo no, y la tabla de repeticiones, RPE y descanso por objetivo).
--   * ejercicios_fichas: qué ficha lleva cada ejercicio de la biblioteca (una como mucho; varias variantes del mismo
--     ejercicio pueden llevar la misma). Lo decide el coach.
--
-- El contenido no va en esta migración: es del coach y se carga aparte, con su propio SQL.
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 056 (o con instalar.sql en una base nueva).
-- Se puede repetir sin romper nada.
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 57 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 057 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 57;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 56) then  -- (2) la anterior
    raise exception 'Falta la migración 056 (esta base va por la %). Ejecuta las migraciones en orden.', to_char(coalesce(v, 0), 'FM000');
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. Las guías
-- ---------------------------------------------------------------------
create table if not exists public.guias (
  id             uuid primary key default gen_random_uuid(),
  clave          text not null unique,            -- «pectoral», «core»… (para enlazarla y para no duplicarla al cargar)
  titulo         text not null,
  subtitulo      text,
  grupo          text,                            -- el grupo muscular de la app al que corresponde, si lo hay
  orden          smallint not null default 0,
  contenido      jsonb not null default '{}',     -- { entrada, cita, secciones: [{ titulo, subtitulo, bloques, fichas }], ideas: [{ titulo, x }] }
  publicada      boolean not null default true,
  creada_en      timestamptz not null default now(),
  actualizada_en timestamptz not null default now()
);
alter table public.guias drop constraint if exists guias_validas;
alter table public.guias add constraint guias_validas check (
  clave ~ '^[a-z0-9][a-z0-9-]{0,39}$'
  and char_length(titulo) between 1 and 80 and public.texto_visible(titulo)
  and (subtitulo is null or (char_length(subtitulo) between 1 and 160 and public.texto_visible(subtitulo)))
  and (grupo is null or grupo in ('pectoral', 'espalda', 'deltoides', 'cuadriceps', 'gluteo', 'isquiotibiales', 'biceps', 'triceps', 'abdominales', 'gemelo'))
  and orden between 0 and 999
  and jsonb_typeof(contenido) = 'object' and pg_column_size(contenido) <= 200000
);

create table if not exists public.fichas_ejercicio (
  id             uuid primary key default gen_random_uuid(),
  guia_id        uuid not null references public.guias (id) on delete cascade,
  orden          smallint not null default 0,
  nombre         text not null,
  ficha          jsonb not null default '{}',     -- { cabecera, descripcion, foto, patron, principales, secundarios, pasos[], errores[], niveles{}, si, no, tabla[] }
  actualizada_en timestamptz not null default now(),
  unique (guia_id, orden)
);
alter table public.fichas_ejercicio drop constraint if exists fichas_ejercicio_validas;
alter table public.fichas_ejercicio add constraint fichas_ejercicio_validas check (
  char_length(nombre) between 1 and 120 and public.texto_visible(nombre)
  and orden between 0 and 999
  and jsonb_typeof(ficha) = 'object' and pg_column_size(ficha) <= 40000
);
create index if not exists fichas_ejercicio_guia_idx on public.fichas_ejercicio (guia_id, orden);

create table if not exists public.ejercicios_fichas (
  ejercicio_id uuid primary key references public.ejercicios (id) on delete cascade,
  ficha_id     uuid not null references public.fichas_ejercicio (id) on delete cascade,
  creado_en    timestamptz not null default now()
);
create index if not exists ejercicios_fichas_ficha_idx on public.ejercicios_fichas (ficha_id);

-- La fecha del último cambio la pone la base
create or replace function public.guia_tocar() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.actualizada_en := now();
  if tg_op = 'UPDATE' and tg_table_name = 'guias' then new.creada_en := old.creada_en; end if;
  return new;
end $$;
drop trigger if exists guias_tocar on public.guias;
create trigger guias_tocar before insert or update on public.guias
  for each row execute function public.guia_tocar();
drop trigger if exists fichas_ejercicio_tocar on public.fichas_ejercicio;
create trigger fichas_ejercicio_tocar before insert or update on public.fichas_ejercicio
  for each row execute function public.guia_tocar();

-- ---------------------------------------------------------------------
-- 2. Quién ve y escribe qué: el coach, todo; sus atletas, lo publicado (solo leer)
-- ---------------------------------------------------------------------
alter table public.guias enable row level security;
alter table public.fichas_ejercicio enable row level security;
alter table public.ejercicios_fichas enable row level security;

drop policy if exists coach_todo on public.guias;
create policy coach_todo on public.guias for all to authenticated
  using (public.es_coach()) with check (public.es_coach());
drop policy if exists atleta_ver on public.guias;
create policy atleta_ver on public.guias for select to authenticated
  using (publicada and public.mi_atleta_id() is not null);

drop policy if exists coach_todo on public.fichas_ejercicio;
create policy coach_todo on public.fichas_ejercicio for all to authenticated
  using (public.es_coach()) with check (public.es_coach());
-- (la subconsulta pasa por la política de guias: solo las fichas de guías que el atleta puede ver)
drop policy if exists atleta_ver on public.fichas_ejercicio;
create policy atleta_ver on public.fichas_ejercicio for select to authenticated
  using (public.mi_atleta_id() is not null and exists (select 1 from public.guias g where g.id = guia_id));

drop policy if exists coach_todo on public.ejercicios_fichas;
create policy coach_todo on public.ejercicios_fichas for all to authenticated
  using (public.es_coach()) with check (public.es_coach());
drop policy if exists atleta_ver on public.ejercicios_fichas;
create policy atleta_ver on public.ejercicios_fichas for select to authenticated
  using (public.mi_atleta_id() is not null and exists (select 1 from public.fichas_ejercicio f where f.id = ficha_id));

-- Desde la 019, cada tabla nueva lleva sus permisos a mano
revoke all on public.guias, public.fichas_ejercicio, public.ejercicios_fichas from public, anon, authenticated;
grant select, insert, update, delete on public.guias, public.fichas_ejercicio, public.ejercicios_fichas to authenticated;
revoke execute on function public.guia_tocar() from public, anon, authenticated;

insert into public.fbe_migraciones (numero) values (57)  -- (3) número de esta migración
  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/058_modo_reloj.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 058: modo reloj (el entreno desde el Apple Watch, con la app Atajos)
--
-- Por qué: una app web no puede tener app en el Apple Watch (Apple solo deja instalar apps nativas). Pero la app Atajos
-- funciona en el reloj y se puede poner en la esfera. El coach prepara una vez el atajo «FBE Reloj»; cada atleta lo
-- instala con su clave personal y, desde la muñeca, ve la serie que toca («Sentadilla · serie 2 de 4 · 80 kg × 8 ·
-- RIR 2»), la marca como hecha (o cambia los kilos y las repeticiones), salta un ejercicio o termina la sesión. Cada
-- serie se guarda en la base como si la marcara en el móvil, y el atajo arranca el temporizador del descanso.
--
-- Qué hace:
--   * reloj: una fila por atleta con la huella (sha-256) de su clave (nunca la clave), la unidad (kg o lb), la sesión
--     que eligió en el reloj (si eligió una) y los ejercicios que saltó en ella. reloj_mio(), reloj_crear(unidad) (la
--     clave, una vez), reloj_unidad(unidad) y reloj_quitar(): el atleta.
--   * Solo para la función «reloj» (clave de servicio): reloj_estado(clave, sesión) (la sesión que toca con su pauta,
--     lo hecho y su última vez en cada ejercicio), reloj_serie(…) (guarda una serie), reloj_saltar(…), reloj_elegir(…)
--     y reloj_terminar(…) (la marca como hecha con su esfuerzo y su duración).
--   * El atajo del coach: atajos_coach admite también 'reloj' (atajo_guardar, igual que en la 051 con esa clave más).
-- Nadie lee ni escribe la tabla directamente. Al borrar la ficha de un atleta, lo suyo se va con ella. De baja, el
-- reloj no deja apuntar nada. Sin esta migración, la app no enseña el modo reloj y todo lo demás sigue igual.
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 057 (o con instalar.sql en una base
-- nueva). Se puede repetir sin romper nada. (Se escribió como la 052; se integró en la v0.141 como la 058.)
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 58 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 058 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 58;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 57) then  -- (2) la migración previa
    raise exception 'Antes de la 058 hace falta la 057: ejecútala primero (o usa supabase/instalar.sql en una base nueva).';
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. La clave de cada atleta y lo que recuerda el reloj
-- ---------------------------------------------------------------------
create table if not exists public.reloj (
  atleta_id       uuid primary key references public.atletas(id) on delete cascade,
  huella          text not null,
  unidad          text not null default 'kg',
  desde           timestamptz not null default now(),
  ultimo          timestamptz,                  -- la última vez que se usó desde el reloj
  sesion_id       uuid references public.sesiones(id) on delete set null,   -- la que eligió en el reloj
  saltados        uuid[] not null default '{}', -- pautas (sesion_ejercicios) que saltó en esa sesión
  actualizado_en  timestamptz not null default now()
);
alter table public.reloj drop constraint if exists reloj_valido;
alter table public.reloj add constraint reloj_valido check (
  huella ~ '^[0-9a-f]{64}$' and unidad in ('kg', 'lb') and cardinality(saltados) <= 100
);
create unique index if not exists reloj_huella_idx on public.reloj (huella);
comment on table public.reloj is 'Modo reloj (Apple Watch con Atajos): la huella de la clave de cada atleta, su unidad y lo que recuerda el reloj. Solo por sus funciones.';

-- El atajo del coach para el reloj, junto a los de la 051
alter table public.atajos_coach drop constraint if exists atajos_coach_valido;
alter table public.atajos_coach add constraint atajos_coach_valido check (
  clave in ('salud', 'entreno', 'reloj') and url ~ '^https://www\.icloud\.com/shortcuts/[0-9A-Za-z]{16,64}$'
);
create or replace function public.atajo_guardar(p_clave text, p_url text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_url text := nullif(btrim(coalesce(p_url, '')), '');
begin
  if not public.es_coach() then raise exception 'Solo el coach'; end if;
  if p_clave not in ('salud', 'entreno', 'reloj') then raise exception 'Atajo no válido'; end if;
  if v_url is null then delete from public.atajos_coach where clave = p_clave; return; end if;
  insert into public.atajos_coach (clave, url) values (p_clave, v_url)
  on conflict (clave) do update set url = excluded.url, actualizado_en = now();
end $$;
comment on function public.atajo_guardar(text, text) is 'El coach guarda (o, vacío, quita) el enlace de iCloud de uno de sus atajos (salud, entreno o reloj).';

-- ---------------------------------------------------------------------
-- 2. Lo que usa el atleta
-- ---------------------------------------------------------------------
create or replace function public.reloj_mio() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id(); r public.reloj;
begin
  if v_atleta is null then return null; end if;
  select * into r from public.reloj where atleta_id = v_atleta;
  return jsonb_build_object('activo', r.atleta_id is not null, 'desde', r.desde, 'ultimo', r.ultimo, 'unidad', coalesce(r.unidad, 'kg'),
    'sesion_id', r.sesion_id, 'saltados', coalesce(to_jsonb(r.saltados), '[]'::jsonb),
    'atajo', (select a.url from public.atajos_coach a where a.clave = 'reloj'));
end $$;
comment on function public.reloj_mio() is 'El modo reloj del atleta (sin la clave): si lo tiene, desde cuándo, la última vez, su unidad, la sesión elegida y lo saltado en ella, y el atajo de su coach.';

create or replace function public.reloj_crear(p_unidad text default 'kg') returns text
language plpgsql security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id(); v_clave text;
begin
  if v_atleta is null then raise exception 'Solo el atleta conecta lo suyo'; end if;
  if exists (select 1 from public.atletas where id = v_atleta and estado = 'baja') then
    raise exception 'Tu cuenta está de baja: puedes ver y descargar tus datos, pero no añadir ni cambiar nada';
  end if;
  if coalesce(p_unidad, 'kg') not in ('kg', 'lb') then raise exception 'Unidad no válida'; end if;
  v_clave := encode(sha256(convert_to(gen_random_uuid()::text || gen_random_uuid()::text || clock_timestamp()::text, 'UTF8')), 'hex');
  insert into public.reloj (atleta_id, huella, unidad) values (v_atleta, fbe_privado.huella(v_clave), coalesce(p_unidad, 'kg'))
  on conflict (atleta_id) do update set huella = excluded.huella, unidad = excluded.unidad, desde = now(), ultimo = null,
    sesion_id = null, saltados = '{}', actualizado_en = now();
  return v_clave;
end $$;
comment on function public.reloj_crear(text) is 'Crea la clave del modo reloj (la anterior deja de valer) y la devuelve una sola vez.';

create or replace function public.reloj_unidad(p_unidad text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id();
begin
  if v_atleta is null then raise exception 'Solo el atleta cambia lo suyo'; end if;
  if p_unidad not in ('kg', 'lb') then raise exception 'Unidad no válida'; end if;
  update public.reloj set unidad = p_unidad, actualizado_en = now() where atleta_id = v_atleta;
end $$;
comment on function public.reloj_unidad(text) is 'Kilos o libras en el reloj.';

create or replace function public.reloj_quitar() returns void
language plpgsql security definer set search_path = '' as $$
declare v_atleta uuid := public.mi_atleta_id();
begin
  if v_atleta is null then raise exception 'Solo el atleta desconecta lo suyo'; end if;
  delete from public.reloj where atleta_id = v_atleta;
end $$;
comment on function public.reloj_quitar() is 'Quita el modo reloj (la clave deja de valer). Las series que apuntó desde el reloj son suyas y se quedan.';

-- ---------------------------------------------------------------------
-- 3. Solo para la función «reloj» (con la clave de servicio)
-- ---------------------------------------------------------------------
-- El atleta de una clave (si vale y no está de baja). Apunta la última vez.
create or replace function fbe_privado.reloj_de(p_clave text, out r public.reloj, out baja boolean)
language plpgsql security definer set search_path = '' as $$
begin
  baja := false;
  -- (v0.141, revisión) p_clave es ya la HUELLA de la clave: la calcula la función «reloj» (sha-256), así que la base
  -- nunca ve la clave (ni queda en los registros de las llamadas)
  if coalesce(p_clave, '') !~ '^[0-9a-f]{64}$' then return; end if;
  select * into r from public.reloj where huella = p_clave;
  if r.atleta_id is null then return; end if;
  baja := exists (select 1 from public.atletas where id = r.atleta_id and estado = 'baja');
  -- no más de una escritura por minuto solo para apuntar la última vez (y de baja, nada)
  if not baja and (r.ultimo is null or r.ultimo < now() - interval '1 minute') then
    update public.reloj set ultimo = now() where atleta_id = r.atleta_id;
  end if;
end $$;

-- ¿Es suya esta sesión y se puede entrenar? (de una semana publicada de un bloque suyo, no plantilla ni cancelado)
create or replace function fbe_privado.reloj_sesion_valida(p_atleta uuid, p_sesion uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.sesiones s join public.semanas w on w.id = s.semana_id join public.bloques b on b.id = w.bloque_id
                 where s.id = p_sesion and b.atleta_id = p_atleta and not b.es_plantilla and b.estado <> 'cancelado' and w.programacion = 'programada');
$$;

-- La sesión que toca: la elegida (p_sesion o la que recuerda el reloj) si sigue sin hacer; si no, la que tiene series
-- de hoy sin terminar; si no, la de hoy (día previsto); si no, la primera sin hacer de la semana en curso.
create or replace function fbe_privado.reloj_sesion_que_toca(p_atleta uuid, p_elegida uuid) returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare v_hoy date := (now() at time zone 'Europe/Madrid')::date; v uuid;
begin
  if p_elegida is not null and fbe_privado.reloj_sesion_valida(p_atleta, p_elegida)
     and not (select completada from public.sesiones where id = p_elegida) then return p_elegida; end if;
  -- con series de hoy y sin terminar
  select s.id into v from public.series x join public.sesion_ejercicios se on se.id = x.sesion_ejercicio_id join public.sesiones s on s.id = se.sesion_id
    where x.atleta_id = p_atleta and (x.registrada_en at time zone 'Europe/Madrid')::date = v_hoy and not s.completada
      and fbe_privado.reloj_sesion_valida(p_atleta, s.id)
    order by x.registrada_en desc limit 1;
  if v is not null then return v; end if;
  -- las de las semanas publicadas en curso (la más reciente que ya ha empezado)
  select s.id into v from public.sesiones s join public.semanas w on w.id = s.semana_id join public.bloques b on b.id = w.bloque_id
    where b.atleta_id = p_atleta and not b.es_plantilla and b.estado <> 'cancelado' and w.programacion = 'programada' and not s.completada
      and w.fecha_inicio is not null and w.fecha_inicio <= v_hoy
    order by w.fecha_inicio desc, (s.dia_previsto = v_hoy) desc nulls last, s.dia_previsto nulls last, s.orden limit 1;
  return v;
end $$;

create or replace function public.reloj_estado(p_clave text, p_sesion uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  x record; r public.reloj; v_sesion uuid; s public.sesiones; v_salud boolean; v_foco text; v_semana uuid;
begin
  perform fbe_privado.solo_servidor();  -- (revisión) aunque una migración futura se olvide de quitarle el permiso
  select * into x from fbe_privado.reloj_de(p_clave);
  r := x.r;
  if r.atleta_id is null then return jsonb_build_object('ok', false, 'error', 'clave'); end if;
  if x.baja then return jsonb_build_object('ok', false, 'error', 'baja'); end if;
  v_sesion := fbe_privado.reloj_sesion_que_toca(r.atleta_id, coalesce(p_sesion, r.sesion_id));
  -- Al cambiar de sesión, se olvida lo saltado en la anterior
  if v_sesion is distinct from r.sesion_id and cardinality(r.saltados) > 0 then
    update public.reloj set saltados = '{}', sesion_id = null where atleta_id = r.atleta_id;
    r.saltados := '{}';
  end if;
  if v_sesion is null then
    return jsonb_build_object('ok', true, 'unidad', r.unidad, 'sesion', null, 'otras', '[]'::jsonb);
  end if;
  select * into s from public.sesiones where id = v_sesion;
  v_semana := s.semana_id;
  select foco into v_foco from public.semanas where id = v_semana;
  -- (revisión) con la clave de servicio no hay usuario: consentimiento_salud_de_atleta() daría siempre falso
  v_salud := exists (select 1 from public.atletas a join public.consentimientos c on c.perfil_id = a.perfil_id
                     where a.id = r.atleta_id and c.tipo = 'datos_salud' and c.revocado_en is null);
  return jsonb_build_object(
    'ok', true, 'unidad', r.unidad, 'saltados', to_jsonb(r.saltados),
    'progresion_auto', coalesce((select a.progresion_auto from public.atletas a where a.id = r.atleta_id), true),
    'foco', v_foco,
    -- «¿Cómo llegas hoy?» es un dato de salud: sin su consentimiento, no se usa
    'preparacion', case when v_salud then s.preparacion else null end,
    'sesion', jsonb_build_object('id', s.id, 'nombre', s.nombre, 'tipo', s.tipo, 'completada', s.completada, 'dia_previsto', s.dia_previsto, 'con_cardio', s.cardio is not null),
    'ejercicios', coalesce((select jsonb_agg(jsonb_build_object(
        'id', se.id, 'ejercicio_id', se.ejercicio_id, 'orden', se.orden, 'superserie', se.superserie, 'series', se.series,
        'reps_min', se.reps_min, 'reps_max', se.reps_max, 'rir_objetivo', se.rir_objetivo, 'rpe_objetivo', se.rpe_objetivo,
        'carga_sugerida_kg', se.carga_sugerida_kg, 'descanso_seg', se.descanso_seg, 'backoff_pct', se.backoff_pct,
        'series_detalle', se.series_detalle, 'notas_coach', se.notas_coach,
        'ejercicio', jsonb_build_object('id', e.id, 'nombre', e.nombre, 'tipo', to_jsonb(e.tipo))) order by se.orden)
      from public.sesion_ejercicios se join public.ejercicios e on e.id = se.ejercicio_id where se.sesion_id = s.id), '[]'::jsonb),
    'hechas', coalesce((select jsonb_agg(jsonb_build_object('sesion_ejercicio_id', h.sesion_ejercicio_id, 'numero', h.numero, 'kg', h.kg,
        'reps', h.reps, 'rpe', h.rpe, 'rir', h.rir, 'sustituto_id', h.sustituto_id, 'registrada_en', h.registrada_en) order by h.registrada_en)
      from public.series h join public.sesion_ejercicios se on se.id = h.sesion_ejercicio_id where se.sesion_id = s.id), '[]'::jsonb),
    -- Su última vez en cada ejercicio (en otra sesión): las series de aquella sesión y lo que tenía pautado
    'ultimas', coalesce((select jsonb_object_agg(u.ejercicio_id, u.datos) from (
        select pe.ejercicio_id, (
          select jsonb_build_object('sesion_id', ult.sesion_id,
            'series', (select jsonb_agg(jsonb_build_object('numero', z.numero, 'kg', z.kg, 'reps', z.reps, 'rpe', z.rpe, 'rir', z.rir) order by z.numero)
                       from public.series z join public.sesion_ejercicios zp on zp.id = z.sesion_ejercicio_id
                       where zp.sesion_id = ult.sesion_id and coalesce(z.sustituto_id, zp.ejercicio_id) = pe.ejercicio_id and z.atleta_id = r.atleta_id),
            'pauta', case when ult.sustituto_id is null then jsonb_build_object('carga_sugerida_kg', ult.carga_sugerida_kg, 'reps_min', ult.reps_min, 'reps_max', ult.reps_max) end)
          from (select yp.sesion_id, y.sustituto_id, yp.carga_sugerida_kg, yp.reps_min, yp.reps_max
                from public.series y join public.sesion_ejercicios yp on yp.id = y.sesion_ejercicio_id
                where y.atleta_id = r.atleta_id and yp.sesion_id <> s.id and coalesce(y.sustituto_id, yp.ejercicio_id) = pe.ejercicio_id
                order by y.registrada_en desc limit 1) ult) as datos
        from (select distinct se.ejercicio_id from public.sesion_ejercicios se where se.sesion_id = s.id) pe) u where u.datos is not null), '{}'::jsonb),
    -- Las otras sesiones sin hacer de esa semana (para elegir otra desde el reloj)
    'otras', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'nombre', o.nombre, 'tipo', o.tipo) order by o.orden)
      from public.sesiones o where o.semana_id = v_semana and not o.completada and o.id <> s.id), '[]'::jsonb));
end $$;
comment on function public.reloj_estado(text, uuid) is 'Solo la función «reloj»: la sesión que toca de un atleta (con su clave), su pauta, lo hecho y su última vez.';

-- Guarda una serie (como al marcarla en el móvil: si ya estaba, la cambia)
create or replace function public.reloj_serie(p_clave text, p_pauta uuid, p_numero int, p_kg numeric, p_reps int, p_rir numeric default null, p_sustituto uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x record; r public.reloj; v_sesion uuid; v_series int;
begin
  perform fbe_privado.solo_servidor();  -- (revisión) aunque una migración futura se olvide de quitarle el permiso
  select * into x from fbe_privado.reloj_de(p_clave);
  r := x.r;
  if r.atleta_id is null then return jsonb_build_object('ok', false, 'error', 'clave'); end if;
  if x.baja then return jsonb_build_object('ok', false, 'error', 'baja'); end if;
  select se.sesion_id, se.series into v_sesion, v_series from public.sesion_ejercicios se where se.id = p_pauta;
  if v_sesion is null or not fbe_privado.reloj_sesion_valida(r.atleta_id, v_sesion) then return jsonb_build_object('ok', false, 'error', 'sesion'); end if;
  if (select completada from public.sesiones where id = v_sesion) then return jsonb_build_object('ok', false, 'error', 'terminada'); end if;
  if p_numero is null or p_numero < 1 or p_numero > greatest(v_series, 1) + 10 then return jsonb_build_object('ok', false, 'error', 'datos'); end if;
  if (p_kg is not null and (p_kg < 0 or p_kg > 9999)) or (p_reps is not null and (p_reps < 0 or p_reps > 1000)) or (p_rir is not null and (p_rir < 0 or p_rir > 10))
     or (p_kg is null and p_reps is null) then
    return jsonb_build_object('ok', false, 'error', 'datos');
  end if;
  if p_sustituto is not null and not exists (select 1 from public.ejercicios where id = p_sustituto) then p_sustituto := null; end if;
  insert into public.series as z (sesion_ejercicio_id, atleta_id, numero, kg, reps, rir, sustituto_id, nota)
    values (p_pauta, r.atleta_id, p_numero, round(p_kg, 2), p_reps, p_rir, p_sustituto, null)
  on conflict (sesion_ejercicio_id, numero) do update set kg = excluded.kg, reps = excluded.reps, rir = excluded.rir,
    sustituto_id = coalesce(excluded.sustituto_id, z.sustituto_id);  -- (revisión) la hora, la de la primera vez (como en el móvil)
  update public.reloj set sesion_id = v_sesion, actualizado_en = now() where atleta_id = r.atleta_id and sesion_id is distinct from v_sesion;
  return jsonb_build_object('ok', true, 'sesion_id', v_sesion);
end $$;
comment on function public.reloj_serie(text, uuid, int, numeric, int, numeric, uuid) is 'Solo la función «reloj»: guarda una serie del atleta (con su clave).';

create or replace function public.reloj_saltar(p_clave text, p_pauta uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x record; r public.reloj; v_sesion uuid;
begin
  perform fbe_privado.solo_servidor();  -- (revisión) aunque una migración futura se olvide de quitarle el permiso
  select * into x from fbe_privado.reloj_de(p_clave);
  r := x.r;
  if r.atleta_id is null then return jsonb_build_object('ok', false, 'error', 'clave'); end if;
  if x.baja then return jsonb_build_object('ok', false, 'error', 'baja'); end if;
  select se.sesion_id into v_sesion from public.sesion_ejercicios se where se.id = p_pauta;
  if v_sesion is null or not fbe_privado.reloj_sesion_valida(r.atleta_id, v_sesion) then return jsonb_build_object('ok', false, 'error', 'sesion'); end if;
  if (select completada from public.sesiones where id = v_sesion) then return jsonb_build_object('ok', false, 'error', 'terminada'); end if;
  update public.reloj set
    saltados = case when sesion_id is distinct from v_sesion then array[p_pauta] when p_pauta = any(saltados) then saltados else (saltados || p_pauta)[1:100] end,
    sesion_id = v_sesion, actualizado_en = now()
  where atleta_id = r.atleta_id;
  return jsonb_build_object('ok', true);
end $$;
comment on function public.reloj_saltar(text, uuid) is 'Solo la función «reloj»: el atleta salta un ejercicio en el reloj (lo que queda de él ya no se le propone en esa sesión).';

create or replace function public.reloj_elegir(p_clave text, p_sesion uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x record; r public.reloj;
begin
  perform fbe_privado.solo_servidor();  -- (revisión) aunque una migración futura se olvide de quitarle el permiso
  select * into x from fbe_privado.reloj_de(p_clave);
  r := x.r;
  if r.atleta_id is null then return jsonb_build_object('ok', false, 'error', 'clave'); end if;
  if x.baja then return jsonb_build_object('ok', false, 'error', 'baja'); end if;
  if not fbe_privado.reloj_sesion_valida(r.atleta_id, p_sesion) then return jsonb_build_object('ok', false, 'error', 'sesion'); end if;
  update public.reloj set sesion_id = p_sesion, saltados = case when sesion_id is distinct from p_sesion then '{}' else saltados end, actualizado_en = now()
    where atleta_id = r.atleta_id;
  return jsonb_build_object('ok', true);
end $$;
comment on function public.reloj_elegir(text, uuid) is 'Solo la función «reloj»: el atleta elige en el reloj otra sesión de su semana.';

-- La marca como hecha: hoy, con su esfuerzo (1–10) y su duración (de la primera serie a ahora, si no se dice)
create or replace function public.reloj_terminar(p_clave text, p_sesion uuid, p_rpe numeric default null, p_minutos int default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x record; r public.reloj; v_min int; v_primera timestamptz;
begin
  perform fbe_privado.solo_servidor();  -- (revisión) aunque una migración futura se olvide de quitarle el permiso
  select * into x from fbe_privado.reloj_de(p_clave);
  r := x.r;
  if r.atleta_id is null then return jsonb_build_object('ok', false, 'error', 'clave'); end if;
  if x.baja then return jsonb_build_object('ok', false, 'error', 'baja'); end if;
  if not fbe_privado.reloj_sesion_valida(r.atleta_id, p_sesion) then return jsonb_build_object('ok', false, 'error', 'sesion'); end if;
  if (select completada from public.sesiones where id = p_sesion) then return jsonb_build_object('ok', false, 'error', 'terminada'); end if;
  -- (revisión) una sesión con cardio pide sus minutos al terminarla: eso, en la app
  if exists (select 1 from public.sesiones where id = p_sesion and (tipo = 'cardio' or cardio is not null)) then return jsonb_build_object('ok', false, 'error', 'cardio'); end if;
  if p_rpe is not null and (p_rpe < 1 or p_rpe > 10) then return jsonb_build_object('ok', false, 'error', 'datos'); end if;
  select min(h.registrada_en) into v_primera from public.series h join public.sesion_ejercicios se on se.id = h.sesion_ejercicio_id where se.sesion_id = p_sesion;
  v_min := coalesce(p_minutos, case when v_primera is not null then ceil(extract(epoch from now() - v_primera) / 60)::int end);
  if v_min is not null and (v_min < 1 or v_min > 600) then v_min := null; end if;
  update public.sesiones set completada = true, fecha_realizada = coalesce(fecha_realizada, (now() at time zone 'Europe/Madrid')::date),
    rpe_sesion = coalesce(round(p_rpe, 1), rpe_sesion), duracion_min = coalesce(v_min, duracion_min)
  where id = p_sesion;
  update public.reloj set sesion_id = null, saltados = '{}', actualizado_en = now() where atleta_id = r.atleta_id;
  return jsonb_build_object('ok', true, 'minutos', v_min);
end $$;
comment on function public.reloj_terminar(text, uuid, numeric, int) is 'Solo la función «reloj»: el atleta termina la sesión desde el reloj.';

-- Nadie toca la tabla directamente
alter table public.reloj enable row level security;
revoke all on public.reloj from public, anon, authenticated;

-- Permisos (como al final de 003 a 056). Lo de la función «reloj», solo la clave de servicio.
revoke truncate, references, trigger on all tables in schema public from public, anon, authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated, service_role;
revoke execute on function public.crear_recordatorios(timestamptz), public.notificaciones_por_enviar(integer, boolean),
  public.notificaciones_resultado(jsonb), public.salud_recibir(text, jsonb), public.calendario_de(text),
  public.reloj_estado(text, uuid), public.reloj_serie(text, uuid, int, numeric, int, numeric, uuid), public.reloj_saltar(text, uuid),
  public.reloj_elegir(text, uuid), public.reloj_terminar(text, uuid, numeric, int), public.guia_tocar() from public, anon, authenticated;
revoke all on all functions in schema fbe_privado from public, anon, authenticated;

insert into public.fbe_migraciones (numero) values (58)  -- (3) número de esta migración
  on conflict (numero) do update set aplicada_en = excluded.aplicada_en;

-- ============================== migraciones/059_youtube.sql ==============================
-- =====================================================================
-- FBE Equipo, migración 059: YouTube dentro de la app
--
-- Por qué: los vídeos del coach (la técnica de cada ejercicio, sus vídeos de YouTube, sus directos) se ven ya dentro de
-- la app, con su reproductor. Esta migración añade lo poco que necesita guardarse en la base:
--
--   * recursos.destacado: el «vídeo de la semana», que sale en Hoy (uno como mucho, para todos).
--   * recursos.directo_en: un directo de YouTube con su día y hora (sale en Hoy desde el día antes hasta 3 h después).
--   * youtube_canal: el canal de YouTube del coach (una fila), para enseñar sus últimos vídeos en «Aprende».
--   * sesiones.video_url y video_titulo: «sigue este vídeo» en una sesión (un calentamiento, movilidad, un cardio).
--   * videos_vistos: qué vídeos de YouTube ha visto cada atleta dentro de la app (cuántas veces, cuánto y si hasta el
--     final), para que el coach sepa si ha visto lo que le mandó y qué vídeos funcionan. Solo lo apunta el propio
--     atleta, con apuntar_video_visto(); lo ven él y su coach; se borra con su ficha.
--
-- El tramo de un vídeo («del 0:42 al 0:58») no necesita nada: va dentro del propio enlace (t= y end=).
--
-- Se ejecuta en el SQL Editor después de schema.sql y las migraciones 002 a 057 (o con instalar.sql en una base nueva);
-- con o sin la 058 (el reloj). Se puede repetir sin romper nada. (Si la 058 se quiere poner después: «delete from
-- public.fbe_migraciones where numero = 59;», la 058 y otra vez esta.)
-- =====================================================================

do $$
declare v smallint;
begin
  select max(numero) into v from public.fbe_migraciones;
  if v > 59 then  -- (1) número de esta migración
    raise exception 'Esta base ya tiene la migración %: repetir la 059 desharía sus cambios. Ejecuta solo las que te falten.', to_char(v, 'FM000')
      using hint = 'Si de verdad hace falta repetirla: ejecuta antes «delete from public.fbe_migraciones where numero > 59;» y, después de ella, todas las siguientes en orden.';
  end if;
  if not exists (select 1 from public.fbe_migraciones where numero = 57) then  -- (2) la anterior (la 058, el reloj, no hace falta)
    raise exception 'Falta la migración 057 (esta base va por la %). Ejecuta las migraciones en orden.', to_char(coalesce(v, 0), 'FM000');
  end if;
end $$;

-- Un enlace de YouTube (o de youtu.be) razonable: https, sin espacios, como mucho 300 caracteres
create or replace function public.es_enlace_youtube(u text) returns boolean
language sql immutable set search_path = public as $$
  select u is not null and char_length(u) <= 300 and u !~ '\s'
    and u ~* '^https://((www|m)\.)?(youtube\.com|youtube-nocookie\.com|youtu\.be)/'
$$;

-- ---------------------------------------------------------------------
-- 1. Recursos: el vídeo de la semana y los directos
-- ---------------------------------------------------------------------
alter table public.recursos add column if not exists destacado boolean not null default false;
alter table public.recursos add column if not exists directo_en timestamptz;
alter table public.recursos drop constraint if exists recursos_youtube_validos;
alter table public.recursos add constraint recursos_youtube_validos check (
  (not destacado or (atleta_id is null and public.es_enlace_youtube(url)))
  and (directo_en is null or (public.es_enlace_youtube(url) and directo_en between '2024-01-01' and '2100-01-01'))
);
-- Uno como mucho a la vez
create unique index if not exists recursos_un_destacado on public.recursos ((true)) where destacado;

-- ---------------------------------------------------------------------
-- 2. El canal de YouTube del coach (una fila)
-- ---------------------------------------------------------------------
create table if not exists public.youtube_canal (
  id             boolean primary key default true check (id),
  canal          text not null,                    -- el id del canal (UC…) o su @nombre
  titulo         text,                             -- cómo se llama (si el coach lo pone; la función usa el del canal)
  activo         boolean not null default true,    -- si sus vídeos salen en «Aprende»
  actualizado_en timestamptz not null default now()
);
alter table public.youtube_canal drop constraint if exists youtube_canal_valido;
alter table public.youtube_canal add constraint youtube_canal_valido check (
  (canal ~ '^UC[A-Za-z0-9_-]{22}$' or canal ~ '^@[A-Za-z0-9._-]{3,30}$')
  and (titulo is null or (char_length(titulo) between 1 and 100 and public.texto_visible(titulo)))
);

-- ---------------------------------------------------------------------
-- 3. «Sigue este vídeo» en una sesión
-- ---------------------------------------------------------------------
alter table public.sesiones add column if not exists video_url text;
alter table public.sesiones add column if not exists video_titulo text;
alter table public.sesiones drop constraint if exists sesiones_video_valido;
alter table public.sesiones add constraint sesiones_video_valido check (
  (video_url is null or public.es_enlace_youtube(video_url))
  and (video_titulo is null or (video_url is not null and char_length(video_titulo) between 1 and 80 and public.texto_visible(video_titulo)))
);
-- Solo el coach lo pone o lo quita (el atleta puede marcar su sesión, pero no cambiar su vídeo)
create or replace function public.sesion_video_proteger() returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user in ('authenticated', 'anon') and not public.es_coach()
     and (new.video_url, new.video_titulo) is distinct from (old.video_url, old.video_titulo) then
    raise exception 'Solo el coach puede cambiar el vídeo de la sesión' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists sesiones_video_proteger on public.sesiones;
create trigger sesiones_video_proteger before update of video_url, video_titulo on public.sesiones
  for each row execute function public.sesion_video_proteger();

-- ---------------------------------------------------------------------
-- 4. Lo que ve cada atleta
-- ---------------------------------------------------------------------
create table if not exists public.videos_vistos (
  atleta_id   uuid not null references public.atletas(id) on delete cascade,
  video       text not null,                      -- el id del vídeo de YouTube (11 caracteres)
  titulo      text,                               -- cómo se llamaba donde lo vio («Técnica: sentadilla»)
  veces       integer not null default 1,         -- cuántas veces (otra vez = pasada media hora desde la última)
  segundos    integer not null default 0,         -- lo visto en total
  completo    boolean not null default false,     -- si alguna vez lo vio hasta el final (o casi)
  primera_vez timestamptz not null default now(),
  ultima_vez  timestamptz not null default now(),
  primary key (atleta_id, video)
);
alter table public.videos_vistos drop constraint if exists videos_vistos_validos;
alter table public.videos_vistos add constraint videos_vistos_validos check (
  video ~ '^[A-Za-z0-9_-]{11}$'
  and (titulo is null or (char_length(titulo) between 1 and 120 and public.texto_visible(titulo)))
  and veces between 1 and 100000 and segundos between 0 and 100000000
);
create index if not exists videos_vistos_video_idx on public.videos_vistos (video);

-- El atleta apunta lo que ha visto (no escribe la tabla directamente: así no toca lo de otro; lo visto lo dice su app)
create or replace function public.apuntar_video_visto(p_video text, p_titulo text default null, p_segundos integer default 0, p_completo boolean default false)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_atleta uuid := public.mi_atleta_id();
  v_titulo text := nullif(left(regexp_replace(coalesce(p_titulo, ''), '\s+', ' ', 'g'), 120), '');
  v_seg integer := least(greatest(coalesce(p_segundos, 0), 0), 21600);
begin
  if v_atleta is null then return; end if;  -- el coach (o una cuenta sin ficha): no se apunta nada
  -- (al integrarla) de baja, como en la 050, 051 y 054: puede ver y descargar lo suyo, pero no se apunta nada nuevo
  if exists (select 1 from public.atletas where id = v_atleta and estado = 'baja') then return; end if;
  if p_video is null or p_video !~ '^[A-Za-z0-9_-]{11}$' then
    raise exception 'Ese no es un vídeo de YouTube' using errcode = '22023';
  end if;
  -- (al integrarla) como mucho 5000 vídeos distintos por atleta (lo ya apuntado se sigue sumando)
  if (select count(*) from public.videos_vistos where atleta_id = v_atleta) >= 5000
     and not exists (select 1 from public.videos_vistos where atleta_id = v_atleta and video = p_video) then return; end if;
  if v_titulo is not null and not public.texto_visible(v_titulo) then v_titulo := null; end if;
  insert into public.videos_vistos as x (atleta_id, video, titulo, segundos, completo)
    values (v_atleta, p_video, v_titulo, v_seg, coalesce(p_completo, false))
  on conflict (atleta_id, video) do update set
    titulo = coalesce(excluded.titulo, x.titulo),
    veces = least(x.veces + case when x.ultima_vez < now() - interval '30 minutes' then 1 else 0 end, 100000),
    segundos = least(x.segundos + excluded.segundos, 100000000),
    completo = x.completo or excluded.completo,
    ultima_vez = now();
end $$;

-- ---------------------------------------------------------------------
-- 5. Quién ve qué
-- ---------------------------------------------------------------------
alter table public.youtube_canal enable row level security;
alter table public.videos_vistos enable row level security;

drop policy if exists coach_todo on public.youtube_canal;
create policy coach_todo on public.youtube_canal for all to authenticated
  using (public.es_coach()) with check (public.es_coach());
